    /// Run a state publication while the exact execution launch owner remains
    /// current. This closes the stale-waiter window for side effects such as a
    /// signed project HEAD compare-and-swap.
    pub fn with_state_db_owned<F, T>(&self, thread_id: &str, launch_owner: &str, f: F) -> Result<T>
    where
        F: FnOnce(&StateDb) -> Result<T>,
    {
        let g = self.lock()?;
        let claim = g
            .runtime_db
            .get_launch_claim(thread_id)?
            .ok_or_else(|| anyhow!("thread {thread_id} has no current launch owner"))?;
        if claim.claimed_by != launch_owner {
            bail!("stale launch owner cannot publish state for thread {thread_id}");
        }
        f(&g.state_db)
    }

    /// Strict, non-mutating verification of the selected projection against a
    /// stable snapshot of trusted heads and CAS.
    pub fn verify_projection_generation(
        &self,
    ) -> Result<ryeos_state::rebuild::ProjectionVerificationReport> {
        let _fork_sensitive_descriptors = lillux::try_retain_fork_sensitive_descriptors()?;
        let _cas_guard = self
            .state_authority
            .acquire_exclusive_guard(!self.read_only)?;
        let _write_permit = self
            .write_barrier
            .acquire_with_timeout(crate::write_barrier::ONLINE_WRITE_PERMIT_TIMEOUT)
            .map_err(|error| {
                anyhow!("cannot acquire write permit for projection verification: {error}")
            })?;
        let mut g = self.lock()?;
        g.state_db.verify_projection_generation()
    }

    /// Publish a freshly rebuilt projection generation and switch
    /// this live store to it. The offline service path still obeys the global
    /// mutation hierarchy so no direct/import publisher can overlap the head
    /// snapshot or generation publication.
    pub fn rebuild_projection_generation(&self) -> Result<ryeos_state::rebuild::RebuildReport> {
        if !self.allow_projection_rebuild {
            bail!(
                "projection rebuild is available only in the authored offline rebuild bootstrap mode"
            );
        }
        let _fork_sensitive_descriptors = lillux::try_retain_fork_sensitive_descriptors()?;
        let cas_guard = self.state_authority.acquire_exclusive_guard(true)?;
        let _write_permit = self
            .write_barrier
            .acquire_with_timeout(crate::write_barrier::ONLINE_WRITE_PERMIT_TIMEOUT)
            .map_err(|error| {
                anyhow!("cannot acquire write permit for projection rebuild: {error}")
            })?;
        let mut g = self.lock()?;
        let Inner {
            state_db,
            runtime_db,
            ..
        } = &mut *g;
        state_db.rebuild_projection_generation_admitted(Some(&*runtime_db), &cas_guard)
    }

    /// Consume a staged remote chain import through the normal mutation
    /// hierarchy. The CAS guard is acquired before the StateStore mutex and is
    /// passed into the journaled head publisher; StateDb never reacquires it
    /// from beneath the mutex.
    pub fn finalize_staged_chain_import(
        &self,
        staged: ryeos_state::sync::StagedChainImport,
    ) -> Result<ryeos_state::sync::ImportResult> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        ryeos_state::sync::finalize_import(
            &g.state_db,
            staged,
            g.signer.as_ref(),
            permit.cas_guard(),
        )
    }

    /// Publish the large, secret-free source launch ledger under a bounded
    /// CAS manifest and create the existing sync-job row that pins it. CAS
    /// publication precedes the SQLite root inside one write-permit window;
    /// a crash in the narrow gap leaves only collectable unreachable bytes,
    /// never a job naming absent authority.
    pub fn create_worker_handoff_source_job(
        &self,
        prepared: &crate::worker_handoff::PreparedPlacementTransferManifest,
        job: &ryeos_state::NewSyncJob,
        progress: &crate::worker_handoff::WorkerSessionHandoffProgress,
    ) -> Result<ryeos_state::SyncJobRecord> {
        prepared.object.validate()?;
        progress.validate()?;
        let manifest_hash = prepared.object_hash()?;
        if job.operation_type != crate::worker_handoff::WORKER_SESSION_HANDOFF_OPERATION
            || !job.roots.iter().any(|hash| hash == &manifest_hash)
            || progress.phase != crate::worker_handoff::WorkerHandoffPhase::SourceExported
        {
            bail!("source-exported worker handoff job does not pin its transfer manifest");
        }
        let operation = crate::worker_handoff::WorkerSessionHandoffJobOperation::from_value(
            job.operation.clone(),
        )?;
        if operation.role != crate::worker_handoff::WorkerHandoffJobRole::Source
            || operation.operation_id != progress.operation_id
        {
            bail!("source-exported progress belongs to another handoff operation");
        }
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if let Some(existing) = g.state_db.get_sync_job(&job.job_id)? {
            if existing.operation_type != job.operation_type
                || existing.operation != job.operation
                || !existing.roots.iter().any(|hash| hash == &manifest_hash)
            {
                bail!("worker handoff job identity is already bound to another operation");
            }
            return Ok(existing);
        }
        if let Some((existing, existing_operation)) =
            active_source_worker_handoff_for_placement_in_db(
                &g.state_db,
                &operation.source_placement_thread_id,
            )?
        {
            bail!(
                "source placement {} is already fenced by active handoff {} ({})",
                operation.source_placement_thread_id,
                existing_operation.operation_id,
                existing.job_id
            );
        }
        self.state_authority.ensure_guard(permit.cas_guard())?;
        let cas = self.state_authority.cas_store()?;
        let object_value = prepared.object.to_value()?;
        let stored_manifest = cas.put_object(&object_value)?;
        if stored_manifest.hash != manifest_hash {
            bail!("stored placement transfer manifest digest changed");
        }
        g.state_db
            .record_cas_entry(&ryeos_state::NewCasEntryAttribution {
                hash: manifest_hash,
                entry_kind: ryeos_state::CasEntryKind::Object,
                bytes: u64::try_from(lillux::canonical_json(&object_value)?.len())?,
                source_principal: Some(format!("fp:{}", g.signer.fingerprint())),
                source_peer: None,
                job_id: Some(job.job_id.clone()),
                state: ryeos_state::CasEntryState::Local,
            })?;
        let progress_value = progress.to_value()?;
        g.state_db.create_sync_job_with_initial_progress(
            job,
            ryeos_state::SyncJobState::Running,
            progress.phase.as_str(),
            Some(&progress_value),
        )
    }

    /// Win the target's pre-cut prepare/abort branch before any source
    /// contact. The exact abort head is retained in the existing sync-job head
    /// coordinate, so a crash cannot reopen prepare/adopt or let a retry name
    /// a different source successor.
    pub fn claim_worker_handoff_target_abort(
        &self,
        requested_job: &ryeos_state::NewSyncJob,
        abort_chain_head_hash: &str,
    ) -> Result<ryeos_state::SyncJobRecord> {
        ryeos_state::objects::thread_snapshot::validate_canonical_hash(
            "target abort claim head",
            abort_chain_head_hash,
        )?;
        let requested_operation =
            crate::worker_handoff::WorkerSessionHandoffJobOperation::from_value(
                requested_job.operation.clone(),
            )?;
        if requested_job.operation_type != crate::worker_handoff::WORKER_SESSION_HANDOFF_OPERATION
            || requested_operation.role != crate::worker_handoff::WorkerHandoffJobRole::Target
            || !requested_job.roots.is_empty()
        {
            bail!("target abort claim is not an exact target handoff job");
        }
        let g = self.lock()?;
        if let Some(existing) = g.state_db.get_sync_job(&requested_job.job_id)? {
            if existing.operation_type != requested_job.operation_type
                || existing.operation != requested_job.operation
                || existing.peer != requested_job.peer
                || existing.max_attempts != requested_job.max_attempts
            {
                bail!("target abort claim conflicts with another durable operation");
            }
            if existing.state == ryeos_state::SyncJobState::Cancelled {
                if existing.heads != [abort_chain_head_hash] {
                    bail!("target abort retry changed its terminal source head");
                }
                return Ok(existing);
            }
            if matches!(
                existing.state,
                ryeos_state::SyncJobState::Completed | ryeos_state::SyncJobState::Failed
            ) {
                bail!("terminal target handoff cannot enter the abort branch");
            }
            let progress = existing
                .result
                .clone()
                .map(crate::worker_handoff::WorkerSessionHandoffProgress::from_value)
                .transpose()?;
            if existing.phase == crate::worker_handoff::WORKER_HANDOFF_TARGET_ABORT_CLAIM_PHASE
                || progress.as_ref().is_some_and(|progress| {
                    progress.phase == crate::worker_handoff::WorkerHandoffPhase::AbortAuthorized
                })
            {
                if existing.heads != [abort_chain_head_hash] {
                    bail!("target abort retry changed its durably claimed source head");
                }
                return Ok(existing);
            }
            if progress.as_ref().is_some_and(|progress| {
                !matches!(
                    progress.phase,
                    crate::worker_handoff::WorkerHandoffPhase::Planned
                        | crate::worker_handoff::WorkerHandoffPhase::TargetPrepared
                )
            }) {
                bail!("target handoff already crossed the abortable pre-cut branch");
            }
            g.state_db.update_sync_job(
                &requested_job.job_id,
                &ryeos_state::SyncJobUpdate {
                    state: ryeos_state::SyncJobState::Running,
                    phase: crate::worker_handoff::WORKER_HANDOFF_TARGET_ABORT_CLAIM_PHASE
                        .to_owned(),
                    roots: None,
                    heads: Some(vec![abort_chain_head_hash.to_owned()]),
                    uploaded_hashes: existing.uploaded_hashes,
                    fetched_hashes: existing.fetched_hashes,
                    last_error: None,
                    result: existing.result,
                },
            )?;
            return g
                .state_db
                .get_sync_job(&requested_job.job_id)?
                .ok_or_else(|| anyhow!("target abort claim disappeared after publication"));
        }
        let progress = crate::worker_handoff::WorkerSessionHandoffProgress::planned(
            requested_operation.operation_id,
        )?;
        let mut job = requested_job.clone();
        job.heads = vec![abort_chain_head_hash.to_owned()];
        g.state_db.create_sync_job_with_initial_progress(
            &job,
            ryeos_state::SyncJobState::Running,
            crate::worker_handoff::WORKER_HANDOFF_TARGET_ABORT_CLAIM_PHASE,
            Some(&progress.to_value()?),
        )
    }

    /// Resolve the exact target-node-owned terminal-branch object for one
    /// operation. Callers still have to parse the closed adoption/abort
    /// evidence; this helper only prevents service responses from naming a
    /// mutable job row or an unowned/missing CAS object.
    pub fn worker_handoff_target_branch_hash(&self, operation_id: &str) -> Result<Option<String>> {
        ryeos_state::objects::thread_snapshot::validate_canonical_hash(
            "worker handoff target-branch operation",
            operation_id,
        )?;
        let signer = self.lock()?.signer.clone();
        let Some(head) = self.with_state_db(|db| {
            db.read_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                operation_id,
            )
        })?
        else {
            return Ok(None);
        };
        if head.signer != signer.fingerprint() {
            bail!("worker handoff target branch is not owned by this node");
        }
        let authority = self.pinned_state_authority()?;
        let guard = authority.acquire_shared_guard()?;
        authority.ensure_guard(&guard)?;
        if authority
            .cas_store()?
            .get_object(&head.target_hash)?
            .is_none()
        {
            bail!("worker handoff target-branch object is absent");
        }
        Ok(Some(head.target_hash))
    }

    /// Decode the exact mutually exclusive target terminal branch. The
    /// permanent generic head, rather than an operational job row, selects
    /// adoption, source abort, proved pre-attachment completion, or failure.
    pub fn worker_handoff_target_terminal(
        &self,
        operation_id: &str,
    ) -> Result<Option<crate::worker_handoff::WorkerHandoffTargetTerminalEvidence>> {
        ryeos_state::objects::thread_snapshot::validate_canonical_hash(
            "worker handoff target-terminal operation",
            operation_id,
        )?;
        let signer = self.lock()?.signer.clone();
        let Some(head) = self.with_state_db(|db| {
            db.read_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                operation_id,
            )
        })?
        else {
            return Ok(None);
        };
        if head.signer != signer.fingerprint() {
            bail!("worker handoff target terminal is not owned by this node");
        }
        let authority = self.pinned_state_authority()?;
        let guard = authority.acquire_shared_guard()?;
        authority.ensure_guard(&guard)?;
        let value = authority
            .cas_store()?
            .get_object(&head.target_hash)?
            .ok_or_else(|| anyhow!("worker handoff target-terminal object is absent"))?;
        let attestation = ryeos_state::objects::Attestation::from_value(&value)?;
        let terminal =
            crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::from_attestation(
                &attestation,
                &signer.verifying_key(),
            )?;
        let retained_operation_id = match &terminal {
            crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Adoption(evidence) => {
                &evidence.target_operation.operation_id
            }
            crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Abort(evidence) => {
                &evidence.target_operation.operation_id
            }
            crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Completion(evidence) => {
                &evidence.target_operation.operation_id
            }
            crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Failure(evidence) => {
                &evidence.target_operation.operation_id
            }
        };
        if retained_operation_id != operation_id {
            bail!("worker handoff target-terminal head names another operation");
        }
        Ok(Some(terminal))
    }

    /// Read the permanent target-node-signed abort fence for one operation.
    /// The generic head, not a terminal sync-job retention window, owns the
    /// refusal authority against a delayed or replayed target prepare.
    pub fn worker_handoff_abort_fence(
        &self,
        operation_id: &str,
    ) -> Result<Option<crate::worker_handoff::WorkerHandoffAbortFenceEvidence>> {
        match self.worker_handoff_target_terminal(operation_id)? {
            None => Ok(None),
            Some(crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Abort(evidence)) => {
                Ok(Some(evidence))
            }
            Some(_) => bail!("worker handoff abort conflicts with another target branch"),
        }
    }

    /// Read the target-node-signed terminal adoption receipt for one exact
    /// handoff operation. Unlike the operational sync-job, this authority is
    /// retained by a signed generic head and remains available for exact
    /// response replay after ordinary terminal-job collection.
    pub fn worker_handoff_adoption_receipt(
        &self,
        operation_id: &str,
    ) -> Result<Option<crate::worker_handoff::WorkerHandoffAdoptionReceiptEvidence>> {
        match self.worker_handoff_target_terminal(operation_id)? {
            None => Ok(None),
            Some(crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Adoption(
                evidence,
            )) => Ok(Some(evidence)),
            Some(_) => bail!("worker handoff adoption conflicts with another target branch"),
        }
    }

    pub fn worker_handoff_terminal_failure(
        &self,
        operation_id: &str,
    ) -> Result<Option<crate::worker_handoff::WorkerHandoffTerminalFailureEvidence>> {
        match self.worker_handoff_target_terminal(operation_id)? {
            None => Ok(None),
            Some(crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Failure(evidence)) => {
                Ok(Some(evidence))
            }
            Some(_) => bail!("worker handoff failure conflicts with another target branch"),
        }
    }

    pub fn worker_handoff_terminal_completion(
        &self,
        operation_id: &str,
    ) -> Result<Option<crate::worker_handoff::WorkerHandoffTerminalCompletionEvidence>> {
        match self.worker_handoff_target_terminal(operation_id)? {
            None => Ok(None),
            Some(crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Completion(
                evidence,
            )) => Ok(Some(evidence)),
            Some(_) => bail!("worker handoff completion conflicts with another target branch"),
        }
    }

    /// Publish the immutable target-side adoption receipt after the exact
    /// successor attachment has been observed. The receipt is deliberately
    /// separate from both the worker event chain and terminal sync-job: a
    /// worker may exit immediately after attachment, and operational jobs
    /// retain only bounded history.
    pub fn publish_worker_handoff_adoption_receipt(
        &self,
        job_id: &str,
        target_operation: &crate::worker_handoff::WorkerSessionHandoffJobOperation,
        request: &crate::worker_handoff::WorkerPlacementAdoptRequest,
        response: &crate::worker_handoff::WorkerPlacementAdoptResponse,
    ) -> Result<String> {
        let job = self
            .with_state_db(|db| db.get_sync_job(job_id))?
            .context("worker handoff adoption receipt lost its operational job")?;
        let progress = crate::worker_handoff::WorkerSessionHandoffProgress::from_value(
            job.result
                .clone()
                .context("worker handoff adoption receipt job has no progress")?,
        )?;
        crate::worker_handoff::validate_projected_target_adoption(
            &job,
            target_operation,
            &progress,
            request,
        )?;
        let evidence = crate::worker_handoff::WorkerHandoffAdoptionReceiptEvidence::new(
            target_operation.clone(),
            request.clone(),
            response.clone(),
        )?;
        if let Some(existing) =
            self.worker_handoff_adoption_receipt(&target_operation.operation_id)?
        {
            if existing != evidence {
                bail!("worker handoff adoption receipt contradicts its existing operation");
            }
            return self
                .with_state_db(|db| {
                    db.read_generic_head_ref(
                        crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                        &target_operation.operation_id,
                    )
                })?
                .map(|head| head.target_hash)
                .ok_or_else(|| anyhow!("worker handoff adoption receipt disappeared"));
        }

        let permit = self.acquire_write_permit()?;
        let previous = self.with_state_db(|db| {
            db.read_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
            )
        })?;
        if previous.is_some() {
            drop(permit);
            let existing = self
                .worker_handoff_adoption_receipt(&target_operation.operation_id)?
                .ok_or_else(|| anyhow!("worker handoff adoption receipt disappeared"))?;
            if existing != evidence {
                bail!("worker handoff adoption receipt contradicts its existing operation");
            }
            return self
                .with_state_db(|db| {
                    db.read_generic_head_ref(
                        crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                        &target_operation.operation_id,
                    )
                })?
                .map(|head| head.target_hash)
                .ok_or_else(|| anyhow!("worker handoff adoption receipt disappeared"));
        }

        let signer = self.lock()?.signer.clone();
        let attestation = evidence.sign_attestation(signer.as_ref())?;
        let authority = self.pinned_state_authority()?;
        authority.ensure_guard(permit.cas_guard())?;
        let cas = authority.cas_store()?;
        let mut stage = authority
            .require_recovery()?
            .begin_staged_cas_roots_admitted(
                permit.cas_guard(),
                "worker-handoff-adoption-receipt",
            )?;
        let attestation_hash =
            stage.store_object_admitted(permit.cas_guard(), &cas, &attestation.to_value())?;
        stage.protect_object_hash_admitted(permit.cas_guard(), &attestation_hash)?;
        self.with_state_db(|db| {
            db.advance_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
                &attestation_hash,
                None,
                signer.as_ref(),
                permit.cas_guard(),
            )
        })?;
        if let Err(error) = stage.finish_admitted(permit.cas_guard()) {
            tracing::warn!(
                %error,
                operation_id = %target_operation.operation_id,
                "worker handoff adoption receipt published while temporary roots remained recoverable"
            );
        }
        Ok(attestation_hash)
    }

    /// Publish immutable target-signed failure testimony only after the exact
    /// successor terminal and cleanup disposition have been proved by the
    /// target lifecycle owner. The shared target-branch namespace prevents a
    /// failure from coexisting with adoption or source abort.
    pub fn publish_worker_handoff_terminal_failure(
        &self,
        target_operation: &crate::worker_handoff::WorkerSessionHandoffJobOperation,
        request: &crate::worker_handoff::WorkerPlacementAdoptRequest,
        failure: &crate::worker_handoff::WorkerPlacementFailureResponse,
    ) -> Result<String> {
        let evidence = crate::worker_handoff::WorkerHandoffTerminalFailureEvidence::new(
            target_operation.clone(),
            request.clone(),
            failure.clone(),
        )?;
        if let Some(existing) =
            self.worker_handoff_target_terminal(&target_operation.operation_id)?
        {
            match existing {
                crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Failure(existing)
                    if existing == evidence =>
                {
                    return self
                        .worker_handoff_target_branch_hash(&target_operation.operation_id)?
                        .ok_or_else(|| anyhow!("worker handoff terminal failure disappeared"));
                }
                _ => bail!("worker handoff terminal failure conflicts with another target branch"),
            }
        }

        let permit = self.acquire_write_permit()?;
        let previous = self.with_state_db(|db| {
            db.read_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
            )
        })?;
        if previous.is_some() {
            drop(permit);
            let existing = self
                .worker_handoff_terminal_failure(&target_operation.operation_id)?
                .ok_or_else(|| anyhow!("worker handoff terminal failure disappeared"))?;
            if existing != evidence {
                bail!("worker handoff terminal failure changed its existing operation");
            }
            return self
                .worker_handoff_target_branch_hash(&target_operation.operation_id)?
                .ok_or_else(|| anyhow!("worker handoff terminal failure disappeared"));
        }

        let signer = self.lock()?.signer.clone();
        let attestation = evidence.sign_attestation(signer.as_ref())?;
        let authority = self.pinned_state_authority()?;
        authority.ensure_guard(permit.cas_guard())?;
        let cas = authority.cas_store()?;
        let mut stage = authority
            .require_recovery()?
            .begin_staged_cas_roots_admitted(
                permit.cas_guard(),
                "worker-handoff-terminal-failure",
            )?;
        let attestation_hash =
            stage.store_object_admitted(permit.cas_guard(), &cas, &attestation.to_value())?;
        stage.protect_object_hash_admitted(permit.cas_guard(), &attestation_hash)?;
        self.with_state_db(|db| {
            db.advance_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
                &attestation_hash,
                None,
                signer.as_ref(),
                permit.cas_guard(),
            )
        })?;
        if let Err(error) = stage.finish_admitted(permit.cas_guard()) {
            tracing::warn!(
                %error,
                operation_id = %target_operation.operation_id,
                "worker handoff terminal failure published while temporary roots remained recoverable"
            );
        }
        Ok(attestation_hash)
    }

    /// Publish immutable target-signed successful terminal testimony when the
    /// successor completes after writer transfer but before the attachment
    /// projection. The same one-operation branch head makes this mutually
    /// exclusive with attachment, source abort, and terminal failure.
    pub fn publish_worker_handoff_terminal_completion(
        &self,
        target_operation: &crate::worker_handoff::WorkerSessionHandoffJobOperation,
        request: &crate::worker_handoff::WorkerPlacementAdoptRequest,
        completion: &crate::worker_handoff::WorkerPlacementCompletionResponse,
    ) -> Result<String> {
        let evidence = crate::worker_handoff::WorkerHandoffTerminalCompletionEvidence::new(
            target_operation.clone(),
            request.clone(),
            completion.clone(),
        )?;
        if let Some(existing) =
            self.worker_handoff_target_terminal(&target_operation.operation_id)?
        {
            match existing {
                crate::worker_handoff::WorkerHandoffTargetTerminalEvidence::Completion(
                    existing,
                ) if existing == evidence => {
                    return self
                        .worker_handoff_target_branch_hash(&target_operation.operation_id)?
                        .ok_or_else(|| anyhow!("worker handoff terminal completion disappeared"));
                }
                _ => {
                    bail!("worker handoff terminal completion conflicts with another target branch")
                }
            }
        }

        let permit = self.acquire_write_permit()?;
        let previous = self.with_state_db(|db| {
            db.read_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
            )
        })?;
        if previous.is_some() {
            drop(permit);
            let existing = self
                .worker_handoff_terminal_completion(&target_operation.operation_id)?
                .ok_or_else(|| anyhow!("worker handoff terminal completion disappeared"))?;
            if existing != evidence {
                bail!("worker handoff terminal completion changed its existing operation");
            }
            return self
                .worker_handoff_target_branch_hash(&target_operation.operation_id)?
                .ok_or_else(|| anyhow!("worker handoff terminal completion disappeared"));
        }

        let signer = self.lock()?.signer.clone();
        let attestation = evidence.sign_attestation(signer.as_ref())?;
        let authority = self.pinned_state_authority()?;
        authority.ensure_guard(permit.cas_guard())?;
        let cas = authority.cas_store()?;
        let mut stage = authority
            .require_recovery()?
            .begin_staged_cas_roots_admitted(
                permit.cas_guard(),
                "worker-handoff-terminal-completion",
            )?;
        let attestation_hash =
            stage.store_object_admitted(permit.cas_guard(), &cas, &attestation.to_value())?;
        stage.protect_object_hash_admitted(permit.cas_guard(), &attestation_hash)?;
        self.with_state_db(|db| {
            db.advance_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
                &attestation_hash,
                None,
                signer.as_ref(),
                permit.cas_guard(),
            )
        })?;
        if let Err(error) = stage.finish_admitted(permit.cas_guard()) {
            tracing::warn!(
                %error,
                operation_id = %target_operation.operation_id,
                "worker handoff terminal completion published while temporary roots remained recoverable"
            );
        }
        Ok(attestation_hash)
    }

    /// Publish the permanent target-side abort fence through the existing CAS
    /// staging and node-signed generic-head authorities. Replays must reproduce
    /// the exact source operation and abort head.
    pub fn publish_worker_handoff_abort_fence(
        &self,
        target_operation: &crate::worker_handoff::WorkerSessionHandoffJobOperation,
        abort_chain_head_hash: &str,
    ) -> Result<String> {
        self.publish_worker_handoff_abort_fence_evidence(
            target_operation,
            abort_chain_head_hash,
            None,
        )
    }

    /// Advance an already-authorized abort fence to its terminal cleanup
    /// receipt. This signed generic head remains replay authority after the
    /// operational sync-job reaches its ordinary retention horizon.
    pub fn publish_worker_handoff_abort_terminal_receipt(
        &self,
        target_operation: &crate::worker_handoff::WorkerSessionHandoffJobOperation,
        abort_chain_head_hash: &str,
        disposition: &str,
    ) -> Result<String> {
        self.publish_worker_handoff_abort_fence_evidence(
            target_operation,
            abort_chain_head_hash,
            Some(disposition.to_owned()),
        )
    }

    fn publish_worker_handoff_abort_fence_evidence(
        &self,
        target_operation: &crate::worker_handoff::WorkerSessionHandoffJobOperation,
        abort_chain_head_hash: &str,
        terminal_disposition: Option<String>,
    ) -> Result<String> {
        let evidence = crate::worker_handoff::WorkerHandoffAbortFenceEvidence::new(
            target_operation.clone(),
            abort_chain_head_hash.to_owned(),
            terminal_disposition,
        )?;
        let permit = self.acquire_write_permit()?;
        let previous = self.with_state_db(|db| {
            db.read_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
            )
        })?;
        let signer = self.lock()?.signer.clone();
        let attestation = evidence.sign_attestation(signer.as_ref())?;
        let authority = self.pinned_state_authority()?;
        authority.ensure_guard(permit.cas_guard())?;
        let cas = authority.cas_store()?;
        if let Some(previous) = &previous {
            if previous.signer != signer.fingerprint() {
                bail!("worker handoff target branch is not owned by this node");
            }
            let value = cas
                .get_object(&previous.target_hash)?
                .ok_or_else(|| anyhow!("worker handoff target-branch object is absent"))?;
            let attestation = ryeos_state::objects::Attestation::from_value(&value)?;
            let existing =
                crate::worker_handoff::WorkerHandoffAbortFenceEvidence::from_attestation(
                    &attestation,
                    &signer.verifying_key(),
                )
                .context("worker handoff abort cannot replace the competing target branch")?;
            if existing.target_operation != evidence.target_operation
                || existing.abort_chain_head_hash != evidence.abort_chain_head_hash
            {
                bail!("worker handoff abort fence contradicts its existing operation");
            }
            if evidence.terminal_disposition.is_none()
                || existing.terminal_disposition == evidence.terminal_disposition
            {
                return Ok(previous.target_hash.clone());
            }
            if existing.terminal_disposition.is_some() {
                bail!("worker handoff abort receipt changed its terminal disposition");
            }
        } else if evidence.terminal_disposition.is_some() {
            bail!("worker handoff abort terminal receipt has no provisional branch fence");
        }
        let mut stage = authority
            .require_recovery()?
            .begin_staged_cas_roots_admitted(permit.cas_guard(), "worker-handoff-abort-fence")?;
        let attestation_hash =
            stage.store_object_admitted(permit.cas_guard(), &cas, &attestation.to_value())?;
        stage.protect_object_hash_admitted(permit.cas_guard(), &attestation_hash)?;
        self.with_state_db(|db| {
            db.advance_generic_head_ref(
                crate::worker_handoff::WORKER_HANDOFF_TARGET_BRANCH_HEAD_NAMESPACE,
                &target_operation.operation_id,
                &attestation_hash,
                previous.as_ref().map(|head| head.target_hash.as_str()),
                signer.as_ref(),
                permit.cas_guard(),
            )
        })?;
        if let Err(error) = stage.finish_admitted(permit.cas_guard()) {
            tracing::warn!(
                %error,
                operation_id = %target_operation.operation_id,
                "worker handoff abort fence published while temporary roots remained recoverable"
            );
        }
        Ok(attestation_hash)
    }

    /// Complete a non-authoritative worker-placement preflight. The signed
    /// receipt is rooted by the existing sync job, but no chain head,
    /// credential reservation, or runnable placement is created here.
    pub fn complete_worker_handoff_preflight(
        &self,
        job_id: &str,
        attempt_id: &str,
        attestation: &ryeos_state::objects::Attestation,
        result: Value,
    ) -> Result<String> {
        attestation.validate()?;
        if attestation.policy != crate::worker_handoff::WORKER_PLACEMENT_PREFLIGHT_POLICY
            || attestation.claim != crate::worker_handoff::WORKER_PLACEMENT_PREFLIGHT_CLAIM
        {
            bail!("worker handoff preflight receipt has another policy");
        }
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let job = g
            .state_db
            .get_sync_job(job_id)?
            .ok_or_else(|| anyhow!("worker handoff preflight job does not exist"))?;
        if job.operation_type != crate::worker_handoff::WORKER_SESSION_HANDOFF_PREFLIGHT_OPERATION {
            bail!("sync job is not a worker handoff preflight");
        }
        self.state_authority.ensure_guard(permit.cas_guard())?;
        let value = attestation.to_value();
        let expected = ryeos_state::objects::canonical_value_digest(&value)?;
        let stored = self.state_authority.cas_store()?.put_object(&value)?;
        if stored.hash != expected {
            bail!("stored worker handoff preflight receipt digest changed");
        }
        g.state_db
            .record_cas_entry(&ryeos_state::NewCasEntryAttribution {
                hash: expected.clone(),
                entry_kind: ryeos_state::CasEntryKind::Object,
                bytes: u64::try_from(lillux::canonical_json(&value)?.len())?,
                source_principal: Some(format!("fp:{}", g.signer.fingerprint())),
                source_peer: None,
                job_id: Some(job_id.to_owned()),
                state: ryeos_state::CasEntryState::Local,
            })?;
        let mut roots = job.roots;
        roots.push(expected.clone());
        roots.sort();
        roots.dedup();
        g.state_db.finish_sync_job_attempt_and_update_job(
            attempt_id,
            &ryeos_state::FinishSyncJobAttempt {
                state: ryeos_state::SyncJobAttemptState::Completed,
                phase: "preflight_complete".to_owned(),
                error: None,
                result: Some(result.clone()),
            },
            job_id,
            &ryeos_state::SyncJobUpdate {
                state: ryeos_state::SyncJobState::Completed,
                phase: "preflight_complete".to_owned(),
                roots: Some(roots),
                heads: None,
                uploaded_hashes: job.uploaded_hashes,
                fetched_hashes: job.fetched_hashes,
                last_error: None,
                result: Some(result),
            },
        )?;
        Ok(expected)
    }

    /// Settle process-local sync attempts before daemon recovery creates any
    /// replacement attempt. Jobs remain durable and retryable.
    pub fn reconcile_interrupted_sync_job_attempts(&self) -> Result<usize> {
        let g = self.lock()?;
        g.state_db.reconcile_interrupted_sync_job_attempts()
    }

    /// Import one digest-verified sync payload as staged CAS data and create
    /// the job that roots it before releasing the shared mutation guard. This
    /// is the generic crash-safe boundary used by remote workflows that must
    /// inspect a closure before deciding whether it may become authority.
    pub fn stage_sync_payload_and_create_job(
        &self,
        payload: &ryeos_state::sync::ExportPayload,
        attribution: &ryeos_state::sync::ImportAttribution,
        job: &ryeos_state::NewSyncJob,
    ) -> Result<(ryeos_state::sync::ImportResult, ryeos_state::SyncJobRecord)> {
        if !job
            .roots
            .iter()
            .all(|root| payload.entries.iter().any(|entry| &entry.hash == root))
        {
            bail!("sync job roots are not all present in its staged transfer payload");
        }
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if let Some(existing) = g.state_db.get_sync_job(&job.job_id)? {
            if existing.operation_type != job.operation_type
                || existing.operation != job.operation
                || existing.peer != job.peer
                || existing.max_attempts != job.max_attempts
                || !job
                    .roots
                    .iter()
                    .all(|root| existing.roots.iter().any(|existing| existing == root))
            {
                bail!("staged sync job identity is already bound to another operation");
            }
            // `roots` may grow as signed receipts are published and `heads`
            // may advance as the durable workflow progresses. The immutable
            // operation and initial roots above identify an idempotent re-drive;
            // comparing the mutable frontier would make every completed job
            // unreplayable.
            return Ok((ryeos_state::sync::ImportResult::default(), existing));
        }
        let import = ryeos_state::sync::import_objects_staged(
            &g.state_db,
            payload,
            attribution,
            permit.cas_guard(),
        )?;
        if import.hash_mismatches != 0 {
            bail!(
                "staged sync payload contained {} digest mismatch(es)",
                import.hash_mismatches
            );
        }
        let job = g.state_db.create_sync_job(job)?;
        Ok((import, job))
    }

    pub fn stage_sync_payload_for_existing_job(
        &self,
        payload: &ryeos_state::sync::ExportPayload,
        attribution: &ryeos_state::sync::ImportAttribution,
        job_id: &str,
        phase: &str,
        additional_roots: &[String],
        progress: Option<Value>,
    ) -> Result<ryeos_state::sync::ImportResult> {
        self.stage_verified_sync_payload_for_existing_job(
            payload,
            attribution,
            job_id,
            phase,
            additional_roots,
            progress,
            |_| Ok(()),
        )
    }

    /// Import a remote payload, prove its caller-owned semantic contract, and
    /// only then make any of its hashes durable job roots. The verifier runs
    /// while the exact CAS mutation authority and StateStore lock remain held,
    /// so rejected bytes cannot race GC or become retry/recovery authority.
    /// This boundary is deliberately schema-blind: the caller supplies the
    /// proof over the pinned CAS view.
    #[allow(clippy::too_many_arguments)]
    pub fn stage_verified_sync_payload_for_existing_job<F>(
        &self,
        payload: &ryeos_state::sync::ExportPayload,
        attribution: &ryeos_state::sync::ImportAttribution,
        job_id: &str,
        phase: &str,
        additional_roots: &[String],
        progress: Option<Value>,
        verify: F,
    ) -> Result<ryeos_state::sync::ImportResult>
    where
        F: FnOnce(&lillux::CasStore) -> Result<()>,
    {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let job = g
            .state_db
            .get_sync_job(job_id)?
            .ok_or_else(|| anyhow!("sync job does not exist"))?;
        if !additional_roots.iter().all(|root| {
            job.roots.iter().any(|existing| existing == root)
                || payload.entries.iter().any(|entry| &entry.hash == root)
        }) {
            bail!(
                "existing sync job additional roots are absent from its durable roots and payload"
            );
        }
        let import = ryeos_state::sync::import_objects_staged(
            &g.state_db,
            payload,
            attribution,
            permit.cas_guard(),
        )?;
        if import.hash_mismatches != 0 {
            bail!("existing sync job import contained digest mismatches");
        }
        let authority = g.state_db.pinned_authority()?;
        authority.ensure_guard(permit.cas_guard())?;
        let cas = authority.cas_store()?;
        verify(&cas)?;
        let mut roots = job.roots;
        roots.extend(additional_roots.iter().cloned());
        roots.sort();
        roots.dedup();
        let mut fetched_hashes = job.fetched_hashes;
        fetched_hashes.extend(
            additional_roots
                .iter()
                .filter(|root| payload.entries.iter().any(|entry| &entry.hash == *root))
                .cloned(),
        );
        fetched_hashes.sort();
        fetched_hashes.dedup();
        g.state_db.update_sync_job(
            job_id,
            &ryeos_state::SyncJobUpdate {
                state: ryeos_state::SyncJobState::Running,
                phase: phase.to_owned(),
                roots: Some(roots),
                heads: None,
                uploaded_hashes: job.uploaded_hashes,
                fetched_hashes,
                last_error: None,
                result: progress,
            },
        )?;
        Ok(import)
    }

    /// Publish a prebuilt node-signed admission object through the generic
    /// admission index while holding the StateStore mutation hierarchy. The
    /// state layer remains blind to the evidence schema.
    pub fn publish_admission_attestation(
        &self,
        attestation: &ryeos_state::objects::Attestation,
        limits: ryeos_state::object_closure::ObjectClosureLimits,
    ) -> Result<ryeos_state::admission::AdmissionResult> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        ryeos_state::admission::publish_admission_attestation(
            &g.state_db,
            attestation,
            limits,
            g.signer.as_ref(),
            permit.cas_guard(),
        )
    }

    /// Atomically make one prepared target placement fetchable and record its
    /// durable job phase. The capsule and recovery seed become CAS roots before
    /// the signed placement admission/head is exposed; the returned hash is
    /// therefore never a promise about collectable or absent bytes.
    pub fn publish_worker_placement_preparation(
        &self,
        job_id: &str,
        transfer_manifest_hash: &str,
        target_capsule: &ryeos_state::objects::AdmittedLaunchCapsule,
        prepared_seed: &crate::worker_handoff::PreparedPlacementRuntimeSeed,
        attestation: &ryeos_state::objects::Attestation,
        progress: &crate::worker_handoff::WorkerSessionHandoffProgress,
        admission_limits: ryeos_state::object_closure::ObjectClosureLimits,
    ) -> Result<ryeos_state::admission::AdmissionResult> {
        target_capsule.validate()?;
        prepared_seed.object.validate()?;
        progress.validate()?;
        let capsule_hash = target_capsule.content_hash()?;
        let seed_hash = prepared_seed.object_hash()?;
        if attestation.subject_hash != capsule_hash
            || progress.placement_attestation_hash.is_none()
            || progress.target_runtime_seed_hash.as_deref() != Some(seed_hash.as_str())
        {
            bail!("target placement publication operands contradict one another");
        }
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let job = g
            .state_db
            .get_sync_job(job_id)?
            .ok_or_else(|| anyhow!("target worker handoff job does not exist"))?;
        let current_progress =
            validate_target_preparation_job_transition(&job, transfer_manifest_hash, progress)?;
        self.state_authority.ensure_guard(permit.cas_guard())?;
        let cas = self.state_authority.cas_store()?;
        let target_capsule_bytes = target_capsule.to_canonical_bytes()?;
        if cas.store_canonical_object_bytes_bounded(
            &target_capsule_bytes,
            ryeos_state::objects::MAX_ADMITTED_LAUNCH_CAPSULE_BYTES,
        )? != capsule_hash
        {
            bail!("stored target placement capsule digest changed");
        }
        if cas.put_blob(&prepared_seed.launch_metadata_bytes)?.hash
            != prepared_seed.object.launch_metadata_blob_hash
        {
            bail!("stored target placement runtime metadata digest changed");
        }
        if cas.put_object(&prepared_seed.object.to_value()?)?.hash != seed_hash {
            bail!("stored target placement runtime seed digest changed");
        }
        let admission = ryeos_state::admission::publish_admission_attestation(
            &g.state_db,
            attestation,
            admission_limits,
            g.signer.as_ref(),
            permit.cas_guard(),
        )?;
        let mut stored_progress = progress.clone();
        stored_progress.placement_attestation_hash = Some(admission.attestation_hash.clone());
        stored_progress.validate()?;
        let mut retained_roots = job.roots.clone();
        retained_roots.extend([
            transfer_manifest_hash.to_owned(),
            capsule_hash,
            seed_hash,
            admission.attestation_hash.clone(),
        ]);
        retained_roots.sort();
        retained_roots.dedup();
        if let Some(current) = current_progress
            && current.phase == crate::worker_handoff::WorkerHandoffPhase::TargetPrepared
        {
            if current != stored_progress || retained_roots != job.roots || job.heads.is_empty() {
                bail!("replayed target preparation differs from its durable publication");
            }
            return Ok(admission);
        }
        g.state_db.update_sync_job(
            job_id,
            &ryeos_state::SyncJobUpdate {
                state: ryeos_state::SyncJobState::Running,
                phase: progress.phase.as_str().to_owned(),
                roots: Some(retained_roots),
                heads: None,
                uploaded_hashes: Vec::new(),
                fetched_hashes: job.roots,
                last_error: None,
                result: Some(stored_progress.to_value()?),
            },
        )?;
        Ok(admission)
    }

    /// Adopt an exact cross-site continuation head through the ordinary staged
    /// import path, then idempotently materialize its target-local runtime seed.
    /// The head is authoritative; SQLite installation is recoverable and never
    /// precedes writer-transfer verification.
    pub fn finalize_remote_adoption_import(
        &self,
        staged: ryeos_state::sync::StagedChainImport,
        transition: &ryeos_state::sync::AdmittedChainWriterTransition,
        admit_accounting: impl FnOnce(
            Option<&(String, ryeos_state::objects::AccountingAllowanceTransfer)>,
        ) -> Result<()>,
    ) -> Result<ryeos_state::sync::ImportResult> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        validate_remote_adoption_runtime_seed(&self.state_authority, &g, transition, false)?;
        let result = ryeos_state::sync::finalize_transferred_import(
            &g.state_db,
            staged,
            transition,
            g.signer.as_ref(),
            permit.cas_guard(),
        )?;
        let (target_launch_metadata, accounting_transfer) =
            validate_remote_adoption_runtime_seed(&self.state_authority, &g, transition, true)?;
        admit_accounting(accounting_transfer.as_ref())?;
        g.runtime_db.install_imported_thread_runtime(
            &transition.evidence.successor_placement_thread_id,
            &transition.evidence.chain_root_id,
            &target_launch_metadata,
        )?;
        Ok(result)
    }

    /// Repair the only allowed crash gap after a transferred head was adopted
    /// but before its operational runtime seed was installed. No staged bytes
    /// or remote phase claims are consulted; the current signed head and the
    /// complete writer/placement/capsule authority are reverified.
    pub fn recover_remote_adoption_runtime(
        &self,
        transition: &ryeos_state::sync::AdmittedChainWriterTransition,
        admit_accounting: impl FnOnce(
            Option<&(String, ryeos_state::objects::AccountingAllowanceTransfer)>,
        ) -> Result<()>,
    ) -> Result<()> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let (target_launch_metadata, accounting_transfer) =
            validate_remote_adoption_runtime_seed(&self.state_authority, &g, transition, true)?;
        admit_accounting(accounting_transfer.as_ref())?;
        g.runtime_db.install_imported_thread_runtime(
            &transition.evidence.successor_placement_thread_id,
            &transition.evidence.chain_root_id,
            &target_launch_metadata,
        )
    }

    #[track_caller]
    fn lock(&self) -> Result<StateStoreGuard<'_>> {
        let started = lillux::time::MonotonicTimer::start();
        let caller = std::panic::Location::caller();
        let fork_sensitive_descriptors = lillux::try_retain_fork_sensitive_descriptors()?;
        let inner = cooperate_while_blocking(|| {
            self.inner
                .lock()
                .map_err(|e| anyhow!("StateStore lock poisoned: {e}"))
        })?;
        let waited = started.elapsed();
        if waited >= std::time::Duration::from_millis(100) {
            record_store_contention(StoreContentionKind::Wait, waited, caller);
        }
        Ok(StateStoreGuard {
            store_mutex: &self.inner,
            _fork_sensitive_descriptors: fork_sensitive_descriptors,
            inner,
            acquired_at: lillux::time::MonotonicTimer::start(),
            caller,
        })
    }

    /// Bound BOTH original descriptor lease and StateStore mutex acquisition.
    /// The returned guard preserves the original descriptor-before-store order.
    #[track_caller]
    fn lock_until(&self, deadline: lillux::time::MonotonicDeadline) -> Result<StateStoreGuard<'_>> {
        let started = lillux::time::MonotonicTimer::start();
        let caller = std::panic::Location::caller();
        let fork_sensitive_descriptors = lillux::retain_fork_sensitive_descriptors_until(deadline)
            .context("original StateStore deadline waiting for descriptor lease")?;
        let inner = cooperate_while_blocking(|| {
            loop {
                if deadline.has_elapsed() {
                    bail!("original StateStore deadline expired waiting for mutex");
                }
                match self.inner.try_lock() {
                    Ok(inner) => {
                        if deadline.has_elapsed() {
                            bail!("original StateStore deadline expired at mutex acquisition");
                        }
                        break Ok(inner);
                    }
                    Err(std::sync::TryLockError::Poisoned(_)) => bail!("StateStore lock poisoned"),
                    Err(std::sync::TryLockError::WouldBlock) => {
                        lillux::time::sleep(
                            deadline
                                .remaining()
                                .min(lillux::time::Duration::from_millis(1)),
                        );
                    }
                }
            }
        })?;
        let waited = started.elapsed();
        if waited >= std::time::Duration::from_millis(100) {
            record_store_contention(StoreContentionKind::Wait, waited, caller);
        }
        Ok(StateStoreGuard {
            store_mutex: &self.inner,
            _fork_sensitive_descriptors: fork_sensitive_descriptors,
            inner,
            acquired_at: lillux::time::MonotonicTimer::start(),
            caller,
        })
    }

    fn with_runtime_original_deadline<T>(
        &self,
        deadline: lillux::time::MonotonicDeadline,
        operation: impl FnOnce(&runtime_db::RuntimeDb) -> Result<T>,
    ) -> Result<T> {
        let g = self.lock_until(deadline)?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("original RuntimeDb operation is fenced for process attachment");
        }
        g.runtime_db.with_original_deadline(
            deadline,
            &self.process_attachment_admission_open,
            &self.process_attachment_admission_closed,
            operation,
        )
    }

    fn attached_process_registry(
        &self,
    ) -> std::sync::MutexGuard<'_, BTreeMap<String, AttachedProcess>> {
        self.attached_processes.lock().unwrap_or_else(|poisoned| {
            tracing::error!(
                "attached process registry mutex was poisoned; retaining its derived state"
            );
            poisoned.into_inner()
        })
    }

    fn live_worker_registry(
        &self,
    ) -> std::sync::MutexGuard<'_, BTreeMap<String, runtime_db::WorkerProcessRecord>> {
        self.live_workers.lock().unwrap_or_else(|poisoned| {
            tracing::error!("live worker registry mutex was poisoned; retaining its derived state");
            poisoned.into_inner()
        })
    }

    /// The in-memory attachment records, read without SQL.
    pub fn attached_process_snapshot(&self) -> Vec<AttachedProcess> {
        self.attached_process_registry().values().cloned().collect()
    }

    /// Drop the in-memory attachment records of processes a stop proved dead
    /// without writing their rows, each only while it still holds exactly
    /// the proved identity. The durable rows stay attached for next-start
    /// recovery; the live Store's close then sees no live attachment.
    pub fn forget_proven_dead_attachments(
        &self,
        proved: &BTreeMap<String, crate::process::ExecutionProcessIdentity>,
    ) {
        let mut attached = self.attached_process_registry();
        for (thread_id, identity) in proved {
            if attached
                .get(thread_id)
                .is_some_and(|record| record.process_identity.as_ref() == Some(identity))
            {
                attached.remove(thread_id);
            }
        }
    }

    /// The in-memory live dedicated worker records, read without SQL.
    pub fn live_worker_snapshot(&self) -> Vec<runtime_db::WorkerProcessRecord> {
        self.live_worker_registry().values().cloned().collect()
    }

    /// Check occupancy under this exact Store guard, then retain only the
    /// lexical operation capability; no registry lock crosses SQL or files.
    fn selected_mutation_permit<'guard, 'store>(
        &self,
        g: &'guard StateStoreGuard<'store>,
        operation: SelectedMutationOperation<'guard>,
    ) -> Result<SelectedMutationPermit<'guard, 'store>> {
        if !self.owns_store_mutex(g.store_mutex) {
            bail!("selected mutation requires this SAME StateStore guard");
        }
        let selected = self
            .selected_invocations
            .lock()
            .map_err(|_| anyhow!("selected invocation registry poisoned; mutation refused"))?;
        let blocked = match &operation {
            SelectedMutationOperation::Claim(thread, ..)
            | SelectedMutationOperation::Release(thread, ..)
            | SelectedMutationOperation::Rotate(thread, ..)
            | SelectedMutationOperation::DeleteThread(thread)
            | SelectedMutationOperation::DiscardBirth(thread) => selected.has_thread(thread),
            SelectedMutationOperation::ClearStale(_)
            | SelectedMutationOperation::DeleteChain(..) => selected.has_any(),
        };
        if blocked {
            bail!("selected invocation retains destructive mutation ownership");
        }
        drop(selected);
        Ok(SelectedMutationPermit {
            guard: g,
            db: &g.runtime_db,
            operation,
        })
    }

    /// Whether `store_mutex` is this Store's own mutex. A guard of any other
    /// Store mints no selected permit and admits no selected cleanup.
    fn owns_store_mutex(&self, store_mutex: *const Mutex<Inner>) -> bool {
        std::ptr::eq(store_mutex, &self.inner)
    }

    fn require_selected_bulk_exclusion(&self, g: &StateStoreGuard<'_>) -> Result<()> {
        if !self.owns_store_mutex(g.store_mutex) {
            bail!("selected cleanup requires this SAME StateStore guard");
        }
        let selected = self
            .selected_invocations
            .lock()
            .map_err(|_| anyhow!("selected invocation registry poisoned; cleanup refused"))?;
        if selected.has_any() {
            bail!("selected invocation retains bulk cleanup ownership");
        }
        Ok(())
    }

    /// Delete one auxiliary runtime row and keep the process-attachment
    /// projection at the same StateStore linearization point. Runtime rows are
    /// normally removed before target release, but rollback must remain exact
    /// if a future caller reaches this path after an attachment was recorded.
    fn delete_thread_runtime_locked(
        &self,
        g: &StateStoreGuard<'_>,
        thread_id: &str,
    ) -> Result<usize> {
        let permit =
            self.selected_mutation_permit(g, SelectedMutationOperation::DeleteThread(thread_id))?;
        let deleted = g.runtime_db.delete_thread_runtime(&permit, thread_id)?;
        if deleted > 0 {
            self.attached_process_registry().remove(thread_id);
        }
        Ok(deleted)
    }

    /// Rebuild the derived attachment projection after a transactional
    /// chain-runtime retirement. That operation deliberately removes the
    /// signed chain members plus any auxiliary rows attributed to the same
    /// chain, so its exact affected thread-id set is owned by RuntimeDb.
    fn refresh_attached_process_registry_locked(&self, g: &Inner) -> Result<()> {
        let attached = attached_processes_from_runtime(&g.runtime_db)?;
        *self.attached_process_registry() = attached;
        Ok(())
    }

    /// Acquire a write permit from the write barrier.
    /// Fails if the daemon is quiescing for GC.
    #[track_caller]
    fn acquire_write_permit(&self) -> Result<StateMutationPermit> {
        if self.read_only {
            bail!("state store is open for strict read-only verification");
        }
        let fork_sensitive_descriptors = lillux::try_retain_fork_sensitive_descriptors()?;
        let cas_guard = self.state_authority.acquire_shared_guard()?;
        let write_permit = self
            .write_barrier
            .acquire_with_timeout(crate::write_barrier::ONLINE_WRITE_PERMIT_TIMEOUT)
            .map_err(|e| anyhow!("cannot acquire write permit: {e}"))?;
        Ok(StateMutationPermit {
            _fork_sensitive_descriptors: fork_sensitive_descriptors,
            cas_guard,
            _write_permit: write_permit,
        })
    }

    /// Serialize a terminal-GC dry-run with ordinary writers using only
    /// already-established lock anchors. This retains the normal barrier and
    /// lock order but cannot create recovery state merely by inspecting it.
    #[track_caller]
    fn acquire_gc_inspection_permit(&self) -> Result<StateMutationPermit> {
        if self.read_only {
            bail!("state store is open for strict read-only verification");
        }
        let fork_sensitive_descriptors = lillux::try_retain_fork_sensitive_descriptors()?;
        let cas_guard = self.state_authority.acquire_shared_guard()?;
        let write_permit = self
            .write_barrier
            .acquire_with_timeout(crate::write_barrier::ONLINE_WRITE_PERMIT_TIMEOUT)
            .map_err(|e| anyhow!("cannot acquire GC inspection permit: {e}"))?;
        Ok(StateMutationPermit {
            _fork_sensitive_descriptors: fork_sensitive_descriptors,
            cas_guard,
            _write_permit: write_permit,
        })
    }

    /// Narrow mutation permit for converging journaled Remove records as part
    /// of the authored offline projection-rebuild bootstrap. It does not widen
    /// the common write gate, so unrelated StateStore mutations remain denied.
    #[track_caller]
    fn acquire_recovery_cleanup_permit(&self, _dry_run: bool) -> Result<StateMutationPermit> {
        if self.read_only && !self.allow_projection_rebuild {
            bail!("state store is open for strict read-only verification");
        }
        let fork_sensitive_descriptors = lillux::try_retain_fork_sensitive_descriptors()?;
        let cas_guard = self.state_authority.acquire_shared_guard()?;
        let write_permit = self
            .write_barrier
            .acquire_with_timeout(crate::write_barrier::ONLINE_WRITE_PERMIT_TIMEOUT)
            .map_err(|e| anyhow!("cannot acquire recovery cleanup permit: {e}"))?;
        Ok(StateMutationPermit {
            _fork_sensitive_descriptors: fork_sensitive_descriptors,
            cas_guard,
            _write_permit: write_permit,
        })
    }

    fn authorize_runtime_pin_for_thread(
        g: &Inner,
        thread_id: &str,
    ) -> Result<ryeos_state::AuthoritativeRuntimePinAdmission> {
        let thread = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("runtime-pin thread {thread_id} does not exist"))?;
        g.state_db.authorize_runtime_pin(&thread.chain_root_id)
    }

    #[tracing::instrument(
        name = "state:create_thread",
        skip(self, thread),
        fields(
            thread_id = %thread.thread_id,
            chain_root_id = %thread.chain_root_id,
            kind = %thread.kind,
            item_ref = %thread.item_ref,
        )
    )]
    pub(crate) fn create_child_thread_admitted(
        &self,
        thread: &NewThreadRecord,
    ) -> Result<Vec<PersistedEventRecord>> {
        if thread.thread_id == thread.chain_root_id {
            bail!("child persistence requires thread_id != chain_root_id");
        }
        if thread.captured_history_policy.is_some() {
            bail!("non-root threads cannot carry a captured history policy");
        }
        self.create_thread_inner(thread)
    }

    /// Raw root persistence is crate-private. The only production callers are
    /// lifecycle methods which first consume an opaque, current admission.
    pub(crate) fn create_admitted_root_thread(
        &self,
        thread: &NewThreadRecord,
    ) -> Result<CreatedThreadPublication> {
        if thread.thread_id != thread.chain_root_id {
            bail!("admitted root persistence requires thread_id == chain_root_id");
        }
        if thread.captured_history_policy.is_none() {
            bail!(
                "new chain root {} has no verified captured history policy",
                thread.thread_id
            );
        }
        self.create_root_thread_with_events_and_launch_metadata(thread, Vec::new(), None)
    }

    /// State-layer fixture for tests which exercise persistence below the
    /// engine admission boundary. It is absent from production builds and
    /// deliberately names the bypass; application/runtime tests should prefer
    /// a real lifecycle admission.
    #[cfg(any(test, feature = "test-support"))]
    pub fn create_thread_for_test(
        &self,
        thread: &NewThreadRecord,
    ) -> Result<Vec<PersistedEventRecord>> {
        if thread.thread_id == thread.chain_root_id {
            self.create_admitted_root_thread(thread)
                .map(|publication| publication.persisted)
        } else {
            self.create_child_thread_admitted(thread)
        }
    }

    #[cfg(any(test, feature = "test-support"))]
    pub(crate) fn create_root_thread_for_test_with_launch_metadata(
        &self,
        thread: &NewThreadRecord,
        launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
    ) -> Result<Vec<PersistedEventRecord>> {
        anyhow::ensure!(
            thread.thread_id == thread.chain_root_id,
            "launch-metadata fixture must be a chain root"
        );
        self.create_root_thread_with_events_and_launch_metadata(
            thread,
            Vec::new(),
            Some(launch_metadata),
        )
        .map(|publication| publication.persisted)
    }

    /// Deliberately corrupt only the replaceable thread projection so recovery
    /// tests can prove authoritative reservation reconciliation does not
    /// depend on projected status.
    #[cfg(any(test, feature = "test-support"))]
    pub fn set_thread_projection_status_for_test(
        &self,
        thread_id: &str,
        status: &str,
    ) -> Result<()> {
        let g = self.lock()?;
        let updated = g.state_db.projection().with_sql(|connection| {
            Ok(connection.execute(
                "UPDATE threads SET status = ?2 WHERE thread_id = ?1",
                rusqlite::params![thread_id, status],
            )?)
        })?;
        if updated != 1 {
            bail!("test projection mutation found no exact thread {thread_id}");
        }
        Ok(())
    }

    /// Run raw SQL on this Store's own live Runtime connection, so recovery
    /// tests can forge crash-window rows that no public transition produces.
    /// A second connection to the Runtime file is refused by the native host.
    #[cfg(any(test, feature = "test-support"))]
    pub fn with_runtime_sql_for_test<T>(
        &self,
        operation: impl for<'connection> FnOnce(&'connection rusqlite::Connection) -> Result<T>,
    ) -> Result<T> {
        let g = self.lock()?;
        g.runtime_db.with_sql_for_test(operation)
    }

    /// Remove only projected events while retaining authoritative CAS, used to
    /// prove terminal postcommit repair does not depend on projection freshness.
    #[cfg(any(test, feature = "test-support"))]
    pub fn delete_thread_projection_events_for_test(&self, thread_id: &str) -> Result<usize> {
        let g = self.lock()?;
        g.state_db.projection().with_sql(|connection| {
            Ok(connection.execute(
                "DELETE FROM events WHERE thread_id = ?1",
                rusqlite::params![thread_id],
            )?)
        })
    }

    /// Remove the replaceable thread row after its projected events have been
    /// removed. Authoritative CAS remains intact so terminal postcommit repair
    /// can prove it has no projection-row dependency.
    #[cfg(any(test, feature = "test-support"))]
    pub fn delete_thread_projection_row_for_test(&self, thread_id: &str) -> Result<bool> {
        let g = self.lock()?;
        Ok(g.state_db.projection().with_sql(|connection| {
            Ok(connection.execute(
                "DELETE FROM threads WHERE thread_id = ?1",
                rusqlite::params![thread_id],
            )?)
        })? == 1)
    }

    fn create_thread_inner(&self, thread: &NewThreadRecord) -> Result<Vec<PersistedEventRecord>> {
        if thread.thread_id == thread.chain_root_id {
            return self
                .create_root_thread_with_events_and_launch_metadata(thread, Vec::new(), None)
                .map(|publication| publication.persisted);
        }
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("thread creation is closed for daemon shutdown");
        }
        let mut payload = json!({
            "kind": &thread.kind,
            "item_ref": &thread.item_ref,
            "executor_ref": &thread.executor_ref,
            "launch_mode": &thread.launch_mode,
        });
        if let Some(usage_subject) = &thread.usage_subject {
            usage_subject.validate()?;
            payload["usage_subject"] =
                serde_json::to_value(usage_subject).context("failed to encode usage_subject")?;
            if let Some(asserted_by) = &thread.usage_subject_asserted_by {
                payload["usage_subject_asserted_by"] = json!(asserted_by);
            }
        }

        let create_event = NewEventRecord {
            event_type: "thread_created".to_string(),
            storage_class: "indexed".to_string(),
            payload,
        };

        let te = convert_events(
            std::slice::from_ref(&create_event),
            &thread.chain_root_id,
            &thread.thread_id,
        );
        {
            let _admission = g.state_db.authorize_runtime_pin(&thread.chain_root_id)?;
            g.runtime_db
                .insert_thread_runtime(&thread.thread_id, &thread.chain_root_id)?;
        }
        let committed = g.state_db.add_thread_with_events_admitted(
            &thread.chain_root_id,
            build_snapshot(thread),
            te,
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        );
        let result = match committed {
            Ok(committed) => committed_value(committed),
            Err(error) => {
                let _ = self.delete_thread_runtime_locked(&g, &thread.thread_id);
                return Err(error);
            }
        };

        persisted_from_add_thread_with_events(&result, &[create_event])
    }

    /// Create a root thread together with caller-supplied initial durable
    /// events. The snapshot, `thread_created`, and supplied events share one
    /// authoritative chain-head commit and projection transaction.
    pub fn create_root_thread_with_events(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.create_root_thread_with_events_and_launch_metadata(thread, initial_events, None)
            .map(|publication| publication.persisted)
    }

    /// Create a managed-launch root with its resume identity installed before
    /// the authoritative chain head becomes visible. The runtime row is
    /// auxiliary, so it is prepared first and removed if chain creation fails.
    pub(crate) fn create_root_thread_with_events_and_launch_metadata(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: Option<&crate::launch_metadata::RuntimeLaunchMetadata>,
    ) -> Result<CreatedThreadPublication> {
        self.create_root_thread_with_events_and_launch_metadata_owned(
            thread,
            initial_events,
            launch_metadata,
            RootBirthOwner::External,
        )
    }

    /// Publish an in-process root only while the exact daemon task owner is
    /// registered. The synchronous owner task cannot drop its guard during
    /// this call; the registry lock itself is deliberately released before
    /// the authoritative chain/runtime commit.
    pub fn create_in_process_root_with_events_and_launch_metadata(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        owner: &InProcessHandlerControl,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.create_root_thread_with_events_and_launch_metadata_owned(
            thread,
            initial_events,
            Some(launch_metadata),
            RootBirthOwner::InProcess(owner),
        )
        .map(|publication| publication.persisted)
    }

    /// Publish an in-process handler thread as a member of its parent's chain
    /// while its exact daemon task owner is registered. An inline in-process
    /// child is a thread in its parent's chain with the parent as upstream,
    /// exactly like an inline tool leaf; this is the birth that makes it so.
    /// The owner contract is the root birth's: the durable reservation is
    /// established before the commit, the created→running transition commits
    /// with the birth under the parent chain's signed head, and the owner's
    /// birth proof is marked only once that head carries the member. The
    /// registry lock is released before the authoritative commit, as above.
    ///
    /// The returned witness is the only way to link the child while it may
    /// still inherit a parent stop landed since the birth; see
    /// [`Self::link_unspawned_in_process_child`].
    pub fn create_in_process_child_with_events_and_launch_metadata(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        owner: &InProcessHandlerControl,
    ) -> Result<(Vec<PersistedEventRecord>, UnspawnedInProcessChild)> {
        let persisted = self.create_in_process_child_birth(
            thread,
            initial_events,
            launch_metadata,
            owner,
            true,
        )?;
        let parent_thread_id = thread.upstream_thread_id.clone().ok_or_else(|| {
            anyhow!(
                "in-process child {} names no upstream parent",
                thread.thread_id
            )
        })?;
        Ok((
            persisted,
            UnspawnedInProcessChild {
                parent_thread_id,
                thread_id: thread.thread_id.clone(),
            },
        ))
    }

    /// The same birth, interrupted exactly as a crash after the authoritative
    /// commit would leave it: the member is published, its reservation is
    /// still pending, and no dispatch link has been written.
    #[cfg(test)]
    fn fixture_create_in_process_child_interrupted_before_link(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        owner: &InProcessHandlerControl,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.create_in_process_child_birth(thread, initial_events, launch_metadata, owner, false)
    }

    fn create_in_process_child_birth(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        owner: &InProcessHandlerControl,
        link_and_advance: bool,
    ) -> Result<Vec<PersistedEventRecord>> {
        if thread.thread_id == thread.chain_root_id || thread.upstream_thread_id.is_none() {
            bail!("in-process child birth requires a chain member record with an upstream parent");
        }
        if thread.captured_history_policy.is_some() {
            bail!("non-root threads cannot carry a captured history policy");
        }
        if initial_events
            .iter()
            .any(|event| event.storage_class == "ephemeral")
        {
            bail!("in-process child initial events must be durable");
        }
        if initial_events.len() != 1
            || initial_events[0].event_type != ryeos_state::event_types::THREAD_STARTED
        {
            bail!("in-process child birth requires exactly one thread_started successor event");
        }
        if launch_metadata.launch_driver
            != Some(ryeos_state::objects::ExecutionLaunchDriver::InProcessHandler)
        {
            bail!("in-process child birth requires the in-process handler launch driver");
        }
        let permit = self.acquire_write_permit()?;
        self.ensure_in_process_handler_owner(&thread.thread_id, owner)?;
        let birth_snapshot = attach_admitted_launch_capsule(
            &self.state_authority,
            permit.cas_guard(),
            build_snapshot(thread),
            Some(launch_metadata),
        )?;
        let g = self.lock()?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("thread creation is closed for daemon shutdown");
        }
        // The parent must be a live member of the chain before anything of
        // the child is written. The store lock is held from here through the
        // link, so no store finalizer can settle the parent in between; the
        // chain commit repeats the check against the head under its own lock.
        let parent_thread_id = thread
            .upstream_thread_id
            .as_deref()
            .expect("in-process child upstream checked above");
        let parent = g
            .state_db
            .read_authoritative_thread_snapshot(&thread.chain_root_id, parent_thread_id)?
            .ok_or_else(|| {
                anyhow!(
                    "in-process child {} names parent {parent_thread_id}, which is not a member of chain {}",
                    thread.thread_id,
                    thread.chain_root_id
                )
            })?;
        if parent.status.is_terminal() {
            bail!(
                "refusing to birth in-process child {} under terminal parent {parent_thread_id} ({})",
                thread.thread_id,
                parent.status.as_str()
            );
        }
        validate_facet_event_admission(&g, &thread.thread_id, &initial_events)?;
        let mut payload = json!({
            "kind": &thread.kind,
            "item_ref": &thread.item_ref,
            "executor_ref": &thread.executor_ref,
            "launch_mode": &thread.launch_mode,
        });
        if let Some(usage_subject) = &thread.usage_subject {
            usage_subject.validate()?;
            payload["usage_subject"] =
                serde_json::to_value(usage_subject).context("failed to encode usage_subject")?;
            if let Some(asserted_by) = &thread.usage_subject_asserted_by {
                payload["usage_subject_asserted_by"] = json!(asserted_by);
            }
        }
        let mut events = Vec::with_capacity(initial_events.len() + 1);
        events.push(NewEventRecord {
            event_type: ryeos_state::event_types::THREAD_CREATED.to_string(),
            storage_class: "indexed".to_string(),
            payload,
        });
        events.extend(initial_events);
        let thread_events = convert_events(&events, &thread.chain_root_id, &thread.thread_id);
        let mut running = birth_snapshot.clone();
        running.status = ThreadStatus::Running;
        let started_at = lillux::time::iso8601_now();
        running.started_at = Some(started_at.clone());
        running.updated_at = started_at;
        // The auxiliary runtime row and the pending reservation precede the
        // authoritative commit, inside the parent chain's runtime pin, like
        // every other member birth. A proven pre-commit failure removes them;
        // an ambiguous acknowledgement or an observable committed member
        // preserves them for exact settlement.
        {
            let _admission = g.state_db.authorize_runtime_pin(&thread.chain_root_id)?;
            g.runtime_db.reserve_in_process_handler_birth(
                &thread.thread_id,
                &thread.chain_root_id,
                launch_metadata,
            )?;
        }
        let committed = g.state_db.add_thread_with_event_successor_admitted(
            AddThreadWithEventSuccessorRequest {
                chain_root_id: &thread.chain_root_id,
                genesis_snapshot: birth_snapshot,
                event_successor_snapshot: running,
                events: thread_events,
                signer: g.signer.as_ref(),
                runtime_liveness: &g.runtime_db,
                cas_mutation_guard: permit.cas_guard(),
            },
        );
        let result = match committed {
            Ok(committed) => committed_value(committed),
            Err(error) => {
                // The parent chain head is the only authority on whether the
                // member was published. A readable head without the member
                // proves the write never landed; a member at running status
                // is the exact birth this owner authored; anything else keeps
                // ownership for reconciliation.
                match g
                    .state_db
                    .read_authoritative_thread_snapshot(&thread.chain_root_id, &thread.thread_id)
                {
                    Ok(Some(snapshot)) if snapshot.status == ThreadStatus::Running => {
                        owner.mark_birth_committed();
                        // The caller receives an error and its owner settles
                        // the member with its own failure terminal, so only
                        // lineage is written here, not an inherited stop that
                        // would contradict that terminal.
                        if let Err(link_error) = link_in_process_chain_member_locked(
                            &g,
                            &thread.chain_root_id,
                            &snapshot,
                            false,
                        ) {
                            return Err(anyhow!(
                                "in-process child birth committed despite its returned error, but its dispatch link could not be written; reservation settlement repairs it: {link_error:#}; original error: {error:#}"
                            ));
                        }
                        if let Err(reservation_error) = g
                            .runtime_db
                            .mark_in_process_handler_birth_running(&thread.thread_id)
                        {
                            return Err(anyhow!(
                                "in-process child birth committed despite its returned error, but its reservation could not advance: {reservation_error:#}; original error: {error:#}"
                            ));
                        }
                        return Err(anyhow!(
                            "in-process child birth committed authoritative state despite its returned error; its armed owner must settle the row: {error:#}"
                        ));
                    }
                    Ok(Some(snapshot)) => {
                        owner.mark_birth_committed();
                        return Err(anyhow!(
                            "in-process child birth left member {} at status {} after its returned error; preserving runtime ownership for reconciliation: {error:#}",
                            thread.thread_id,
                            snapshot.status.as_str()
                        ));
                    }
                    Ok(None) => {}
                    Err(readback_error) => {
                        owner.mark_birth_committed();
                        return Err(anyhow!(
                            "in-process child birth failed and authoritative readback was unavailable; preserving runtime ownership for reconciliation: write error: {error:#}; readback error: {readback_error:#}"
                        ));
                    }
                }
                let cleanup = self
                    .selected_mutation_permit(
                        &g,
                        SelectedMutationOperation::DiscardBirth(&thread.thread_id),
                    )
                    .and_then(|selected| {
                        g.runtime_db
                            .discard_pending_in_process_handler_birth(&selected, &thread.thread_id)
                    })
                    .and_then(|deleted| {
                        if deleted {
                            Ok(())
                        } else {
                            bail!(
                                "pending in-process birth reservation disappeared before failed-member cleanup"
                            )
                        }
                    });
                if let Err(cleanup_error) = cleanup {
                    tracing::error!(
                        thread_id = %thread.thread_id,
                        chain_root_id = %thread.chain_root_id,
                        error = %cleanup_error,
                        "failed to remove auxiliary runtime row after in-process child birth failed"
                    );
                }
                return Err(error);
            }
        };
        owner.mark_birth_committed();
        if !link_and_advance {
            return persisted_from_add_thread_with_events(&result, &events)
                .context("reconstruct committed in-process child events");
        }
        // The member is published; its dispatch link and any stop the parent
        // already carries are written in one runtime transaction before the
        // reservation leaves `pending`, so a running reservation always has
        // its link and a crash in between is repaired from the upstream id
        // when reconciliation advances the reservation.
        link_in_process_chain_member_locked(&g, &thread.chain_root_id, &result.snapshot, true)
            .with_context(|| {
                format!(
                    "record dispatch link of in-process child {} to parent {parent_thread_id}",
                    thread.thread_id
                )
            })?;
        g.runtime_db
            .mark_in_process_handler_birth_running(&thread.thread_id)
            .with_context(|| {
                format!(
                    "advance committed in-process birth reservation for {}",
                    thread.thread_id
                )
            })?;
        persisted_from_add_thread_with_events(&result, &events)
            .context("reconstruct committed in-process child events before handler effects")
    }

    fn create_root_thread_with_events_and_launch_metadata_owned(
        &self,
        thread: &NewThreadRecord,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: Option<&crate::launch_metadata::RuntimeLaunchMetadata>,
        birth_owner: RootBirthOwner<'_>,
    ) -> Result<CreatedThreadPublication> {
        if thread.thread_id != thread.chain_root_id || thread.upstream_thread_id.is_some() {
            bail!("create_root_thread_with_events requires a root thread record");
        }
        if initial_events
            .iter()
            .any(|event| event.storage_class == "ephemeral")
        {
            bail!("root initial events must be durable");
        }
        let permit = self.acquire_write_permit()?;
        let is_in_process_launch = launch_metadata.and_then(|metadata| metadata.launch_driver)
            == Some(ryeos_state::objects::ExecutionLaunchDriver::InProcessHandler);
        match (&birth_owner, is_in_process_launch) {
            (RootBirthOwner::External, false) => {
                let active = self
                    .active_in_process_handlers
                    .lock()
                    .map_err(|_| anyhow!("active in-process-handler registry poisoned"))?;
                if active.contains_key(&thread.thread_id) {
                    bail!(
                        "registered in-process owner cannot publish a non-in-process root for thread {}",
                        thread.thread_id
                    );
                }
            }
            (RootBirthOwner::External, true) => {
                bail!("in-process root birth requires an exact registered daemon owner");
            }
            (RootBirthOwner::InProcess(_), false) => {
                bail!("in-process root owner cannot authorize a different launch driver");
            }
            (RootBirthOwner::InProcess(owner), true) => {
                // As above, do not serialize every StateStore writer behind a
                // volatile registry mutex while the durable birth commits.
                self.ensure_in_process_handler_owner(&thread.thread_id, owner)?;
            }
        }
        // Capsule verification and CAS publication are protected by the
        // mutation permit above, not by the daemon's process-local store
        // mutex. Do them before taking that mutex so independent root births
        // do not serialize every runtime/projection operation behind content
        // verification. Admission state, the auxiliary runtime row, the
        // authoritative chain commit, and its projection remain one fenced
        // critical section below.
        let birth_snapshot = attach_admitted_launch_capsule(
            &self.state_authority,
            permit.cas_guard(),
            build_snapshot(thread),
            launch_metadata,
        )?;
        let expected_birth_snapshot = birth_snapshot.clone();
        let thread_runtime = RuntimeInfo {
            launch_metadata: launch_metadata.cloned(),
            ..RuntimeInfo::default()
        };
        let g = self.lock()?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("thread creation is closed for daemon shutdown");
        }
        let launch_planning = g.runtime_db.launch_planning_by_thread(&thread.thread_id)?;
        if let Some(planning) = launch_planning.as_ref() {
            if planning.state != "planning"
                || planning.daemon_generation_id != runtime_db::daemon_generation_id()
            {
                return Err(LaunchPlanningInactive.into());
            }
            validate_launch_planning_owner(planning, thread.requested_by.as_deref())?;
        }
        // Initial facet events are subject to the same collection/key/value
        // limits as ordinary appends. The new thread is not projected yet, so
        // the validator correctly evaluates this batch against an empty set.
        validate_facet_event_admission(&g, &thread.thread_id, &initial_events)?;
        let mut payload = json!({
            "kind": &thread.kind,
            "item_ref": &thread.item_ref,
            "executor_ref": &thread.executor_ref,
            "launch_mode": &thread.launch_mode,
        });
        if let Some(usage_subject) = &thread.usage_subject {
            usage_subject.validate()?;
            payload["usage_subject"] =
                serde_json::to_value(usage_subject).context("failed to encode usage_subject")?;
            if let Some(asserted_by) = &thread.usage_subject_asserted_by {
                payload["usage_subject_asserted_by"] = json!(asserted_by);
            }
        }
        let mut events = Vec::with_capacity(initial_events.len() + 1);
        events.push(NewEventRecord {
            event_type: ryeos_state::event_types::THREAD_CREATED.to_string(),
            storage_class: "indexed".to_string(),
            payload,
        });
        events.extend(initial_events);
        let thread_events = convert_events(&events, &thread.chain_root_id, &thread.thread_id);
        let event_successor_snapshot = if launch_metadata
            .and_then(|metadata| metadata.launch_driver)
            == Some(ryeos_state::objects::ExecutionLaunchDriver::InProcessHandler)
        {
            if events.len() != 2 || events[1].event_type != ryeos_state::event_types::THREAD_STARTED
            {
                bail!("in-process root birth requires exactly one thread_started successor event");
            }
            let mut running = birth_snapshot.clone();
            running.status = ThreadStatus::Running;
            let started_at = lillux::time::iso8601_now();
            running.started_at = Some(started_at.clone());
            running.updated_at = started_at;
            Some(running)
        } else {
            None
        };
        let expected_event_successor_snapshot = event_successor_snapshot.clone();
        let expected_thread_events = thread_events.clone();
        // Establish the auxiliary runtime row before the authoritative commit.
        // A proven pre-commit failure removes it. Ambiguous acknowledgement or
        // an observable committed root preserves it for exact settlement;
        // deleting uncertain ownership would make recovery impossible.
        if is_in_process_launch {
            g.runtime_db.reserve_in_process_handler_birth(
                &thread.thread_id,
                &thread.chain_root_id,
                launch_metadata.expect("in-process launch metadata is present"),
            )?;
        } else {
            g.runtime_db
                .insert_thread_runtime(&thread.thread_id, &thread.chain_root_id)?;
            if let Some(launch_metadata) = launch_metadata
                && let Err(error) = g
                    .runtime_db
                    .set_launch_metadata(&thread.thread_id, launch_metadata)
            {
                let _ = self.delete_thread_runtime_locked(&g, &thread.thread_id);
                return Err(error);
            }
        }
        let committed = match event_successor_snapshot {
            Some(successor) => g.state_db.create_chain_with_event_successor_admitted(
                CreateChainWithEventSuccessorRequest {
                    chain_root_id: &thread.chain_root_id,
                    genesis_snapshot: birth_snapshot,
                    event_successor_snapshot: successor,
                    events: thread_events,
                    signer: g.signer.as_ref(),
                    runtime_liveness: &g.runtime_db,
                    cas_mutation_guard: permit.cas_guard(),
                },
            ),
            None => g.state_db.create_chain_with_events_admitted(
                &thread.chain_root_id,
                birth_snapshot,
                thread_events,
                g.signer.as_ref(),
                &g.runtime_db,
                permit.cas_guard(),
            ),
        };
        let result = match committed {
            Ok(committed) => committed_value(committed),
            Err(error) => {
                match read_exact_committed_root(
                    &g,
                    &thread.chain_root_id,
                    ExpectedRootCommit {
                        birth_snapshot: &expected_birth_snapshot,
                        event_successor_snapshot: expected_event_successor_snapshot.as_ref(),
                        events: &expected_thread_events,
                    },
                ) {
                    Ok(RootCommitReadback::Exact(snapshot)) => {
                        if let RootBirthOwner::InProcess(owner) = &birth_owner {
                            owner.mark_birth_committed();
                            if let Err(reservation_error) = g
                                .runtime_db
                                .mark_in_process_handler_birth_running(&thread.thread_id)
                            {
                                return Err(anyhow!(
                                    "in-process root birth committed despite its returned error, but its reservation could not advance: {reservation_error:#}; original error: {error:#}"
                                ));
                            }
                            return Err(anyhow!(
                                "in-process root birth committed authoritative state despite its returned error; its armed owner must settle the row: {error:#}"
                            ));
                        }
                        // External managed publication can continue from the
                        // exact signed snapshot. Returning the write error here
                        // would strand a committed root before launch.
                        if let Some(planning) = launch_planning.as_ref() {
                            match g.runtime_db.bind_launch_planning(&thread.thread_id) {
                                Ok(true) => {}
                                Ok(false) => tracing::error!(
                                    thread_id = %thread.thread_id,
                                    launch_id = %planning.launch_id,
                                    "authoritative root committed but launch planning bind changed no row"
                                ),
                                Err(bind_error) => tracing::error!(
                                    thread_id = %thread.thread_id,
                                    launch_id = %planning.launch_id,
                                    error = %bind_error,
                                    "authoritative root committed but launch planning bind failed"
                                ),
                            }
                            match self.launch_task_abort_handles.lock() {
                                Ok(mut handles) => {
                                    handles.remove(&planning.launch_id);
                                }
                                Err(poisoned) => {
                                    tracing::error!(
                                        thread_id = %thread.thread_id,
                                        launch_id = %planning.launch_id,
                                        "launch task abort registry was poisoned after root commit"
                                    );
                                    poisoned.into_inner().remove(&planning.launch_id);
                                }
                            }
                        }
                        tracing::error!(
                            thread_id = %thread.thread_id,
                            error = %error,
                            "root birth returned an error after publishing authoritative state; continuing from exact committed snapshot"
                        );
                        let successor =
                            thread_detail_from_committed_snapshot(*snapshot, thread_runtime);
                        return Ok(CreatedThreadPublication {
                            persisted: Vec::new(),
                            successor,
                            remote_writer_grant_hash: None,
                        });
                    }
                    Ok(RootCommitReadback::Ambiguous(reason)) => {
                        if let RootBirthOwner::InProcess(owner) = &birth_owner {
                            owner.mark_birth_committed();
                        }
                        return Err(anyhow!(
                            "root birth failed with ambiguous authoritative state; preserving runtime ownership for reconciliation ({reason}): {error:#}"
                        ));
                    }
                    Err(authority_error) => {
                        if let RootBirthOwner::InProcess(owner) = &birth_owner {
                            // The write acknowledgement and authoritative
                            // readback are both ambiguous. Treat birth as
                            // possibly committed so guard-drop exact
                            // terminalization is attempted; startup can
                            // discard the pending reservation if no root was
                            // actually published.
                            owner.mark_birth_committed();
                        }
                        return Err(anyhow!(
                            "root birth failed and authoritative readback was unavailable; preserving runtime ownership for reconciliation: write error: {error:#}; readback error: {authority_error:#}"
                        ));
                    }
                    Ok(RootCommitReadback::ProvenAbsent) => {}
                }
                let _selected_exclusion = self.selected_mutation_permit(
                    &g,
                    SelectedMutationOperation::DeleteThread(&thread.thread_id),
                )?;
                if let Err(settle_error) = g.runtime_db.fail_launch_planning(&thread.thread_id) {
                    tracing::error!(
                        thread_id = %thread.thread_id,
                        error = %settle_error,
                        "failed to settle launch planning after root-chain creation failed"
                    );
                }
                let cleanup = if is_in_process_launch {
                    g.runtime_db
                        .discard_pending_in_process_handler_birth(&self.selected_mutation_permit(&g, SelectedMutationOperation::DiscardBirth(&thread.thread_id))?, &thread.thread_id)
                        .and_then(|deleted| {
                            if deleted {
                                Ok(())
                            } else {
                                bail!(
                                    "pending in-process birth reservation disappeared before failed-root cleanup"
                                )
                            }
                        })
                } else {
                    self.delete_thread_runtime_locked(&g, &thread.thread_id)
                        .map(|_| ())
                };
                if let Err(cleanup_error) = cleanup {
                    tracing::error!(
                        thread_id = %thread.thread_id,
                        error = %cleanup_error,
                        "failed to remove auxiliary runtime row after root-chain creation failed"
                    );
                }
                return Err(error);
            }
        };
        // The signed root birth is authoritative from this point onward.
        // Recorded in-process ownership deliberately retains one fallible
        // boundary: if the durable reservation cannot advance, its already
        // armed owner guard must settle the committed row before handler
        // effects proceed. External managed roots have no such guard, so all
        // of their remaining publication work is best-effort and infallible.
        if let RootBirthOwner::InProcess(owner) = &birth_owner {
            owner.mark_birth_committed();
            g.runtime_db
                .mark_in_process_handler_birth_running(&thread.thread_id)
                .with_context(|| {
                    format!(
                        "advance committed in-process birth reservation for {}",
                        thread.thread_id
                    )
                })?;
        }
        if let Some(planning) = launch_planning {
            match g.runtime_db.bind_launch_planning(&thread.thread_id) {
                Ok(true) => {}
                Ok(false) => tracing::error!(
                    thread_id = %thread.thread_id,
                    launch_id = %planning.launch_id,
                    "authoritative root committed but launch planning bind changed no row"
                ),
                Err(error) => tracing::error!(
                    thread_id = %thread.thread_id,
                    launch_id = %planning.launch_id,
                    error = %error,
                    "authoritative root committed but launch planning bind failed"
                ),
            }
            match self.launch_task_abort_handles.lock() {
                Ok(mut handles) => {
                    handles.remove(&planning.launch_id);
                }
                Err(poisoned) => {
                    tracing::error!(
                        thread_id = %thread.thread_id,
                        launch_id = %planning.launch_id,
                        "launch task abort registry was poisoned after root commit"
                    );
                    poisoned.into_inner().remove(&planning.launch_id);
                }
            }
        }
        let persisted = match persisted_from_add_thread_with_events(&result, &events) {
            Ok(persisted) => persisted,
            Err(error) => {
                if matches!(&birth_owner, RootBirthOwner::InProcess(_)) {
                    return Err(error.context(
                        "reconstruct committed in-process root events before handler effects",
                    ));
                }
                tracing::error!(
                    thread_id = %thread.thread_id,
                    chain_root_id = %thread.chain_root_id,
                    error = %error,
                    "authoritative root committed but live event reconstruction failed"
                );
                Vec::new()
            }
        };
        let successor = thread_detail_from_committed_snapshot(result.snapshot, thread_runtime);
        Ok(CreatedThreadPublication {
            persisted,
            successor,
            remote_writer_grant_hash: None,
        })
    }

    #[tracing::instrument(
        name = "state:create_trace_branch",
        skip(self, thread, branch_payload),
        fields(
            thread_id = %thread.thread_id,
            chain_root_id = %thread.chain_root_id,
            item_ref = %thread.item_ref,
        )
    )]
    pub fn create_trace_branch(
        &self,
        thread: &NewThreadRecord,
        branch_payload: Value,
    ) -> Result<Vec<PersistedEventRecord>> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("trace-branch creation is closed for daemon shutdown");
        }

        if thread.thread_id == thread.chain_root_id {
            bail!("trace branch child must not be a chain root thread");
        }
        if thread.upstream_thread_id.is_some() {
            bail!("trace branch child must not use upstream_thread_id");
        }
        if g.state_db.get_thread(&thread.thread_id)?.is_some() {
            bail!("thread already exists: {}", thread.thread_id);
        }

        let create_event = NewEventRecord {
            event_type: ryeos_state::event_types::THREAD_CREATED.to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "kind": &thread.kind,
                "item_ref": &thread.item_ref,
                "executor_ref": &thread.executor_ref,
                "launch_mode": &thread.launch_mode,
                "trace_branch": true,
            }),
        };
        let branch_event = NewEventRecord {
            event_type: ryeos_state::event_types::EDGE_RECORDED.to_string(),
            storage_class: "indexed".to_string(),
            payload: branch_payload,
        };
        let events_to_append = vec![create_event, branch_event];
        let te = convert_events(&events_to_append, &thread.chain_root_id, &thread.thread_id);
        let result = committed_value(g.state_db.add_thread_with_events_admitted(
            &thread.chain_root_id,
            build_snapshot(thread),
            te,
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        )?);

        {
            let _admission = g.state_db.authorize_runtime_pin(&thread.chain_root_id)?;
            g.runtime_db
                .insert_thread_runtime(&thread.thread_id, &thread.chain_root_id)?;
        }

        persisted_from_add_thread_with_events(&result, &events_to_append)
    }

    #[tracing::instrument(
        name = "state:mark_thread_running",
        skip(self),
        fields(thread_id = %thread_id)
    )]
    pub fn mark_thread_running(
        &self,
        thread_id: &str,
        base_project_snapshot_hash: Option<&str>,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.mark_thread_running_with_events(thread_id, base_project_snapshot_hash, Vec::new())
    }

    /// Atomically append launch-attempt audit and cross a created thread into
    /// `running`. Existing running recovery attempts append only their new
    /// audit; they never emit a duplicate `thread_started` event.
    pub fn mark_thread_running_with_events(
        &self,
        thread_id: &str,
        base_project_snapshot_hash: Option<&str>,
        mut initial_events: Vec<NewEventRecord>,
    ) -> Result<Vec<PersistedEventRecord>> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread_row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("mark_running is fenced during daemon shutdown");
        }
        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing while marking running: {thread_id}"))?;
        if let Some(intent) = runtime.stop_intent {
            bail!(
                "mark_running is fenced after {} request for thread {thread_id}",
                intent.as_str()
            );
        }
        let authoritative_snapshot = authoritative_snapshot_for_transition(
            &g,
            &thread_row.chain_root_id,
            &thread_row.thread_id,
        )?;
        verify_admitted_launch_capsule(
            &self.state_authority,
            &self.bundle_admission_trust,
            &authoritative_snapshot,
            runtime.launch_metadata.as_ref(),
        )?;

        let transition_created = match thread_row.status.as_str() {
            // Fresh launch: fall through to the created -> running transition
            // (appends `thread_started`, sets `started_at`).
            "created" => true,
            // Same-thread crash recovery re-spawns a row that is still `running`,
            // and the resumed runtime calls `mark_running` again. Idempotent
            // no-op: do NOT append a second `thread_started` or rewrite
            // `started_at` — an empty persisted-events list means "already
            // running". (`drain_running_threads` still sees `running`, so the
            // shutdown kill window stays intact — no transient non-running state.)
            "running" if initial_events.is_empty() => return Ok(Vec::new()),
            "running" => false,
            other => {
                bail!("invalid status transition: {other} -> running");
            }
        };

        let snapshot_updates = if transition_created {
            let mut updated_snapshot = authoritative_snapshot;
            let authoritative_base = updated_snapshot
                .project_authority
                .operational_snapshot_projection()
                .map(str::to_owned);
            if let Some(requested_base) = base_project_snapshot_hash
                && Some(requested_base) != authoritative_base.as_deref()
            {
                bail!(
                    "mark_running project snapshot mismatch for {thread_id}: authoritative {:?}, requested {:?}",
                    authoritative_base,
                    requested_base,
                );
            }

            let now = lillux::time::iso8601_now();
            updated_snapshot.status = ThreadStatus::Running;
            updated_snapshot.updated_at.clone_from(&now);
            updated_snapshot.started_at = Some(now);
            updated_snapshot.finished_at = None;
            updated_snapshot.base_project_snapshot_hash = authoritative_base;
            initial_events.push(NewEventRecord {
                event_type: "thread_started".to_string(),
                storage_class: "indexed".to_string(),
                payload: json!({}),
            });
            vec![SnapshotUpdate {
                thread_id: thread_id.to_string(),
                new_snapshot: updated_snapshot,
            }]
        } else {
            Vec::new()
        };

        let te = convert_events(&initial_events, &thread_row.chain_root_id, thread_id);
        let result = committed_value(g.state_db.append_events_admitted(
            &thread_row.chain_root_id,
            thread_id,
            te,
            snapshot_updates,
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        )?);

        persisted_from_append(&result, &initial_events)
    }

    #[tracing::instrument(
        name = "state:finalize_thread",
        skip(self, update),
        fields(thread_id = %thread_id, status = %update.status)
    )]
    pub fn finalize_thread(
        &self,
        thread_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.finalize_thread_locked(thread_id, update)
            .map(|(events, _)| events)
    }

    /// Generic lifecycle finalization that also returns the effective record
    /// after global durable-stop dominance. Higher layers must use this form so
    /// scheduler/command/follow side effects match the persisted terminal event.
    pub fn finalize_thread_effective(
        &self,
        thread_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<(Vec<PersistedEventRecord>, FinalizeThreadRecord)> {
        self.finalize_thread_locked(thread_id, update)
    }

    pub fn finalize_thread_effective_owned(
        &self,
        thread_id: &str,
        launch_owner: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<(Vec<PersistedEventRecord>, FinalizeThreadRecord)> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let claim = g
            .runtime_db
            .get_launch_claim(thread_id)?
            .ok_or_else(|| anyhow::anyhow!("thread {thread_id} has no launch owner"))?;
        if claim.claimed_by != launch_owner {
            anyhow::bail!("stale launch owner cannot finalize thread {thread_id}");
        }
        self.finalize_thread_with_guard(
            &g,
            permit.cas_guard(),
            thread_id,
            update,
            false,
            Some(&claim.owner),
        )
    }

    fn finalize_thread_locked(
        &self,
        thread_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<(Vec<PersistedEventRecord>, FinalizeThreadRecord)> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        self.finalize_thread_with_guard(&g, permit.cas_guard(), thread_id, update, false, None)
    }

    /// Atomically finalize a child-link failure only while the child is still a
    /// never-launched row. This conditional transition is deliberately allowed
    /// after shutdown admission closes: unlike a generic finalizer, the guarded
    /// row has no process for shutdown to own and no launcher entitled to attach
    /// one. A durable stop still dominates the requested failure outcome.
    pub fn finalize_created_unattached_if_current(
        &self,
        thread_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<FinalizeCreatedUnattachedOutcome> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread_row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;

        if is_terminal_status(&thread_row.status) {
            return Ok(FinalizeCreatedUnattachedOutcome::AlreadyTerminal);
        }

        // Birth can commit before the runtime row is installed. Absence is an
        // exact unattached state for this conditional transition, not an
        // error; the launch-claim check below still fences a concurrent owner.
        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .unwrap_or_default();
        let process_attached =
            runtime.pid.is_some() || runtime.pgid.is_some() || runtime.process_identity.is_some();
        let launch_claimed = g.runtime_db.get_launch_claim(thread_id)?.is_some();
        if thread_row.status != ThreadStatus::Created.as_str() || process_attached || launch_claimed
        {
            return Ok(FinalizeCreatedUnattachedOutcome::NotCurrent {
                status: thread_row.status,
                process_attached,
                launch_claimed,
            });
        }

        let (persisted, effective) = self.finalize_thread_with_rows(
            &g,
            permit.cas_guard(),
            thread_id,
            thread_row,
            runtime,
            update,
            true,
            None,
        )?;
        Ok(FinalizeCreatedUnattachedOutcome::Finalized {
            persisted,
            effective: Box::new(effective),
        })
    }

    /// Atomically finalize a nonterminal row, or report the terminal/shutdown
    /// winner without a check-then-write race. A durable Cancel/Kill tombstone
    /// is folded into the effective terminal record by
    /// `Self::finalize_thread_with_rows`.
    pub fn finalize_if_nonterminal(
        &self,
        thread_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<FinalizeIfNonterminalOutcome> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread_row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;
        if is_terminal_status(&thread_row.status) {
            return Ok(FinalizeIfNonterminalOutcome::AlreadyTerminal {
                status: thread_row.status,
            });
        }
        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing during finalization: {thread_id}"))?;
        if runtime.stop_intent.is_none()
            && !self
                .process_attachment_admission_open
                .load(Ordering::Acquire)
        {
            g.runtime_db.reset_resume_attempts(thread_id)?;
            return Ok(FinalizeIfNonterminalOutcome::PreservedForShutdown);
        }
        let (persisted, effective) = self.finalize_thread_with_rows(
            &g,
            permit.cas_guard(),
            thread_id,
            thread_row,
            runtime,
            update,
            false,
            None,
        )?;
        Ok(FinalizeIfNonterminalOutcome::Finalized {
            persisted,
            effective: Box::new(effective),
        })
    }

    /// Reservation-qualified no-replay finalization driven exclusively by the
    /// authoritative root snapshot. Replaceable projection status must not
    /// decide whether an ownerless in-process service remains running.
    ///
    /// `None` means a live owner appeared before the mutation lock and retains
    /// terminal authority.
    pub fn finalize_ownerless_in_process_handler_if_nonterminal(
        &self,
        thread_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<Option<FinalizeIfNonterminalOutcome>> {
        let permit = self.acquire_write_permit()?;
        let active = self
            .active_in_process_handlers
            .lock()
            .map_err(|_| anyhow!("active in-process-handler registry poisoned"))?;
        if active.contains_key(thread_id) {
            return Ok(None);
        }
        let g = self.lock()?;
        let reservation = g
            .runtime_db
            .in_process_handler_reservation(thread_id)?
            .ok_or_else(|| {
                anyhow!("ownerless in-process handler {thread_id} has no durable reservation")
            })?;
        let chain_root_id = in_process_handler_chain_root_locked(&g, thread_id)?;
        if reservation.phase == runtime_db::InProcessHandlerReservationPhase::TerminalConfirmed {
            let snapshot = g
                .state_db
                .read_authoritative_thread_snapshot(&chain_root_id, thread_id)?
                .ok_or_else(|| {
                    anyhow!(
                        "terminal-confirmed in-process handler {thread_id} has no authoritative thread"
                    )
                })?;
            if !snapshot.status.is_terminal() {
                bail!(
                    "terminal-confirmed in-process handler {thread_id} contradicts authoritative status {}",
                    snapshot.status.as_str()
                );
            }
            return Ok(Some(FinalizeIfNonterminalOutcome::AlreadyTerminal {
                status: snapshot.status.as_str().to_string(),
            }));
        }
        let snapshot = g
            .state_db
            .read_authoritative_thread_snapshot(&chain_root_id, thread_id)?
            .ok_or_else(|| {
                anyhow!("ownerless in-process handler {thread_id} has no authoritative thread")
            })?;
        if snapshot.status.is_terminal() {
            return Ok(Some(FinalizeIfNonterminalOutcome::AlreadyTerminal {
                status: snapshot.status.as_str().to_string(),
            }));
        }
        if snapshot.status != ThreadStatus::Running {
            bail!(
                "ownerless in-process handler {thread_id} has authoritative status {} instead of running",
                snapshot.status.as_str()
            );
        }
        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing during finalization: {thread_id}"))?;
        let metadata = runtime
            .launch_metadata
            .as_ref()
            .ok_or_else(|| anyhow!("ownerless in-process handler has no launch metadata"))?;
        if metadata.launch_driver
            != Some(ryeos_state::objects::ExecutionLaunchDriver::InProcessHandler)
            || metadata.lifecycle_authority()?
                != Some(ryeos_state::objects::ExecutionLifecycleAuthority::DAEMON_NON_RECOVERABLE)
        {
            bail!("ownerless in-process handler runtime authority is inconsistent");
        }
        let thread_row = queries::ThreadRow {
            thread_id: snapshot.thread_id.clone(),
            chain_root_id: snapshot.chain_root_id.clone(),
            kind: snapshot.kind_name.clone(),
            status: snapshot.status.as_str().to_string(),
            item_ref: snapshot.item_ref.clone(),
            executor_ref: snapshot.executor_ref.clone(),
            launch_mode: snapshot.launch_mode.clone(),
            current_site_id: snapshot.current_site_id.clone(),
            origin_site_id: snapshot.origin_site_id.clone(),
            upstream_thread_id: snapshot.upstream_thread_id.clone(),
            requested_by: snapshot.requested_by.clone(),
            project_root: snapshot
                .project_root
                .as_ref()
                .map(|path| path.display().to_string()),
            project_authority: snapshot.project_authority.clone(),
            admitted_launch_capsule_hash: snapshot.admitted_launch_capsule_hash.clone(),
            base_project_snapshot_hash: snapshot.base_project_snapshot_hash.clone(),
            result_project_snapshot_hash: snapshot.result_project_snapshot_hash.clone(),
            result_workspace_output_capture_hash: snapshot
                .result_workspace_output_capture_hash
                .clone(),
            captured_history_policy: snapshot.captured_history_policy.clone(),
            created_at: snapshot.created_at.clone(),
            updated_at: snapshot.updated_at.clone(),
            started_at: snapshot.started_at.clone(),
            finished_at: snapshot.finished_at.clone(),
        };
        let (persisted, effective) = self.finalize_thread_with_rows(
            &g,
            permit.cas_guard(),
            thread_id,
            thread_row,
            runtime,
            update,
            false,
            None,
        )?;
        Ok(Some(FinalizeIfNonterminalOutcome::Finalized {
            persisted,
            effective: Box::new(effective),
        }))
    }

    /// Owner-qualified form of [`Self::finalize_if_nonterminal`] for daemon
    /// supervised method/runtime completion. The terminal check, exact owner
    /// comparison, stop dominance, and winning write share one StateStore lock.
    pub fn finalize_if_nonterminal_owned(
        &self,
        thread_id: &str,
        launch_owner: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<FinalizeIfNonterminalOutcome> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread_row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;
        if is_terminal_status(&thread_row.status) {
            return Ok(FinalizeIfNonterminalOutcome::AlreadyTerminal {
                status: thread_row.status,
            });
        }
        let claim = g
            .runtime_db
            .get_launch_claim(thread_id)?
            .ok_or_else(|| anyhow!("thread {thread_id} has no launch owner"))?;
        if claim.claimed_by != launch_owner {
            bail!("stale launch owner cannot finalize thread {thread_id}");
        }
        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing during finalization: {thread_id}"))?;
        if runtime.stop_intent.is_none()
            && !self
                .process_attachment_admission_open
                .load(Ordering::Acquire)
        {
            g.runtime_db.reset_resume_attempts(thread_id)?;
            return Ok(FinalizeIfNonterminalOutcome::PreservedForShutdown);
        }
        let (persisted, effective) = self.finalize_thread_with_rows(
            &g,
            permit.cas_guard(),
            thread_id,
            thread_row,
            runtime,
            update,
            false,
            Some(&claim.owner),
        )?;
        Ok(FinalizeIfNonterminalOutcome::Finalized {
            persisted,
            effective: Box::new(effective),
        })
    }

    fn finalize_thread_with_guard(
        &self,
        g: &Inner,
        cas_mutation_guard: &ryeos_state::CasMutationGuard,
        thread_id: &str,
        update: &FinalizeThreadRecord,
        allow_closed_admission: bool,
        owned_launch_owner: Option<&runtime_db::LaunchOwner>,
    ) -> Result<(Vec<PersistedEventRecord>, FinalizeThreadRecord)> {
        let thread_row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;
        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing during finalization: {thread_id}"))?;
        self.finalize_thread_with_rows(
            g,
            cas_mutation_guard,
            thread_id,
            thread_row,
            runtime,
            update,
            allow_closed_admission,
            owned_launch_owner,
        )
    }

    /// This runs inside the existing StateStore writer exclusion, retained
    /// through the signed terminal CAS commit below. Every production runtime
    /// mutation uses the same private Inner guard; a returned output projection
    /// is not a reusable finalization capability outside this critical section.
    fn validate_external_direct_finalization_locked(
        &self,
        inner: &Inner,
        thread_id: &str,
        chain_root_id: &str,
        update: &FinalizeThreadRecord,
    ) -> Result<()> {
        use runtime_db::external_execution::ExternalAllocationOwner;
        let snapshot = authoritative_snapshot_for_transition(inner, chain_root_id, thread_id)?;
        let capsule = snapshot
            .admitted_launch_capsule_hash
            .as_deref()
            .map(|hash| {
                load_admitted_launch_capsule(
                    &self.state_authority,
                    &self.bundle_admission_trust,
                    hash,
                )
            })
            .transpose()?;
        let is_external = capsule
            .as_ref()
            .map(crate::thread_lifecycle::capsule_requires_external_direct)
            .transpose()?
            .unwrap_or(false);
        let allocation = inner.runtime_db.external_allocation(thread_id)?;
        if !is_external {
            anyhow::ensure!(
                !allocation.as_ref().is_some_and(|allocation| matches!(
                    allocation.reservation.owner,
                    ExternalAllocationOwner::DirectThread { .. }
                )),
                "external direct allocation has no authoritative external capsule"
            );
            return Ok(());
        }
        anyhow::ensure!(
            update.status != ThreadStatus::Continued.as_str(),
            "one-shot external direct execution cannot author a continuation"
        );
        anyhow::ensure!(
            update.result_project_snapshot_hash.is_none()
                && update.result_workspace_output_capture_hash.is_none()
                && update.managed_envelope.is_none()
                && update.artifacts.is_empty()
                && update.final_cost.is_none(),
            "external direct execution cannot add unadmitted artifacts, cost or project publication"
        );
        // A substrate/administrative failure may settle the thread without
        // inventing a target result. The external cleanup obligation remains in
        // its existing journal; a null local PID is never its death proof.
        if update.status != ThreadStatus::Completed.as_str() && update.result_json.is_none() {
            return Ok(());
        }
        let allocation = allocation.context("external direct result has no allocation evidence")?;
        let ExternalAllocationOwner::DirectThread {
            chain_root_id: retained_root,
            program,
            ..
        } = &allocation.reservation.owner
        else {
            bail!("external direct result has a different allocation owner");
        };
        anyhow::ensure!(
            snapshot.thread_id == thread_id
                && snapshot.chain_root_id == *retained_root
                && snapshot.admitted_launch_capsule_hash.as_deref()
                    == Some(allocation.reservation.admitted_capsule_hash.as_str()),
            "external direct finalization changed its authoritative born capsule"
        );
        let capsule = capsule.context("external direct result lost its authoritative capsule")?;
        let endpoint =
            crate::thread_lifecycle::validate_retained_external_direct_program(&capsule, program)?;
        anyhow::ensure!(
            capsule.project_authority == snapshot.project_authority
                && capsule.executor_ref == snapshot.executor_ref
                && endpoint.binding_digest == allocation.reservation.binding_hash,
            "external direct finalization changed its admitted program or project authority"
        );
        anyhow::ensure!(
            matches!(&capsule.project_authority,
                ryeos_state::objects::ExecutionProjectAuthority::PinnedGeneration {
                    snapshot_hash,
                    realization: ryeos_state::objects::PinnedProjectRealization::ReadOnly,
                    environment: ryeos_state::objects::EnvironmentAuthority::None,
                    workspace_outputs: None, ..
                } if snapshot_hash == &allocation.reservation.base_snapshot_hash),
            "external direct finalization lost its immutable admitted generation"
        );
        let claim = inner
            .runtime_db
            .get_launch_claim(thread_id)?
            .context("external direct finalization has no current settlement owner")?;
        let output = inner
            .runtime_db
            .external_direct_finalization_output(thread_id, &claim.claimed_by)?;
        validate_external_direct_result(update, &output)
    }

    #[allow(clippy::too_many_arguments)]
    fn finalize_thread_with_rows(
        &self,
        g: &Inner,
        cas_mutation_guard: &ryeos_state::CasMutationGuard,
        thread_id: &str,
        thread_row: queries::ThreadRow,
        runtime: RuntimeInfo,
        update: &FinalizeThreadRecord,
        allow_closed_admission: bool,
        owned_launch_owner: Option<&runtime_db::LaunchOwner>,
    ) -> Result<(Vec<PersistedEventRecord>, FinalizeThreadRecord)> {
        if g.runtime_db
            .has_unsettled_scoped_child_for_thread(thread_id)?
        {
            bail!("thread finalization requires exact scoped child retirement");
        }
        let validated_final_cost = update
            .final_cost
            .as_ref()
            .map(validate_final_cost)
            .transpose()?;
        let mut effective_update = update.clone();
        // Stop intent dominates every later finalizer, including administrative
        // failure nets. This is intentionally global: a check-then-finalize
        // caller must not be able to overwrite a stop that committed between
        // its check and this lock acquisition.
        if let Some(intent) = runtime.stop_intent {
            let status = match intent {
                StopIntent::Cancel => ThreadStatus::Cancelled,
                StopIntent::Kill => ThreadStatus::Killed,
            };
            effective_update.status = status.as_str().to_string();
            effective_update.outcome_code = Some(status.as_str().to_string());
            effective_update.result_json = None;
            effective_update.error_json = Some(json!({
                "reason": "durable_stop_intent",
                "intent": intent.as_str(),
            }));
            // The runtime supplied envelope describes its reported outcome,
            // not the daemon-owned durable-stop winner above. Never sign that
            // contradictory process claim into the effective terminal
            // snapshot. Incurred cost remains authoritative and is retained.
            effective_update.managed_envelope = None;
            effective_update.result_project_snapshot_hash = None;
            effective_update.result_workspace_output_capture_hash = None;
        } else if !allow_closed_admission
            && !self
                .process_attachment_admission_open
                .load(Ordering::Acquire)
        {
            // Every terminal writer shares the shutdown fence. Otherwise an
            // execution-result fallback could turn a shutdown-owned kill into a
            // terminal failure after drain had taken ownership of the process.
            // A durable stop remains the one exception: it must be allowed to
            // settle to its dominant cancelled/killed outcome while draining.
            bail!("thread finalization is fenced during daemon shutdown");
        }
        let update = &effective_update;

        if is_terminal_status(&thread_row.status) {
            bail!(
                "invalid status transition: {} -> {}",
                thread_row.status,
                update.status
            );
        }

        let terminal_status = ThreadStatus::from_str_lossy(&update.status)
            .ok_or_else(|| anyhow!("invalid terminal status: {}", update.status))?;
        if !terminal_status.is_terminal() {
            bail!("finalize_thread requires a terminal status");
        }
        self.validate_external_direct_finalization_locked(
            g,
            thread_id,
            &thread_row.chain_root_id,
            update,
        )?;
        if let Some(cost) = update.final_cost.as_ref() {
            validate_final_cost_for_settlement(cost)?;
        }
        let (result_size_bytes, error_size_bytes) =
            ryeos_state::objects::validate_thread_result_content(
                update.result_json.as_ref(),
                update.error_json.as_ref(),
            )?;
        if let Some(envelope) = update.managed_envelope.as_ref() {
            validate_managed_terminal_envelope(
                envelope,
                thread_id,
                terminal_status,
                update.result_json.as_ref(),
                update.error_json.as_ref(),
                update.final_cost.as_ref(),
            )?;
        }

        let (additional_artifact_kind_bytes, additional_artifact_metadata_bytes) =
            update.artifacts.iter().try_fold(
                (0usize, 0usize),
                |(kind_total, metadata_total), artifact| {
                    let metadata_bytes = validate_new_artifact_shape(
                        &artifact.artifact_type,
                        artifact.metadata.as_ref(),
                    )?;
                    Ok::<_, anyhow::Error>((
                        kind_total
                            .checked_add(artifact.artifact_type.len())
                            .ok_or_else(|| anyhow!("terminal artifact kind byte total overflow"))?,
                        metadata_total.checked_add(metadata_bytes).ok_or_else(|| {
                            anyhow!("terminal artifact metadata byte total overflow")
                        })?,
                    ))
                },
            )?;
        if !update.artifacts.is_empty() {
            if !self.projection_health.is_current() {
                bail!("artifact admission requires a current thread projection");
            }
            ensure_artifact_projection_capacity(
                g,
                thread_id,
                update.artifacts.len(),
                additional_artifact_kind_bytes,
                additional_artifact_metadata_bytes,
            )?;
        }

        let now = lillux::time::iso8601_now();
        let facets = terminal_facets(update.final_cost.as_ref())?;
        let managed_runtime_terminal =
            managed_runtime_terminal_supplement(update.managed_envelope.as_ref())?;

        let artifacts_json: Vec<Value> = update
            .artifacts
            .iter()
            .map(|a| serde_json::to_value(a).unwrap())
            .collect();

        let mut updated_snapshot = authoritative_snapshot_for_transition(
            g,
            &thread_row.chain_root_id,
            &thread_row.thread_id,
        )?;
        let usage_started_at = updated_snapshot
            .started_at
            .clone()
            .unwrap_or_else(|| updated_snapshot.created_at.clone());
        updated_snapshot.status = terminal_status;
        updated_snapshot.updated_at.clone_from(&now);
        updated_snapshot.finished_at = Some(now.clone());
        updated_snapshot.result.clone_from(&update.result_json);
        updated_snapshot
            .outcome_code
            .clone_from(&update.outcome_code);
        updated_snapshot.error.clone_from(&update.error_json);
        updated_snapshot.budget = validated_final_cost.as_ref().map(|cost| {
            ThreadUsage {
                completed_turns: cost.completed_turns,
                input_tokens: cost.input_tokens,
                output_tokens: cost.output_tokens,
                spend_usd: cost.spend_usd,
                spawns_used: 0, // not tracked in FinalCost
                started_at: usage_started_at.clone(),
                settled_at: now.clone(),
                last_settled_turn_seq: u64::from(cost.completed_turns),
                elapsed_ms: 0, // daemon doesn't track wall-clock time
                provider_id: None,
                model: None,
                profile: None,
            }
        });
        updated_snapshot.artifacts = artifacts_json;
        updated_snapshot.managed_runtime_terminal = managed_runtime_terminal;
        updated_snapshot.facets = facets;
        updated_snapshot
            .result_project_snapshot_hash
            .clone_from(&update.result_project_snapshot_hash);
        updated_snapshot
            .result_workspace_output_capture_hash
            .clone_from(&update.result_workspace_output_capture_hash);
        updated_snapshot
            .verify_result_workspace_output_capture(&self.state_authority.cas_store()?)?;

        let snapshot_update = SnapshotUpdate {
            thread_id: thread_id.to_string(),
            new_snapshot: updated_snapshot,
        };

        let mut events_to_append = Vec::new();

        for artifact in &update.artifacts {
            events_to_append.push(NewEventRecord {
                event_type: "artifact_published".to_string(),
                storage_class: "indexed".to_string(),
                payload: json!({
                    "artifact_type": artifact.artifact_type,
                    "uri": artifact.uri,
                    "content_hash": artifact.content_hash,
                    "metadata": artifact.metadata,
                }),
            });
        }

        // A terminal event is a bounded lifecycle fact, not a second result
        // store. The complete result/error remain authoritative in the thread
        // snapshot committed by this same head transition. Hashes let an event
        // consumer correlate those values without embedding them again.
        let mut terminal_payload = json!({
            "result_project_snapshot_hash": update.result_project_snapshot_hash,
            "result_workspace_output_capture_hash": update.result_workspace_output_capture_hash,
            "outcome_code": update.outcome_code,
            "result_present": update.result_json.is_some(),
            "result_size_bytes": result_size_bytes,
            "result_digest": terminal_value_digest(update.result_json.as_ref(), "result")?,
            "has_error": update.error_json.is_some(),
            "error_size_bytes": error_size_bytes,
            "error_digest": terminal_value_digest(update.error_json.as_ref(), "error")?,
            "artifact_count": update.artifacts.len(),
        });
        // This reference is daemon-derived under the same launch-owner lock
        // as the signed terminal. The operational slot alone is mutable and
        // must never qualify a later attempt; an unowned or non-completed
        // finalizer cannot mint this bridge.
        if terminal_status == ThreadStatus::Completed
            && runtime.process_identity.is_none()
            && let Some(owner) = owned_launch_owner
            && let Some(settlement) = g.runtime_db.latest_thread_process_settlement(thread_id)?
            && settlement.launch_owner == *owner
            && matches!(
                settlement.kind,
                runtime_db::ThreadProcessSettlementKind::ReapedScopeEmpty
                    | runtime_db::ThreadProcessSettlementKind::ReapedGroupAbsent
            )
        {
            terminal_payload["process_settlement_witness_digest"] =
                Value::String(settlement.digest()?);
        }
        if let Some(err) = &update.error_json
            && let Some(map) = terminal_payload.as_object_mut()
        {
            if error_size_bytes <= MAX_TERMINAL_EVENT_INLINE_ERROR_BYTES {
                map.insert("error".to_string(), err.clone());
            } else {
                map.insert("error_omitted".to_string(), Value::Bool(true));
                map.insert(
                    "error_preview".to_string(),
                    Value::String(
                        "terminal error exceeds the event inline limit; inspect the thread for the full error"
                            .to_string(),
                    ),
                );
            }
        }
        events_to_append.push(NewEventRecord {
            event_type: terminal_event_type(&update.status)?.to_string(),
            storage_class: "indexed".to_string(),
            payload: terminal_payload,
        });

        let te = convert_events(&events_to_append, &thread_row.chain_root_id, thread_id);
        let result = committed_value(g.state_db.append_events_admitted(
            &thread_row.chain_root_id,
            thread_id,
            te,
            vec![snapshot_update],
            g.signer.as_ref(),
            &g.runtime_db,
            cas_mutation_guard,
        )?);

        Ok((
            persisted_from_append(&result, &events_to_append)?,
            effective_update,
        ))
    }

    #[tracing::instrument(
        name = "state:create_continuation",
        skip(self, successor),
        fields(
            thread_id = %successor.thread_id,
            chain_root_id = %chain_root_id,
            source_thread_id = %source_thread_id,
        )
    )]
    pub(crate) fn create_continuation_admitted(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
        initial_events: Vec<NewEventRecord>,
        launch_metadata: Option<&crate::launch_metadata::RuntimeLaunchMetadata>,
    ) -> Result<CreatedThreadPublication> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let launch_planning = g
            .runtime_db
            .launch_planning_by_thread(&successor.thread_id)?;
        if let Some(planning) = launch_planning.as_ref() {
            if planning.state != "planning"
                || planning.daemon_generation_id != runtime_db::daemon_generation_id()
            {
                return Err(LaunchPlanningInactive.into());
            }
            validate_launch_planning_owner(planning, successor.requested_by.as_deref())?;
        }
        validate_facet_event_admission(&g, &successor.thread_id, &initial_events)?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("continuation creation is closed for daemon shutdown");
        }
        let source_row = g
            .state_db
            .get_thread(source_thread_id)?
            .ok_or_else(|| anyhow!("source thread not found: {source_thread_id}"))?;

        if is_terminal_status(&source_row.status)
            && source_row.status != ThreadStatus::Failed.as_str()
            && source_row.status != ThreadStatus::Completed.as_str()
        {
            bail!(
                "cannot continue thread in terminal status '{}'",
                source_row.status
            );
        }

        // Single-successor invariant: a thread is continued at most once. The
        // write permit + lock held here serialize `create_continuation`, so this
        // check-then-create is atomic — a double-submit or race cannot mint
        // sibling successors (which would make `successor_thread_id` ambiguous).
        if let Some(existing) =
            queries::continuation_successor(g.state_db.projection(), source_thread_id)?
        {
            bail!("thread {source_thread_id} already continued as {existing}");
        }

        // Ensure successor has upstream_thread_id set to source for edge derivation
        let mut successor_with_upstream = successor.clone();
        if successor_with_upstream.upstream_thread_id.is_none() {
            successor_with_upstream.upstream_thread_id = Some(source_thread_id.to_string());
        }
        let (successor_snapshot, source_snapshot_before) = attach_continuation_launch_capsule(
            &self.state_authority,
            &self.bundle_admission_trust,
            permit.cas_guard(),
            &g,
            build_snapshot(&successor_with_upstream),
            ContinuationCapsuleTransition {
                chain_root_id,
                source_thread_id,
                launch_metadata,
                expected_result_generation: None,
                kind: crate::launch_metadata::ContinuationAuthorityTransitionKind::Inherit,
            },
        )?;
        // Predecessor-immutability contract: terminal sources retain their
        // exact snapshot, while a running source is settled to `continued` in
        // the same signed head as the successor.
        let source_snapshot_updated = !is_terminal_status(&source_row.status);
        let source_snapshot_after = if source_snapshot_updated {
            continued_snapshot_from_authoritative(
                source_snapshot_before.clone(),
                &lillux::time::iso8601_now(),
            )
        } else {
            source_snapshot_before.clone()
        };
        let source_snapshot_updates = source_snapshot_updated
            .then(|| SnapshotUpdate {
                thread_id: source_thread_id.to_string(),
                new_snapshot: source_snapshot_after.clone(),
            })
            .into_iter()
            .collect();
        let successor_runtime = RuntimeInfo {
            launch_metadata: launch_metadata.cloned(),
            ..RuntimeInfo::default()
        };
        {
            let _admission = g.state_db.authorize_runtime_pin(chain_root_id)?;
            g.runtime_db
                .insert_thread_runtime(&successor.thread_id, chain_root_id)?;
            if let Some(launch_metadata) = launch_metadata
                && let Err(error) = g
                    .runtime_db
                    .set_launch_metadata(&successor.thread_id, launch_metadata)
            {
                let _ = self.delete_thread_runtime_locked(&g, &successor.thread_id);
                return Err(error);
            }
        }

        let successor_event = NewEventRecord {
            event_type: "thread_created".to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "kind": &successor.kind,
                "item_ref": &successor.item_ref,
                "continuation_from": source_thread_id,
            }),
        };
        let mut successor_events = Vec::with_capacity(initial_events.len() + 1);
        successor_events.push(successor_event);
        successor_events.extend(initial_events);
        let successor_thread_events =
            convert_events(&successor_events, chain_root_id, &successor.thread_id);
        let expected_successor_events = successor_thread_events.clone();
        let source_event = NewEventRecord {
            event_type: "thread_continued".to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "successor_thread_id": &successor.thread_id,
                "reason": reason,
            }),
        };
        let ste = convert_events(
            std::slice::from_ref(&source_event),
            chain_root_id,
            source_thread_id,
        );
        let expected_source_event = ste
            .first()
            .cloned()
            .expect("continuation source event batch is non-empty");
        let expected_successor_snapshot = successor_snapshot.clone();
        let successor_commit = g.state_db.add_thread_with_events_and_append_admitted(
            chain_root_id,
            successor_snapshot,
            successor_thread_events,
            source_thread_id,
            ste,
            source_snapshot_updates,
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        );
        let successor_result = match successor_commit {
            Ok(committed) => committed_value(committed),
            Err(error) => {
                match read_exact_committed_continuation(
                    &g,
                    chain_root_id,
                    ExpectedContinuationCommit {
                        source_thread_id,
                        source_before: &source_snapshot_before,
                        source_after: &source_snapshot_after,
                        source_snapshot_updated,
                        source_event: &expected_source_event,
                        successor_snapshot: &expected_successor_snapshot,
                        successor_events: &expected_successor_events,
                    },
                ) {
                    Ok(ContinuationCommitReadback::Exact(snapshot)) => {
                        // `StateDb` can report a journal phase-advance error
                        // after the signed head is already visible. Continue
                        // from the exact source/successor pair instead of
                        // deleting the runtime authority needed to launch it.
                        if let Some(planning) = launch_planning.as_ref() {
                            match g.runtime_db.bind_launch_planning(&successor.thread_id) {
                                Ok(true) => {}
                                Ok(false) => tracing::error!(
                                    thread_id = %successor.thread_id,
                                    launch_id = %planning.launch_id,
                                    "authoritative continuation committed but launch planning bind changed no row"
                                ),
                                Err(bind_error) => tracing::error!(
                                    thread_id = %successor.thread_id,
                                    launch_id = %planning.launch_id,
                                    error = %bind_error,
                                    "authoritative continuation committed but launch planning bind failed"
                                ),
                            }
                            match self.launch_task_abort_handles.lock() {
                                Ok(mut handles) => {
                                    handles.remove(&planning.launch_id);
                                }
                                Err(poisoned) => {
                                    tracing::error!(
                                        thread_id = %successor.thread_id,
                                        launch_id = %planning.launch_id,
                                        "launch task abort registry was poisoned after continuation commit"
                                    );
                                    poisoned.into_inner().remove(&planning.launch_id);
                                }
                            }
                        }
                        tracing::error!(
                            thread_id = %successor.thread_id,
                            source_thread_id,
                            error = %error,
                            "continuation creation returned an error after publishing authoritative state; continuing from exact committed pair"
                        );
                        return Ok(CreatedThreadPublication {
                            persisted: Vec::new(),
                            successor: thread_detail_from_committed_snapshot(
                                *snapshot,
                                successor_runtime,
                            ),
                            remote_writer_grant_hash: None,
                        });
                    }
                    Err(authority_error) => {
                        return Err(anyhow!(
                            "continuation creation failed and authoritative pair readback was unavailable; preserving runtime ownership for reconciliation: write error: {error:#}; readback error: {authority_error:#}"
                        ));
                    }
                    Ok(ContinuationCommitReadback::Ambiguous(reason)) => {
                        return Err(anyhow!(
                            "continuation creation failed with ambiguous authoritative readback; preserving runtime ownership for reconciliation: {reason}; write error: {error:#}"
                        ));
                    }
                    Ok(ContinuationCommitReadback::ProvenAbsent) => {}
                }
                let _selected_exclusion = self.selected_mutation_permit(
                    &g,
                    SelectedMutationOperation::DeleteThread(&successor.thread_id),
                )?;
                if let Err(settle_error) = g.runtime_db.fail_launch_planning(&successor.thread_id) {
                    tracing::error!(
                        thread_id = %successor.thread_id,
                        error = %settle_error,
                        "failed to settle launch planning after continuation creation failed"
                    );
                }
                if let Err(cleanup_error) =
                    self.delete_thread_runtime_locked(&g, &successor.thread_id)
                {
                    tracing::error!(
                        thread_id = %successor.thread_id,
                        error = %cleanup_error,
                        "failed to remove runtime row after atomic continuation birth failed"
                    );
                }
                return Err(error);
            }
        };
        // The signed successor/source transition is authoritative from this
        // point onward. Auxiliary planning and live-notification bookkeeping
        // must not turn that committed continuation into a pre-launch error.
        if let Some(planning) = launch_planning {
            match g.runtime_db.bind_launch_planning(&successor.thread_id) {
                Ok(true) => {}
                Ok(false) => tracing::error!(
                    thread_id = %successor.thread_id,
                    launch_id = %planning.launch_id,
                    "authoritative continuation committed but launch planning bind changed no row"
                ),
                Err(error) => tracing::error!(
                    thread_id = %successor.thread_id,
                    launch_id = %planning.launch_id,
                    error = %error,
                    "authoritative continuation committed but launch planning bind failed"
                ),
            }
            match self.launch_task_abort_handles.lock() {
                Ok(mut handles) => {
                    handles.remove(&planning.launch_id);
                }
                Err(poisoned) => {
                    tracing::error!(
                        thread_id = %successor.thread_id,
                        launch_id = %planning.launch_id,
                        "launch task abort registry was poisoned after continuation commit"
                    );
                    poisoned.into_inner().remove(&planning.launch_id);
                }
            }
        }
        let mut all_input_events = successor_events;
        all_input_events.push(source_event);
        let persisted =
            match persisted_from_add_thread_with_events(&successor_result, &all_input_events) {
                Ok(persisted) => persisted,
                Err(error) => {
                    tracing::error!(
                        thread_id = %successor.thread_id,
                        source_thread_id,
                        chain_root_id,
                        error = %error,
                        "authoritative continuation committed but live event reconstruction failed"
                    );
                    Vec::new()
                }
            };
        let successor =
            thread_detail_from_committed_snapshot(successor_result.snapshot, successor_runtime);
        Ok(CreatedThreadPublication {
            persisted,
            successor,
            remote_writer_grant_hash: None,
        })
    }

    /// Raw continuation fixture for state-layer tests. Absent in production.
    #[cfg(any(test, feature = "test-support"))]
    pub fn create_continuation_for_test(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.create_continuation_admitted(
            successor,
            source_thread_id,
            chain_root_id,
            reason,
            Vec::new(),
            None,
        )
        .map(|publication| publication.persisted)
    }

    /// Machine continuation handoff (limit cut-off) — the autonomous path.
    ///
    /// Unlike the operator-follow-up continuation path, which
    /// accepts a terminal source and leaves it as-is), this enforces the machine
    /// invariants atomically under the write permit + lock:
    ///
    /// - the source must be **exactly `running`** — a cut-off live run. Re-checked
    ///   here, not just by the caller, so a source that goes terminal between the
    ///   caller's check and this commit cannot mint a successor.
    /// - the source must carry a captured `ResumeContext` (spawn-time launch
    ///   identity) — a successor we cannot launch is worse than none.
    /// - the successor's launch metadata is **seeded before the source is settled
    ///   `continued`**, and the runtime-db writes (which can fail independently of
    ///   the source's terminal snapshot) happen first — so any failure aborts the
    ///   handoff with the source still `running` (the runner then fails terminal),
    ///   never `continued` behind an unlaunchable successor.
    pub fn create_machine_continuation(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
    ) -> Result<Vec<PersistedEventRecord>> {
        let sanitized_reason =
            reason.filter(|r| !queries::ContinuationReasonMarker::is_reserved_str(r));
        self.create_running_continuation_successor(
            successor,
            source_thread_id,
            chain_root_id,
            RunningContinuationKind::Machine { sanitized_reason },
            None,
            None,
            None,
            Vec::new(),
        )
        .map(|publication| publication.persisted)
    }

    // Source lineage, resume proof, launch metadata, and initial durable events
    // stay explicit because each is validated under the same write permit.
    #[allow(clippy::too_many_arguments)]
    pub fn create_machine_continuation_with_events(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
        expected_resume_context: &crate::launch_metadata::ResumeContext,
        successor_launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        initial_events: Vec<NewEventRecord>,
    ) -> Result<(Vec<PersistedEventRecord>, ThreadDetail)> {
        // The machine handoff carries a free-form runtime LOG reason. Scrub ALL
        // daemon-reserved markers so a runtime cannot mint an edge the chain-depth
        // walk would treat as an operator reset or a depth-exempt follow.
        let sanitized_reason =
            reason.filter(|r| !queries::ContinuationReasonMarker::is_reserved_str(r));
        self.create_running_continuation_successor(
            successor,
            source_thread_id,
            chain_root_id,
            RunningContinuationKind::Machine { sanitized_reason },
            Some(expected_resume_context),
            Some(successor_launch_metadata),
            None,
            initial_events,
        )
        .map(|publication| (publication.persisted, publication.successor))
    }

    /// Daemon-owned machine continuation that advances an exact frozen pinned
    /// CoW generation.  The ordinary runtime callback cannot select this
    /// value; checkpoint/handoff code supplies the CAS-proved candidate and
    /// the shared continuation transaction verifies the typed authority
    /// transition before publishing either side.
    pub fn create_machine_continuation_with_project_generation(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
        expected_resume_context: &crate::launch_metadata::ResumeContext,
        successor_launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        source_result_snapshot_hash: Option<&str>,
        initial_events: Vec<NewEventRecord>,
    ) -> Result<(Vec<PersistedEventRecord>, ThreadDetail)> {
        let sanitized_reason =
            reason.filter(|reason| !queries::ContinuationReasonMarker::is_reserved_str(reason));
        // This source-only entry point serves retained worker candidates, which
        // have no output partition. The shared typed transition refuses an
        // output-bearing source rather than dropping its capture authority.
        let generation = source_result_snapshot_hash.map(|snapshot_hash| {
            ryeos_state::objects::WorkspaceGenerationPair {
                snapshot_hash: snapshot_hash.to_owned(),
                output_capture_hash: None,
            }
        });
        self.create_running_continuation_successor(
            successor,
            source_thread_id,
            chain_root_id,
            RunningContinuationKind::Machine { sanitized_reason },
            Some(expected_resume_context),
            Some(successor_launch_metadata),
            generation.as_ref(),
            initial_events,
        )
        .map(|publication| (publication.persisted, publication.successor))
    }

    /// Atomically terminalize the exact quiesced source placement and author
    /// one target-site successor without creating a runnable source-node
    /// runtime row. The ordinary running-continuation transaction remains the
    /// sole single-successor serialization boundary.
    pub fn create_remote_adoption_successor(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        authority: &RemoteAdoptionContinuationAuthority,
    ) -> Result<RemoteAdoptionPublication> {
        let publication = self.create_running_continuation_successor(
            successor,
            source_thread_id,
            chain_root_id,
            RunningContinuationKind::RemoteAdoption { authority },
            None,
            None,
            Some(&ryeos_state::objects::WorkspaceGenerationPair {
                snapshot_hash: authority
                    .placement
                    .project_rebind
                    .source_candidate_snapshot_hash
                    .clone(),
                output_capture_hash: None,
            }),
            Vec::new(),
        )?;
        Ok(RemoteAdoptionPublication {
            successor_thread_id: successor.thread_id.clone(),
            writer_grant_hash: publication.remote_writer_grant_hash.ok_or_else(|| {
                anyhow!("remote adoption committed without its chain-writer grant identity")
            })?,
            target_launch_capsule_hash: authority.placement.target_launch_capsule_hash.clone(),
            target_runtime_seed_hash: authority.placement.target_runtime_seed_hash.clone(),
        })
    }

    /// Create the parent's follow-resume successor: a running-source continuation
    /// marked `graph_follow_resume`. Created and seeded only — NOT launched (the
    /// resume path launches it later, once the child's result is available) and
    /// NOT subject to the autonomous chain-depth cap (a follow is structural
    /// progress, not an autonomous run). Daemon-only: the trusted marker cannot be
    /// reached through a runtime-supplied reason. The running source must declare
    /// native resume, and that exact policy is projected into the successor so a
    /// resumed segment remains eligible to suspend at another follow node.
    pub fn create_follow_resume_successor(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
    ) -> Result<Vec<PersistedEventRecord>> {
        self.create_running_continuation_successor(
            successor,
            source_thread_id,
            chain_root_id,
            RunningContinuationKind::GraphFollowResume,
            None,
            None,
            None,
            Vec::new(),
        )
        .map(|publication| publication.persisted)
    }

    pub fn create_follow_resume_successor_with_launch_metadata(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        successor_launch_metadata: &crate::launch_metadata::RuntimeLaunchMetadata,
        result_generation: Option<&ryeos_state::objects::WorkspaceGenerationPair>,
    ) -> Result<Vec<PersistedEventRecord>> {
        if let Some(generation) = result_generation {
            generation.validate()?;
            if successor
                .project_authority
                .operational_snapshot_projection()
                != Some(generation.snapshot_hash.as_str())
                || successor
                    .project_authority
                    .workspace_outputs()
                    .and_then(|outputs| outputs.capture_hash.as_ref())
                    != generation.output_capture_hash.as_ref()
            {
                bail!(
                    "follow successor authority contradicts the frozen source/output generation pair"
                );
            }
        }
        self.create_running_continuation_successor(
            successor,
            source_thread_id,
            chain_root_id,
            RunningContinuationKind::GraphFollowResume,
            successor_launch_metadata.resume_context.as_ref(),
            Some(successor_launch_metadata),
            result_generation,
            Vec::new(),
        )
        .map(|publication| publication.persisted)
    }

    /// Shared core for both running-source continuations (machine handoff and
    /// follow-resume). One atomic op under the write permit + lock: re-verify the
    /// source is running, enforce the single-successor invariant, require the
    /// source's captured ResumeContext, seed the successor (runtime-db writes
    /// first), then settle the source `continued`. A race or seed failure aborts
    /// with the source still running — never `continued` behind an unlaunchable
    /// successor.
    #[allow(clippy::too_many_arguments)]
    fn create_running_continuation_successor(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        kind: RunningContinuationKind<'_>,
        expected_resume_context: Option<&crate::launch_metadata::ResumeContext>,
        successor_launch_metadata: Option<&crate::launch_metadata::RuntimeLaunchMetadata>,
        source_result_generation: Option<&ryeos_state::objects::WorkspaceGenerationPair>,
        initial_events: Vec<NewEventRecord>,
    ) -> Result<CreatedThreadPublication> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        validate_facet_event_admission(&g, &successor.thread_id, &initial_events)?;
        let source_row = g
            .state_db
            .get_thread(source_thread_id)?
            .ok_or_else(|| anyhow!("source thread not found: {source_thread_id}"))?;

        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("continuation authoring is closed for daemon shutdown");
        }
        let source_runtime = g
            .runtime_db
            .get_runtime_info(source_thread_id)?
            .ok_or_else(|| anyhow!("source runtime row missing: {source_thread_id}"))?;
        if let Some(intent) = source_runtime.stop_intent.as_ref() {
            bail!(
                "cannot continue stop-requested thread {source_thread_id} ({})",
                intent.as_str()
            );
        }

        // A running-source continuation cuts a still-running source. Re-checked
        // under the lock to close the caller's check-then-commit race; a terminal
        // source is the operator follow-up path, not this one.
        if source_row.status != ThreadStatus::Running.as_str() {
            bail!(
                "running continuation requires a running source; \
                 thread {source_thread_id} is '{}'",
                source_row.status
            );
        }

        // Never braid a successor into the wrong chain.
        if chain_root_id != source_row.chain_root_id {
            bail!(
                "chain_root_id mismatch: requested {chain_root_id}, source \
                 {source_thread_id} is in chain {}",
                source_row.chain_root_id
            );
        }

        // Single-successor invariant (atomic under the held permit + lock).
        if let Some(existing) =
            queries::continuation_successor(g.state_db.projection(), source_thread_id)?
        {
            bail!("thread {source_thread_id} already continued as {existing}");
        }

        // Chain-level ceiling: bound the length of an AUTONOMOUS continuation run.
        // MACHINE handoffs only — a follow-resume edge is structural progress and
        // must be allowed even when the parent chain is already at the cap.
        if let RunningContinuationKind::Machine { .. } = &kind {
            let machine_depth = queries::consecutive_machine_continuation_depth(
                g.state_db.projection(),
                source_thread_id,
                crate::thread_lifecycle::MAX_CONTINUATION_CHAIN_DEPTH,
            )?;
            if machine_depth >= crate::thread_lifecycle::MAX_CONTINUATION_CHAIN_DEPTH {
                bail!(
                    "continuation depth limit reached ({machine_depth}/{}); the autonomous \
                     chain will not continue",
                    crate::thread_lifecycle::MAX_CONTINUATION_CHAIN_DEPTH
                );
            }
        }

        // Same-node continuations inherit operational launch metadata. A
        // remote adoption deliberately does not: its portable source
        // authority is the admitted capsule, while its successor authority is
        // the target-attested capsule and runtime seed.
        let source_launch_metadata = source_runtime.launch_metadata;
        let source_resume_context =
            if matches!(&kind, RunningContinuationKind::RemoteAdoption { .. }) {
                None
            } else {
                Some(
                    source_launch_metadata
                        .as_ref()
                        .and_then(|metadata| metadata.resume_context.as_ref())
                        .cloned()
                        .ok_or_else(|| {
                            anyhow!(
                                "source thread {source_thread_id} has no captured ResumeContext; \
                             cannot create a launchable continuation successor"
                            )
                        })?,
                )
            };
        let remote_frontier = if let RunningContinuationKind::RemoteAdoption { authority } = &kind {
            authority.placement.validate()?;
            let placement = &authority.placement;
            let source_capsule_hash = source_row
                .admitted_launch_capsule_hash
                .as_deref()
                .ok_or_else(|| anyhow!("remote adoption source has no admitted launch capsule"))?;
            let source_capsule = load_admitted_launch_capsule(
                &self.state_authority,
                &self.bundle_admission_trust,
                source_capsule_hash,
            )?;
            source_capsule.validate_durable_handoff_eligibility()?;
            let source_sealed =
                crate::thread_lifecycle::SealedRootExecutionRequest::decode_from_admitted_capsule(
                    &source_capsule,
                )?;
            match (
                source_capsule.accounting_scope.as_ref(),
                authority.source_accounting_transfer.as_ref(),
            ) {
                (None, None) if placement.accounting.source_scope.is_none() => {}
                (Some(scope), Some(transfer))
                    if scope == &transfer.source_scope
                        && placement.accounting.source_scope.as_ref() == Some(scope)
                        && placement.accounting.source_financial_high_water
                            == transfer.source_financial_high_water_before
                        && placement.accounting.source_charged_usd_nanos
                            == transfer.source_charged_usd_nanos
                        && placement.accounting.source_remaining_cap_usd_nanos
                            == transfer.source_execution_available_before_usd_nanos
                        && placement
                            .accounting
                            .source_remaining_directive_cap_usd_nanos
                            == transfer.source_directive_available_before_usd_nanos
                        && placement.accounting.target_scope.as_ref()
                            == Some(&transfer.target_scope)
                        && placement.accounting.allocation_mode.as_deref()
                            == Some(transfer.allocation_mode.as_str())
                        && placement.accounting.target_cap_usd_nanos
                            == transfer.target_cap_usd_nanos
                        && placement.accounting.target_directive_cap_usd_nanos
                            == transfer.target_directive_cap_usd_nanos
                        && transfer.operation_id == placement.operation_id
                        && transfer.source_chain_root_id == placement.chain_root_id
                        && transfer.source_placement_thread_id
                            == placement.source_placement_thread_id => {}
                _ => bail!(
                    "remote adoption accounting evidence is not the exact settled source frontier"
                ),
            }
            if placement.chain_root_id != chain_root_id
                || placement.source_placement_thread_id != source_thread_id
                || placement.successor_placement_thread_id != successor.thread_id
                || placement.owner_principal != source_sealed.handoff_principal_identifier()?
                || placement.origin_site_id != source_sealed.handoff_origin_site_id()
                || placement.source_site_id != source_sealed.handoff_current_site_id()
            {
                bail!(
                    "remote adoption placement does not name the exact source, successor, owner, and sites"
                );
            }
            if successor.current_site_id != placement.target_site_id
                || successor.origin_site_id != placement.origin_site_id
                || successor.requested_by.as_deref() != Some(placement.owner_principal.as_str())
            {
                bail!(
                    "remote adoption successor snapshot identity contradicts placement authority"
                );
            }

            let source_head = g
                .state_db
                .read_generic_head_ref("chains", chain_root_id)?
                .ok_or_else(|| anyhow!("remote adoption source chain has no signed head"))?;
            if source_head.target_hash != placement.source_chain_head_hash
                || source_head.signer != g.signer.fingerprint()
            {
                bail!("remote adoption source head is no longer the exact locally owned frontier");
            }
            let anchor = g
                .state_db
                .read_authoritative_thread_append_anchor(chain_root_id, source_thread_id)?
                .ok_or_else(|| anyhow!("remote adoption source thread has no append anchor"))?;
            if anchor.thread_last_event_hash.as_deref()
                != Some(placement.source_last_event_hash.as_str())
            {
                bail!("remote adoption source event is no longer the exact thread frontier");
            }

            let session = g
                .runtime_db
                .dedicated_session(source_thread_id)?
                .ok_or_else(|| anyhow!("remote adoption source has no dedicated worker session"))?;
            if session.chain_root_id != chain_root_id
                || session.owner_principal != placement.owner_principal
                || session.state != "frozen"
                || session.current_turn_id.is_some()
                || session.send_boundary != "settled"
                || session.candidate_snapshot_hash.as_deref()
                    != Some(
                        placement
                            .project_rebind
                            .source_candidate_snapshot_hash
                            .as_str(),
                    )
                || session.credential_profile_id != source_sealed.worker_credential_profile_id()?
                || session.remote_thread_id.as_deref()
                    != Some(
                        placement
                            .credential_reservation
                            .upstream_session_id
                            .as_str(),
                    )
            {
                bail!("remote adoption source session is not the exact frozen settled candidate");
            }
            let worker_instance_id = session.worker_instance_id.as_deref().ok_or_else(|| {
                anyhow!("remote adoption source session has no retained worker identity")
            })?;
            let worker = g
                .runtime_db
                .worker_process(worker_instance_id)?
                .ok_or_else(|| anyhow!("remote adoption source worker projection is missing"))?;
            if worker.placement_thread_id != source_thread_id
                || session.worker_boot_epoch != Some(worker.boot_epoch)
                || worker.state != runtime_db::WorkerProcessState::Dead
                || worker.cleanup_state != "reaped"
            {
                bail!("remote adoption source worker death is not proved reaped");
            }

            let checkpoint_value = self
                .state_authority
                .cas_store()?
                .get_object(&placement.checkpoint_manifest_hash)?
                .ok_or_else(|| anyhow!("remote adoption checkpoint manifest is absent"))?;
            let checkpoint = StateManifest::from_current_value(checkpoint_value)?;
            if checkpoint.publisher_chain_root_id != chain_root_id
                || checkpoint.publisher_thread_id != source_thread_id
                || checkpoint.contract != ryeos_state::objects::WORKER_SESSION_RESTORE_CONTRACT
            {
                bail!("remote adoption checkpoint was not published by the exact source placement");
            }
            let restore_bytes = self
                .state_authority
                .cas_store()?
                .get_blob(&checkpoint.restore.blob_hash)?
                .ok_or_else(|| anyhow!("remote adoption restore document is absent"))?;
            if lillux::sha256_hex(&restore_bytes) != checkpoint.restore.blob_hash {
                bail!("remote adoption restore document digest changed");
            }
            let restore_value: Value = serde_json::from_slice(&restore_bytes)
                .context("decode remote adoption restore document")?;
            if lillux::canonical_json(&restore_value)?.as_bytes() != restore_bytes {
                bail!("remote adoption restore document is not canonical JSON");
            }
            let restore =
                ryeos_state::objects::WorkerSessionRestore::from_current_value(restore_value)?;
            let source_capsule_hash = source_row
                .admitted_launch_capsule_hash
                .as_deref()
                .ok_or_else(|| anyhow!("remote adoption source has no launch capsule"))?;
            let restored_dependencies = restore
                .persistent_dependencies
                .iter()
                .map(|(name, dependency)| (name.clone(), dependency.exact_program_hash.clone()))
                .collect::<BTreeMap<_, _>>();
            if restore.source_position.chain_root_id != chain_root_id
                || restore.source_position.placement_thread_id != source_thread_id
                || restore.project_candidate_snapshot_hash.as_deref()
                    != Some(
                        placement
                            .project_rebind
                            .source_candidate_snapshot_hash
                            .as_str(),
                    )
                || restore.outer_exact_program_hash != placement.outer_exact_program_hash
                || restored_dependencies != placement.persistent_dependency_programs
                || restore.upstream_session_id
                    != placement.credential_reservation.upstream_session_id
                || restore.credential_subject_contract_digest
                    != placement.credential_reservation.subject_contract_digest
                || restore.credential_subject_digest
                    != placement.credential_reservation.subject_digest
                || restore.source_site_id != placement.source_site_id
                || restore.source_launch_capsule_hash != source_capsule_hash
            {
                bail!("remote adoption placement contradicts its authoritative checkpoint restore");
            }
            let latest_anchor =
                queries::latest_state_anchor_event(g.state_db.projection(), source_thread_id)?
                    .ok_or_else(|| {
                        anyhow!("remote adoption source has no authoritative state anchor")
                    })?;
            let anchor = ryeos_state::objects::StateAnchorMilestone::from_value(
                serde_json::from_slice(&latest_anchor.payload)
                    .context("decode latest source state-anchor payload")?,
            )?;
            if anchor.payload.manifest_ref != format!("cas:{}", placement.checkpoint_manifest_hash)
            {
                bail!("remote adoption checkpoint is not the source's latest state anchor");
            }
            match &anchor.subject {
                ryeos_state::objects::StateAnchorSubject::Execution {
                    chain_root_id: anchor_chain,
                    placement_thread_id,
                    launch_capsule_hash,
                    source_chain_seq,
                    source_event_hash,
                    ..
                } if anchor_chain == chain_root_id
                    && placement_thread_id == source_thread_id
                    && source_row.admitted_launch_capsule_hash.as_deref()
                        == Some(launch_capsule_hash.as_str())
                    && restore.source_position.chain_seq == *source_chain_seq
                    && restore.source_position.event_hash == *source_event_hash => {}
                _ => bail!("remote adoption checkpoint anchor names another execution authority"),
            }

            let placement_value = self
                .state_authority
                .cas_store()?
                .get_object(&authority.placement_attestation_hash)?
                .ok_or_else(|| anyhow!("remote adoption placement attestation is absent"))?;
            let placement_attestation =
                ryeos_state::objects::Attestation::from_value(&placement_value)?;
            placement_attestation.verify_with_key(&authority.target_node_verifying_key)?;
            if placement_attestation.is_expired_at(&lillux::time::iso8601_now())? {
                bail!("remote adoption placement attestation is expired");
            }
            let observed =
                crate::worker_handoff::WorkerPlacementAdmissionEvidence::from_attestation(
                    &placement_attestation,
                )?;
            if observed != *placement {
                bail!("remote adoption placement attestation differs from its supplied evidence");
            }
            let target_signer_fingerprint = placement_attestation.issuer_fingerprint()?.to_string();
            Some((
                source_head.target_hash,
                placement.source_last_event_hash.clone(),
                target_signer_fingerprint,
            ))
        } else {
            None
        };
        if matches!(&kind, RunningContinuationKind::GraphFollowResume)
            && source_launch_metadata
                .as_ref()
                .expect("non-remote continuation source metadata was required above")
                .native_resume
                .is_none()
        {
            bail!("follow-resume source thread {source_thread_id} does not declare native_resume");
        }
        // Successor preconditions BEFORE any write: it must belong to the source's
        // chain and, if it names an upstream, name THIS source — never braid a
        // successor into the wrong chain or contradict the edge being created (a
        // later StateDb reject would leave an orphan runtime row behind).
        if successor.chain_root_id != source_row.chain_root_id {
            bail!(
                "successor {} chain_root_id {} does not match source chain {}",
                successor.thread_id,
                successor.chain_root_id,
                source_row.chain_root_id
            );
        }
        match successor.upstream_thread_id.as_deref() {
            None => {}
            Some(id) if id == source_thread_id => {}
            Some(other) => bail!(
                "successor {} declares upstream {other}, not the continuation source {source_thread_id}",
                successor.thread_id
            ),
        }
        let mut successor_with_upstream = successor.clone();
        successor_with_upstream.upstream_thread_id = Some(source_thread_id.to_string());

        if successor_launch_metadata.is_some()
            && matches!(&kind, RunningContinuationKind::RemoteAdoption { .. })
        {
            bail!("remote adoption derives launch metadata only from its attested target capsule");
        }
        let mut successor_meta = match &kind {
            RunningContinuationKind::RemoteAdoption { authority } => {
                let cas = self.state_authority.cas_store()?;
                let target_capsule_hash = &authority.placement.target_launch_capsule_hash;
                let target_capsule_value = cas
                    .get_object_bounded(
                        target_capsule_hash,
                        ryeos_state::objects::MAX_ADMITTED_LAUNCH_CAPSULE_BYTES as u64,
                    )?
                    .ok_or_else(|| anyhow!("remote adoption target launch capsule is absent"))?;
                let target_capsule =
                    ryeos_state::objects::AdmittedLaunchCapsule::from_current_value(
                        target_capsule_value,
                    )?;
                if target_capsule.content_hash()? != *target_capsule_hash {
                    bail!("remote adoption target launch capsule changed content hash");
                }
                verify_rooted_bundle_member_source_proof(
                    &target_capsule,
                    &self.bundle_admission_trust,
                )
                .context("revalidate transferred rooted Bundle member-source signatures")?;
                target_capsule
                    .verify_retained_execution_realization_with_key(
                        &cas,
                        &self.state_authority.large_object_store()?,
                        &authority.target_node_verifying_key,
                    )
                    .context("verify remote target execution realization")?;
                let source_capsule_hash = source_row
                    .admitted_launch_capsule_hash
                    .as_deref()
                    .ok_or_else(|| {
                        anyhow!("remote adoption source has no admitted launch capsule")
                    })?;
                let source_capsule = load_admitted_launch_capsule(
                    &self.state_authority,
                    &self.bundle_admission_trust,
                    source_capsule_hash,
                )?;
                let target_sealed =
                    crate::thread_lifecycle::SealedRootExecutionRequest::decode_from_admitted_capsule(
                        &target_capsule,
                    )?;
                let cas = self.state_authority.cas_store()?;
                let seed_value = cas
                    .get_object(&authority.placement.target_runtime_seed_hash)?
                    .ok_or_else(|| anyhow!("remote adoption target runtime seed is absent"))?;
                let seed =
                    ryeos_state::objects::PlacementRuntimeSeed::from_current_value(seed_value)?;
                if seed.content_hash()? != authority.placement.target_runtime_seed_hash
                    || seed.operation_id != authority.placement.operation_id
                    || seed.chain_root_id != chain_root_id
                    || seed.source_placement_thread_id != source_thread_id
                    || seed.successor_placement_thread_id != successor.thread_id
                    || seed.target_site_id != authority.placement.target_site_id
                    || seed.owner_principal != authority.placement.owner_principal
                    || seed.target_launch_capsule_hash
                        != authority.placement.target_launch_capsule_hash
                {
                    bail!("remote adoption runtime seed contradicts placement authority");
                }
                let metadata_bytes = cas
                    .get_blob(&seed.launch_metadata_blob_hash)?
                    .ok_or_else(|| anyhow!("remote adoption runtime metadata is absent"))?;
                if u64::try_from(metadata_bytes.len())? != seed.launch_metadata_size_bytes
                    || lillux::sha256_hex(&metadata_bytes) != seed.launch_metadata_blob_hash
                {
                    bail!("remote adoption runtime metadata size or digest changed");
                }
                let metadata_value: Value = serde_json::from_slice(&metadata_bytes)
                    .context("decode target-authored runtime seed")?;
                if lillux::canonical_json(&metadata_value)?.as_bytes() != metadata_bytes {
                    bail!("remote adoption runtime metadata is not canonical JSON");
                }
                let metadata: crate::launch_metadata::RuntimeLaunchMetadata =
                    serde_json::from_value(metadata_value)
                        .context("decode target-authored launch metadata")?;
                metadata
                    .validate()
                    .context("validate remote adoption target launch metadata")?;
                let seed_sealed_matches = metadata
                    .sealed_root_request
                    .as_ref()
                    .map(serde_json::to_value)
                    .transpose()?
                    == Some(serde_json::to_value(&target_sealed)?);
                let target_resume = metadata.resume_context.as_ref().ok_or_else(|| {
                    anyhow!("target-authored runtime seed has no resume authority")
                })?;
                if metadata.continuation_source_thread_id.as_deref() != Some(source_thread_id)
                    || !seed_sealed_matches
                {
                    bail!("target-authored runtime seed changed its resume or source authority");
                }
                crate::worker_handoff::validate_cross_site_capsule_transition(
                    &source_capsule,
                    &target_capsule,
                    target_resume,
                    &authority.placement,
                    &cas,
                )?;
                if metadata.admitted_launch_capsule()?.as_ref() != Some(&target_capsule) {
                    bail!(
                        "remote adoption target metadata does not reproduce its admitted capsule"
                    );
                }
                metadata
            }
            _ => {
                let source_launch_metadata = source_launch_metadata
                    .as_ref()
                    .expect("non-remote continuation source metadata was required above");
                let source_resume_context = source_resume_context
                    .as_ref()
                    .expect("non-remote continuation source resume was required above");
                let prepared = successor_launch_metadata.cloned();
                let mut metadata = prepared.clone().unwrap_or_else(|| {
                    source_launch_metadata
                        .continuation_successor_seed(source_resume_context.clone())
                });
                if prepared.is_none() && matches!(&kind, RunningContinuationKind::Machine { .. }) {
                    metadata.continuation_runtime_bootstrap = Some(
                        crate::launch_metadata::ContinuationRuntimeBootstrap::PredecessorNativeCheckpoint,
                    );
                }
                metadata
            }
        };
        let successor_resume_context =
            successor_meta
                .resume_context
                .as_ref()
                .cloned()
                .ok_or_else(|| {
                    anyhow!(
                        "successor {} has no captured ResumeContext",
                        successor.thread_id
                    )
                })?;
        if expected_resume_context.is_some_and(|expected| expected != &successor_resume_context) {
            bail!(
                "successor {} ResumeContext changed during authoritative preparation",
                successor.thread_id
            );
        }
        match &kind {
            RunningContinuationKind::RemoteAdoption { .. } => {}
            _ => successor_resume_context.validate_continuation_transition_from(
                source_resume_context
                    .as_ref()
                    .expect("non-remote continuation source resume was required above"),
                source_result_generation,
                crate::launch_metadata::ContinuationAuthorityTransitionKind::Inherit,
            )?,
        }
        if successor_meta
            .continuation_source_thread_id
            .as_deref()
            .is_some_and(|source| source != source_thread_id)
        {
            bail!("prepared successor names a different continuation source");
        }
        successor_meta.continuation_source_thread_id = Some(source_thread_id.to_string());
        match &kind {
            RunningContinuationKind::Machine { .. } => {
                if successor_meta.continuation_runtime_bootstrap.is_none() {
                    bail!("machine successor has no durable runtime-state bootstrap");
                }
            }
            RunningContinuationKind::RemoteAdoption { .. } => {
                if successor_meta.continuation_runtime_bootstrap
                    != Some(
                        crate::launch_metadata::ContinuationRuntimeBootstrap::ExternallyRestoredState,
                    )
                {
                    bail!("remote adoption must cold-start from externally restored state");
                }
            }
            RunningContinuationKind::GraphFollowResume => {
                if successor_meta.continuation_runtime_bootstrap.is_some() {
                    bail!("follow-resume successor carries machine runtime-state bootstrap");
                }
            }
        }
        let successor_runtime = RuntimeInfo {
            launch_metadata: Some(successor_meta.clone()),
            ..RuntimeInfo::default()
        };
        let (successor_snapshot, source_snapshot_before) =
            if let RunningContinuationKind::RemoteAdoption { authority } = &kind {
                let mut snapshot = build_continuation_snapshot(
                    &successor_with_upstream,
                    &successor_resume_context,
                )?;
                snapshot.admitted_launch_capsule_hash =
                    Some(authority.placement.target_launch_capsule_hash.clone());
                (
                    snapshot,
                    authoritative_snapshot_for_transition(&g, chain_root_id, source_thread_id)?,
                )
            } else {
                attach_continuation_launch_capsule(
                    &self.state_authority,
                    &self.bundle_admission_trust,
                    permit.cas_guard(),
                    &g,
                    build_continuation_snapshot(
                        &successor_with_upstream,
                        &successor_resume_context,
                    )?,
                    ContinuationCapsuleTransition {
                        chain_root_id,
                        source_thread_id,
                        launch_metadata: Some(&successor_meta),
                        expected_result_generation: source_result_generation,
                        kind: crate::launch_metadata::ContinuationAuthorityTransitionKind::Inherit,
                    },
                )?
            };

        // Same-node successors become locally runnable, so their runtime seed
        // is written before the authoritative edge. A remote successor is
        // deliberately absent from this node's runtime database; the target
        // may create its operational row only after it adopts the transferred
        // signed head.
        let local_runtime_seeded = !matches!(&kind, RunningContinuationKind::RemoteAdoption { .. });
        if local_runtime_seeded {
            if let Some(prepared) = successor_launch_metadata
                && (prepared.native_resume
                    != source_launch_metadata
                        .as_ref()
                        .expect("local continuation source metadata was required above")
                        .native_resume
                    || prepared.cancellation_mode
                        != source_launch_metadata
                            .as_ref()
                            .expect("local continuation source metadata was required above")
                            .cancellation_mode
                    || prepared.launch_driver
                        != source_launch_metadata
                            .as_ref()
                            .expect("local continuation source metadata was required above")
                            .launch_driver)
            {
                bail!(
                    "prepared successor execution policy differs from its source launch metadata"
                );
            }
            let _admission = g.state_db.authorize_runtime_pin(chain_root_id)?;
            g.runtime_db
                .insert_thread_runtime(&successor.thread_id, chain_root_id)?;
            let metadata_result = g
                .runtime_db
                .set_launch_metadata(&successor.thread_id, &successor_meta);
            if let Err(error) = metadata_result {
                let _ = self.delete_thread_runtime_locked(&g, &successor.thread_id);
                return Err(error);
            }
        }

        let remote_authority = match (&kind, remote_frontier.as_ref()) {
            (
                RunningContinuationKind::RemoteAdoption { authority },
                Some((source_chain_head_hash, source_last_event_hash, target_signer_fingerprint)),
            ) => {
                let placement = &authority.placement;
                if source_snapshot_before.current_site_id != placement.source_site_id
                    || source_snapshot_before.origin_site_id != placement.origin_site_id
                    || source_snapshot_before.requested_by.as_deref()
                        != Some(placement.owner_principal.as_str())
                    || source_snapshot_before
                        .admitted_launch_capsule_hash
                        .is_none()
                {
                    bail!("remote adoption source snapshot contradicts placement authority");
                }
                let accounting_transfer_hash = authority
                    .source_accounting_transfer
                    .as_ref()
                    .map(|transfer| -> Result<String> {
                        transfer.validate()?;
                        if transfer.operation_id != placement.operation_id {
                            bail!("accounting export belongs to another handoff operation");
                        }
                        self.state_authority.ensure_guard(permit.cas_guard())?;
                        self.state_authority
                            .cas_store()?
                            .store_object(&serde_json::to_value(transfer)?)
                    })
                    .transpose()?;
                let grant_evidence = crate::worker_handoff::chain_writer_transition_from_placement(
                    placement,
                    authority.placement_attestation_hash.clone(),
                    accounting_transfer_hash.clone(),
                    g.signer.fingerprint().to_string(),
                    target_signer_fingerprint.clone(),
                );
                let grant = grant_evidence.sign_attestation(g.signer.as_ref())?;
                self.state_authority.ensure_guard(permit.cas_guard())?;
                let cas = self.state_authority.cas_store()?;
                let seed_value = cas
                    .get_object(&placement.target_runtime_seed_hash)?
                    .ok_or_else(|| anyhow!("target placement runtime seed is absent at cut"))?;
                let seed =
                    ryeos_state::objects::PlacementRuntimeSeed::from_current_value(seed_value)?;
                if seed.content_hash()? != placement.target_runtime_seed_hash
                    || seed.target_launch_capsule_hash != placement.target_launch_capsule_hash
                {
                    bail!("target placement runtime seed changed before source cut");
                }
                let writer_grant_hash = cas
                    .store_object(&grant.to_value())
                    .context("store one-successor remote chain-writer grant")?;
                Some(ryeos_state::objects::RemoteContinuationAuthority {
                    schema: ryeos_state::objects::REMOTE_CONTINUATION_AUTHORITY_SCHEMA,
                    operation_id: placement.operation_id.clone(),
                    preflight_id: placement.preflight_id.clone(),
                    preflight_attestation_hash: placement.preflight_attestation_hash.clone(),
                    follow_delivery_reservation_attestation_hash: placement
                        .follow_delivery_reservation_attestation_hash
                        .clone(),
                    source_chain_head_hash: source_chain_head_hash.clone(),
                    source_last_event_hash: source_last_event_hash.clone(),
                    checkpoint_manifest_hash: placement.checkpoint_manifest_hash.clone(),
                    target_placement_attestation_hash: authority.placement_attestation_hash.clone(),
                    chain_writer_grant_hash: writer_grant_hash,
                    target_launch_capsule_hash: placement.target_launch_capsule_hash.clone(),
                    target_runtime_seed_hash: placement.target_runtime_seed_hash.clone(),
                    source_accounting_transfer_hash: accounting_transfer_hash,
                    source_site_id: placement.source_site_id.clone(),
                    target_site_id: placement.target_site_id.clone(),
                    target_node_signer_fingerprint: target_signer_fingerprint.clone(),
                    successor_thread_id: successor.thread_id.clone(),
                })
            }
            (RunningContinuationKind::RemoteAdoption { .. }, None) => {
                bail!("remote adoption lost its verified source frontier")
            }
            (_, Some(_)) => bail!("local continuation unexpectedly carries a remote frontier"),
            (_, None) => None,
        };

        // The successor becomes observable with its creation record and complete
        // authoritative launch audit in the same signed chain head. ResumeContext
        // was seeded above, so every visible successor is immediately relaunchable.
        let successor_event = NewEventRecord {
            event_type: "thread_created".to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "kind": &successor.kind,
                "item_ref": &successor.item_ref,
                "continuation_from": source_thread_id,
            }),
        };
        let mut successor_events = Vec::with_capacity(initial_events.len() + 1);
        successor_events.push(successor_event);
        successor_events.extend(initial_events);
        let successor_thread_events =
            convert_events(&successor_events, chain_root_id, &successor.thread_id);
        let expected_successor_events = successor_thread_events.clone();
        // Settle the source to `continued` in the same signed head that creates
        // the successor and records its authoritative birth events.
        let now = lillux::time::iso8601_now();
        let mut source_snapshot_after =
            continued_snapshot_from_authoritative(source_snapshot_before.clone(), &now);
        source_snapshot_after.result_project_snapshot_hash =
            source_result_generation.map(|generation| generation.snapshot_hash.clone());
        if let Some(result_hash) =
            source_result_generation.map(|generation| generation.snapshot_hash.as_str())
            && successor_with_upstream
                .base_project_snapshot_hash
                .as_deref()
                != Some(result_hash)
        {
            bail!(
                "continuation successor {} base snapshot does not match frozen source result {}",
                successor.thread_id,
                result_hash
            );
        }
        source_snapshot_after.result_workspace_output_capture_hash =
            source_result_generation.and_then(|generation| generation.output_capture_hash.clone());
        source_snapshot_after
            .verify_result_workspace_output_capture(&self.state_authority.cas_store()?)?;
        let edge_reason: Option<&str> = match &kind {
            RunningContinuationKind::Machine { sanitized_reason } => *sanitized_reason,
            RunningContinuationKind::GraphFollowResume => {
                Some(queries::ContinuationReasonMarker::GraphFollowResume.as_str())
            }
            RunningContinuationKind::RemoteAdoption { .. } => Some("remote_adoption"),
        };
        let mut source_payload = json!({
            "successor_thread_id": &successor.thread_id,
            "reason": edge_reason,
            "result_project_snapshot_hash": source_snapshot_after.result_project_snapshot_hash,
            "result_workspace_output_capture_hash": source_snapshot_after.result_workspace_output_capture_hash,
        });
        if let Some(remote) = &remote_authority {
            source_payload
                .as_object_mut()
                .expect("continuation payload is an object")
                .insert(
                    "remote_adoption".to_string(),
                    serde_json::to_value(remote).context("encode remote continuation authority")?,
                );
        }
        let source_event = NewEventRecord {
            event_type: "thread_continued".to_string(),
            storage_class: "indexed".to_string(),
            payload: source_payload,
        };
        let mut ste = convert_events(
            std::slice::from_ref(&source_event),
            chain_root_id,
            source_thread_id,
        );
        if let Some(remote) = &remote_authority {
            ste.first_mut()
                .expect("running continuation source event batch is non-empty")
                .prev_thread_event_hash = Some(remote.source_last_event_hash.clone());
        }
        let expected_source_event = ste
            .first()
            .cloned()
            .expect("running continuation source event batch is non-empty");
        let expected_successor_snapshot = successor_snapshot.clone();
        let successor_commit = g.state_db.add_thread_with_events_and_append_admitted(
            chain_root_id,
            successor_snapshot,
            successor_thread_events,
            source_thread_id,
            ste,
            vec![SnapshotUpdate {
                thread_id: source_thread_id.to_string(),
                new_snapshot: source_snapshot_after.clone(),
            }],
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        );
        let successor_result = match successor_commit {
            Ok(committed) => committed_value(committed),
            Err(error) => {
                match read_exact_committed_continuation(
                    &g,
                    chain_root_id,
                    ExpectedContinuationCommit {
                        source_thread_id,
                        source_before: &source_snapshot_before,
                        source_after: &source_snapshot_after,
                        source_snapshot_updated: true,
                        source_event: &expected_source_event,
                        successor_snapshot: &expected_successor_snapshot,
                        successor_events: &expected_successor_events,
                    },
                ) {
                    Ok(ContinuationCommitReadback::Exact(snapshot)) => {
                        tracing::error!(
                            thread_id = %successor.thread_id,
                            source_thread_id,
                            error = %error,
                            "running continuation returned an error after publishing authoritative state; continuing from exact committed pair"
                        );
                        return Ok(CreatedThreadPublication {
                            persisted: Vec::new(),
                            successor: thread_detail_from_committed_snapshot(
                                *snapshot,
                                successor_runtime,
                            ),
                            remote_writer_grant_hash: remote_authority
                                .as_ref()
                                .map(|remote| remote.chain_writer_grant_hash.clone()),
                        });
                    }
                    Err(authority_error) => {
                        return Err(anyhow!(
                            "running continuation failed and authoritative pair readback was unavailable; preserving runtime ownership for reconciliation: write error: {error:#}; readback error: {authority_error:#}"
                        ));
                    }
                    Ok(ContinuationCommitReadback::Ambiguous(reason)) => {
                        return Err(anyhow!(
                            "running continuation failed with ambiguous authoritative readback; preserving runtime ownership for reconciliation: {reason}; write error: {error:#}"
                        ));
                    }
                    Ok(ContinuationCommitReadback::ProvenAbsent) => {}
                }
                if local_runtime_seeded
                    && let Err(cleanup_error) =
                        self.delete_thread_runtime_locked(&g, &successor.thread_id)
                {
                    tracing::error!(
                        thread_id = %successor.thread_id,
                        error = %cleanup_error,
                        "failed to remove runtime row after atomic running-continuation birth failed"
                    );
                }
                return Err(error);
            }
        };
        let mut all_input_events = successor_events;
        all_input_events.push(source_event);
        let persisted = match persisted_from_add_thread_with_events(
            &successor_result,
            &all_input_events,
        ) {
            Ok(persisted) => persisted,
            Err(error) => {
                tracing::error!(
                    thread_id = %successor.thread_id,
                    source_thread_id,
                    chain_root_id,
                    error = %error,
                    "authoritative running continuation committed but live event reconstruction failed"
                );
                Vec::new()
            }
        };
        Ok(CreatedThreadPublication {
            persisted,
            successor: thread_detail_from_committed_snapshot(
                successor_result.snapshot,
                successor_runtime,
            ),
            remote_writer_grant_hash: remote_authority.map(|remote| remote.chain_writer_grant_hash),
        })
    }

    /// Operator follow-up continuation, made idempotent by a request fingerprint.
    ///
    /// Unlike [`Self::create_continuation`] (whose single-successor guard FAILS on
    /// a second follow-up), this dedups: under the write permit + lock, if the
    /// source already has a successor it compares the recorded
    /// `successor_request_fingerprint` to this request's — a match returns the
    /// existing successor (`Existing`, a double-submit), a mismatch is a
    /// `Conflict`. Otherwise it creates the successor and persists the fingerprint
    /// on the `thread_continued` edge in the SAME critical section, so dedup works
    /// even if the daemon crashes before the runtime emits anything. A terminal
    /// (completed/failed) source keeps its status; a running source is settled
    /// `continued` (same as `create_continuation`).
    // Idempotency identity, source lineage, launch metadata, and initial events
    // remain explicit at this atomic admission boundary.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn create_or_get_continuation_admitted(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
        request_fingerprint: &str,
        launch_metadata: Option<&crate::launch_metadata::RuntimeLaunchMetadata>,
        initial_events: Vec<NewEventRecord>,
    ) -> Result<ContinuationOutcome> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        validate_facet_event_admission(&g, &successor.thread_id, &initial_events)?;
        if !self
            .process_attachment_admission_open
            .load(Ordering::Acquire)
        {
            bail!("continuation creation is closed for daemon shutdown");
        }
        let source_row = g
            .state_db
            .get_thread(source_thread_id)?
            .ok_or_else(|| anyhow!("source thread not found: {source_thread_id}"))?;

        // The caller-supplied chain root must match the source's — a continuation
        // stays in the predecessor's chain. Fail loud on a mismatch rather than
        // braiding a successor into the wrong chain.
        if chain_root_id != source_row.chain_root_id {
            bail!(
                "chain_root_id mismatch: caller passed '{chain_root_id}' but source \
                 '{source_thread_id}' belongs to chain '{}'",
                source_row.chain_root_id
            );
        }

        if is_terminal_status(&source_row.status)
            && source_row.status != ThreadStatus::Failed.as_str()
            && source_row.status != ThreadStatus::Completed.as_str()
        {
            bail!(
                "cannot continue thread in terminal status '{}'",
                source_row.status
            );
        }

        // Idempotent get-or-conflict: a source already continued is deduped by
        // fingerprint instead of failing the single-successor guard.
        if let Some(existing) =
            queries::continuation_successor(g.state_db.projection(), source_thread_id)?
        {
            let existing_fp =
                queries::continuation_fingerprint(g.state_db.projection(), source_thread_id)?;
            return Ok(if existing_fp.as_deref() == Some(request_fingerprint) {
                ContinuationOutcome::Existing {
                    successor_thread_id: existing,
                }
            } else {
                ContinuationOutcome::Conflict {
                    successor_thread_id: existing,
                }
            });
        }

        let mut successor_with_upstream = successor.clone();
        if successor_with_upstream.upstream_thread_id.is_none() {
            successor_with_upstream.upstream_thread_id = Some(source_thread_id.to_string());
        }
        let effective_launch_metadata = launch_metadata
            .map(|metadata| {
                let mut metadata = metadata.clone();
                if metadata
                    .continuation_source_thread_id
                    .as_deref()
                    .is_some_and(|source| source != source_thread_id)
                {
                    bail!("prepared successor names a different continuation source");
                }
                metadata.continuation_source_thread_id = Some(source_thread_id.to_string());
                Ok(metadata)
            })
            .transpose()?;
        let base_successor_snapshot = match effective_launch_metadata
            .as_ref()
            .and_then(|metadata| metadata.resume_context.as_ref())
        {
            Some(resume) => build_continuation_snapshot(&successor_with_upstream, resume)?,
            None => build_snapshot(&successor_with_upstream),
        };
        let (successor_snapshot, source_snapshot_before) = attach_continuation_launch_capsule(
            &self.state_authority,
            &self.bundle_admission_trust,
            permit.cas_guard(),
            &g,
            base_successor_snapshot,
            ContinuationCapsuleTransition {
                chain_root_id,
                source_thread_id,
                launch_metadata: effective_launch_metadata.as_ref(),
                expected_result_generation: None,
                kind: crate::launch_metadata::ContinuationAuthorityTransitionKind::OperatorFollowUp,
            },
        )?;
        let source_snapshot_updated = !is_terminal_status(&source_row.status);
        let source_snapshot_after = if source_snapshot_updated {
            continued_snapshot_from_authoritative(
                source_snapshot_before.clone(),
                &lillux::time::iso8601_now(),
            )
        } else {
            source_snapshot_before.clone()
        };
        let source_snapshot_updates = source_snapshot_updated
            .then(|| SnapshotUpdate {
                thread_id: source_thread_id.to_string(),
                new_snapshot: source_snapshot_after.clone(),
            })
            .into_iter()
            .collect();
        let successor_runtime = RuntimeInfo {
            launch_metadata: effective_launch_metadata.clone(),
            ..RuntimeInfo::default()
        };
        // Seed runtime state before the atomic signed-head transition. Failure
        // leaves at most an auxiliary runtime row, which is removed below; the
        // successor snapshot and source edge are indivisible.
        {
            let _admission = g.state_db.authorize_runtime_pin(chain_root_id)?;
            g.runtime_db
                .insert_thread_runtime(&successor.thread_id, chain_root_id)?;

            // Seed the operator launch context before the successor is visible.
            if let Some(meta) = effective_launch_metadata.as_ref()
                && let Err(error) = g.runtime_db.set_launch_metadata(&successor.thread_id, meta)
            {
                let _ = self.delete_thread_runtime_locked(&g, &successor.thread_id);
                return Err(error);
            }
        }

        let successor_event = NewEventRecord {
            event_type: "thread_created".to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "kind": &successor.kind,
                "item_ref": &successor.item_ref,
                "continuation_from": source_thread_id,
            }),
        };
        let mut successor_events = Vec::with_capacity(initial_events.len() + 1);
        successor_events.push(successor_event);
        successor_events.extend(initial_events);
        let successor_thread_events =
            convert_events(&successor_events, chain_root_id, &successor.thread_id);
        let expected_successor_events = successor_thread_events.clone();
        let source_event = NewEventRecord {
            event_type: "thread_continued".to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "successor_thread_id": &successor.thread_id,
                "reason": reason,
                "successor_request_fingerprint": request_fingerprint,
            }),
        };
        let ste = convert_events(
            std::slice::from_ref(&source_event),
            chain_root_id,
            source_thread_id,
        );
        let expected_source_event = ste
            .first()
            .cloned()
            .expect("operator continuation source event batch is non-empty");
        let expected_successor_snapshot = successor_snapshot.clone();
        let successor_commit = g.state_db.add_thread_with_events_and_append_admitted(
            chain_root_id,
            successor_snapshot,
            successor_thread_events,
            source_thread_id,
            ste,
            source_snapshot_updates,
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        );
        let successor_result = match successor_commit {
            Ok(committed) => committed_value(committed),
            Err(error) => {
                match read_exact_committed_continuation(
                    &g,
                    chain_root_id,
                    ExpectedContinuationCommit {
                        source_thread_id,
                        source_before: &source_snapshot_before,
                        source_after: &source_snapshot_after,
                        source_snapshot_updated,
                        source_event: &expected_source_event,
                        successor_snapshot: &expected_successor_snapshot,
                        successor_events: &expected_successor_events,
                    },
                ) {
                    Ok(ContinuationCommitReadback::Exact(snapshot)) => {
                        tracing::error!(
                            thread_id = %successor.thread_id,
                            source_thread_id,
                            error = %error,
                            "operator continuation returned an error after publishing authoritative state; continuing from exact committed pair"
                        );
                        return Ok(ContinuationOutcome::Created {
                            persisted: Vec::new(),
                            successor: Box::new(thread_detail_from_committed_snapshot(
                                *snapshot,
                                successor_runtime,
                            )),
                        });
                    }
                    Err(authority_error) => {
                        return Err(anyhow!(
                            "operator continuation failed and authoritative pair readback was unavailable; preserving runtime ownership for reconciliation: write error: {error:#}; readback error: {authority_error:#}"
                        ));
                    }
                    Ok(ContinuationCommitReadback::Ambiguous(reason)) => {
                        return Err(anyhow!(
                            "operator continuation failed with ambiguous authoritative readback; preserving runtime ownership for reconciliation: {reason}; write error: {error:#}"
                        ));
                    }
                    Ok(ContinuationCommitReadback::ProvenAbsent) => {}
                }
                if let Err(cleanup_error) =
                    self.delete_thread_runtime_locked(&g, &successor.thread_id)
                {
                    tracing::error!(
                        thread_id = %successor.thread_id,
                        error = %cleanup_error,
                        "failed to remove runtime row after atomic operator continuation birth failed"
                    );
                }
                return Err(error);
            }
        };
        let mut all_input_events = successor_events;
        all_input_events.push(source_event);
        let persisted = match persisted_from_add_thread_with_events(
            &successor_result,
            &all_input_events,
        ) {
            Ok(persisted) => persisted,
            Err(error) => {
                tracing::error!(
                    thread_id = %successor.thread_id,
                    source_thread_id,
                    chain_root_id,
                    error = %error,
                    "authoritative operator continuation committed but live event reconstruction failed"
                );
                Vec::new()
            }
        };
        Ok(ContinuationOutcome::Created {
            persisted,
            successor: Box::new(thread_detail_from_committed_snapshot(
                successor_result.snapshot,
                successor_runtime,
            )),
        })
    }

    /// Raw idempotent continuation fixture for state-layer tests. Absent in
    /// production.
    #[cfg(any(test, feature = "test-support"))]
    pub fn create_or_get_continuation_for_test(
        &self,
        successor: &NewThreadRecord,
        source_thread_id: &str,
        chain_root_id: &str,
        reason: Option<&str>,
        request_fingerprint: &str,
        resume_context: Option<&crate::launch_metadata::ResumeContext>,
    ) -> Result<ContinuationOutcome> {
        let launch_metadata = resume_context.cloned().map(|resume_context| {
            crate::launch_metadata::RuntimeLaunchMetadata::default()
                .with_launch_driver(ryeos_state::objects::ExecutionLaunchDriver::ManagedRuntime)
                .with_resume_context(resume_context)
        });
        self.create_or_get_continuation_admitted(
            successor,
            source_thread_id,
            chain_root_id,
            reason,
            request_fingerprint,
            launch_metadata.as_ref(),
            Vec::new(),
        )
    }

    /// The `successor_request_fingerprint` recorded on a source's
    /// `thread_continued` edge, if any — used to dedup operator double-submits.
    pub fn get_continuation_fingerprint(&self, thread_id: &str) -> Result<Option<String>> {
        let g = self.lock()?;
        queries::continuation_fingerprint(g.state_db.projection(), thread_id)
    }

    /// Whether `source_thread_id`'s continuation edge is a follow-resume edge
    /// pointing at `successor_thread_id`. Such a successor has the same shape as a
    /// stranded machine continuation but must NOT be auto-launched — it waits for
    /// the followed child's result. Target-aware: another created row that merely
    /// names the same upstream is NOT matched.
    pub fn is_follow_resume_successor(
        &self,
        source_thread_id: &str,
        successor_thread_id: &str,
    ) -> Result<bool> {
        let g = self.lock()?;
        Ok(matches!(
            queries::continuation_edge(g.state_db.projection(), source_thread_id)?,
            Some((succ, Some(reason), _))
                if succ == successor_thread_id
                    && reason == queries::ContinuationReasonMarker::GraphFollowResume.as_str()
        ))
    }

    /// Reserve a durable, owner-bound planning handle before any launch task is
    /// spawned. The reserved thread id remains internal until authoritative
    /// thread publication binds it.
    pub fn reserve_launch_planning(
        &self,
        reserved_thread_id: &str,
        requested_by: &str,
    ) -> std::result::Result<String, LaunchPlanningReservationError> {
        let launch_id = format!("L-{}", uuid::Uuid::new_v4().simple());
        self.reserve_launch_planning_with_id(&launch_id, reserved_thread_id, requested_by)?;
        Ok(launch_id)
    }

    /// Reserve a caller-retained opaque launch coordinate before background
    /// execution starts. The coordinate is not authority by itself: every
    /// later read/cancel also proves the authenticated owner.
    pub fn reserve_launch_planning_with_id(
        &self,
        launch_id: &str,
        reserved_thread_id: &str,
        requested_by: &str,
    ) -> std::result::Result<(), LaunchPlanningReservationError> {
        if !is_canonical_launch_id(launch_id) {
            return Err(LaunchPlanningReservationError::Internal(anyhow!(
                "launch id must be L- followed by exactly 32 hexadecimal characters"
            )));
        }
        let _permit = self
            .acquire_write_permit()
            .map_err(LaunchPlanningReservationError::Internal)?;
        let g = self
            .lock()
            .map_err(LaunchPlanningReservationError::Internal)?;
        g.runtime_db
            .reserve_launch_planning(launch_id, reserved_thread_id, requested_by)
            .map_err(map_launch_planning_reservation_error)?;
        Ok(())
    }

    pub fn launch_planning_status(
        &self,
        launch_id: &str,
        requested_by: &str,
    ) -> Result<Option<LaunchPlanningStatus>> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let Some(mut record) = g.runtime_db.launch_planning_by_id(launch_id)? else {
            return Ok(None);
        };
        if record.requested_by != requested_by {
            return Ok(None);
        }
        // Root publication is authoritative; the planning row is auxiliary.
        // Repair an interrupted bind while answering the exact owner rather
        // than leaving the caller unable to distinguish admission from loss.
        if record.state == "planning"
            && let Some(thread) = g.state_db.get_thread(&record.reserved_thread_id)?
        {
            validate_launch_planning_owner(&record, thread.requested_by.as_deref())?;
            g.runtime_db
                .bind_launch_planning(&record.reserved_thread_id)?;
            record = g
                .runtime_db
                .launch_planning_by_id(launch_id)?
                .ok_or_else(|| anyhow!("launch planning disappeared during status repair"))?;
        }
        let thread_id = match record.state.as_str() {
            "bound" => {
                let bound_thread_id = record.bound_thread_id.ok_or_else(|| {
                    anyhow!(
                        "bound launch planning record `{launch_id}` has no authoritative thread binding"
                    )
                })?;
                if bound_thread_id != record.reserved_thread_id {
                    bail!(
                        "bound launch planning record `{launch_id}` has divergent reserved and authoritative thread identities"
                    );
                }
                Some(bound_thread_id)
            }
            "qualified" | "planning" | "cancelled" | "failed" | "expired" => None,
            other => bail!("launch planning record `{launch_id}` has unknown state `{other}`"),
        };
        Ok(Some(LaunchPlanningStatus {
            launch_id: record.launch_id,
            thread_id,
            status: record.state,
            outcome_code: record.outcome_code,
        }))
    }

    /// Read one owner-bound launch-planning row without hiding its pre-minted
    /// thread coordinate. Candidate integration uses this only after the same
    /// coordinate was atomically committed with owner qualification.
    pub fn launch_planning_record_for_owner(
        &self,
        launch_id: &str,
        requested_by: &str,
    ) -> Result<Option<runtime_db::LaunchPlanningRecord>> {
        let g = self.lock()?;
        Ok(g.runtime_db
            .launch_planning_by_id(launch_id)?
            .filter(|record| record.requested_by == requested_by))
    }

    pub fn activate_qualified_launch_planning(
        &self,
        launch_id: &str,
        reserved_thread_id: &str,
        requested_by: &str,
    ) -> Result<()> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if !g.runtime_db.activate_qualified_launch_planning(
            launch_id,
            reserved_thread_id,
            requested_by,
        )? {
            bail!("qualified launch planning coordinate is no longer startable");
        }
        Ok(())
    }

    pub fn ensure_launch_planning_active(&self, reserved_thread_id: &str) -> Result<()> {
        let g = self.lock()?;
        let Some(record) = g.runtime_db.launch_planning_by_thread(reserved_thread_id)? else {
            return Ok(());
        };
        if record.state != "planning"
            || record.daemon_generation_id != runtime_db::daemon_generation_id()
        {
            return Err(LaunchPlanningInactive.into());
        }
        Ok(())
    }

    pub fn register_launch_task_abort(
        &self,
        reserved_thread_id: &str,
        abort_handle: tokio::task::AbortHandle,
    ) -> std::result::Result<(), LaunchTaskAbortRegistrationError> {
        self.register_launch_task_abort_bounded(
            reserved_thread_id,
            abort_handle,
            MAX_ACTIVE_LAUNCH_SIGNALS,
        )
    }

    fn register_launch_task_abort_bounded(
        &self,
        reserved_thread_id: &str,
        abort_handle: tokio::task::AbortHandle,
        max_active_signals: usize,
    ) -> std::result::Result<(), LaunchTaskAbortRegistrationError> {
        let g = self.lock()?;
        let planning = g.runtime_db.launch_planning_by_thread(reserved_thread_id)?;
        let Some(record) = planning else {
            return Ok(());
        };
        if record.state == "bound" {
            return Ok(());
        }
        if record.state != "planning"
            || record.daemon_generation_id != runtime_db::daemon_generation_id()
        {
            abort_handle.abort();
            return Ok(());
        }
        let launch_id = record.launch_id;
        let mut handles = self
            .launch_task_abort_handles
            .lock()
            .map_err(|_| anyhow!("launch task abort registry lock poisoned"))?;
        if handles.len() >= max_active_signals && !handles.contains_key(&launch_id) {
            abort_handle.abort();
            return Err(LaunchTaskAbortRegistrationError::CapacityExceeded);
        }
        if let Some(previous) = handles.insert(launch_id, abort_handle) {
            previous.abort();
        }
        drop(handles);
        drop(g);
        Ok(())
    }

    pub fn unregister_launch_task_abort(&self, reserved_thread_id: &str) -> Result<()> {
        let launch_id = {
            let g = self.lock()?;
            g.runtime_db
                .launch_planning_by_thread(reserved_thread_id)?
                .map(|record| record.launch_id)
        };
        if let Some(launch_id) = launch_id {
            self.launch_task_abort_handles
                .lock()
                .map_err(|_| anyhow!("launch task abort registry lock poisoned"))?
                .remove(&launch_id);
        }
        Ok(())
    }

    /// Settle a pre-bind task exit, including unwind/abort paths. If the
    /// authoritative row committed first, repair the planning record to bound;
    /// otherwise mark it terminal failed. Already-terminal records are a no-op.
    pub fn settle_launch_planning_task_exit(&self, reserved_thread_id: &str) -> Result<()> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let Some(record) = g.runtime_db.launch_planning_by_thread(reserved_thread_id)? else {
            return Ok(());
        };
        if record.state != "planning" {
            return Ok(());
        }
        if let Some(thread) = g.state_db.get_thread(reserved_thread_id)? {
            validate_launch_planning_owner(&record, thread.requested_by.as_deref())?;
            g.runtime_db.bind_launch_planning(reserved_thread_id)?;
        } else {
            g.runtime_db.fail_launch_planning(reserved_thread_id)?;
        }
        Ok(())
    }

    /// Settle an accepted request that was durably reserved but refused before
    /// its background task took ownership. The exact coordinate remains
    /// queryable, proving that no authoritative thread was launched.
    pub fn settle_launch_planning_admission_exit(&self, reserved_thread_id: &str) -> Result<()> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let Some(record) = g.runtime_db.launch_planning_by_thread(reserved_thread_id)? else {
            return Ok(());
        };
        if record.state != "planning" {
            return Ok(());
        }
        if let Some(thread) = g.state_db.get_thread(reserved_thread_id)? {
            validate_launch_planning_owner(&record, thread.requested_by.as_deref())?;
            g.runtime_db.bind_launch_planning(reserved_thread_id)?;
        } else {
            g.runtime_db
                .fail_launch_planning_admission(reserved_thread_id)?;
        }
        Ok(())
    }

    /// Resolve cancel-vs-bind while holding the same store mutex used by root
    /// and continuation publication. A committed authoritative row always wins
    /// and is repaired to `bound` before the caller delegates to normal durable
    /// thread cancel.
    pub fn cancel_launch_planning(
        &self,
        launch_id: &str,
        requested_by: &str,
    ) -> Result<Option<LaunchCancellationResolution>> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let Some(record) = g.runtime_db.launch_planning_by_id(launch_id)? else {
            return Ok(None);
        };
        if record.requested_by != requested_by {
            return Ok(None);
        }
        if record.state == "qualified" {
            if g.state_db.get_thread(&record.reserved_thread_id)?.is_some() {
                bail!(
                    "qualified launch planning record `{launch_id}` unexpectedly has an authoritative thread"
                );
            }
            if g.runtime_db.cancel_unbound_launch_planning(launch_id)? {
                return Ok(Some(LaunchCancellationResolution::Cancelled));
            }
        }
        if record.state == "planning" {
            if let Some(thread) = g.state_db.get_thread(&record.reserved_thread_id)? {
                validate_launch_planning_owner(&record, thread.requested_by.as_deref())?;
                g.runtime_db
                    .bind_launch_planning(&record.reserved_thread_id)?;
                self.launch_task_abort_handles
                    .lock()
                    .map_err(|_| anyhow!("launch task abort registry lock poisoned"))?
                    .remove(launch_id);
                return Ok(Some(LaunchCancellationResolution::Bound {
                    thread_id: record.reserved_thread_id,
                }));
            }
            if g.runtime_db.cancel_unbound_launch_planning(launch_id)? {
                drop(g);
                if let Some(abort_handle) = self
                    .launch_task_abort_handles
                    .lock()
                    .map_err(|_| anyhow!("launch task abort registry lock poisoned"))?
                    .remove(launch_id)
                {
                    abort_handle.abort();
                }
                return Ok(Some(LaunchCancellationResolution::Cancelled));
            }
        }
        if record.state == "bound" {
            let thread_id = record.bound_thread_id.ok_or_else(|| {
                anyhow!(
                    "bound launch planning record `{launch_id}` has no authoritative thread binding"
                )
            })?;
            if thread_id != record.reserved_thread_id {
                bail!(
                    "bound launch planning record `{launch_id}` has divergent reserved and authoritative thread identities"
                );
            }
            return Ok(Some(LaunchCancellationResolution::Bound { thread_id }));
        }
        Ok(Some(LaunchCancellationResolution::Terminal {
            state: record.state,
            outcome_code: record.outcome_code,
        }))
    }

    pub fn reconcile_launch_planning(&self) -> Result<usize> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let mut repaired = 0usize;
        for record in g.runtime_db.pending_launch_planning()? {
            if let Some(thread) = g.state_db.get_thread(&record.reserved_thread_id)? {
                validate_launch_planning_owner(&record, thread.requested_by.as_deref())?;
                if g.runtime_db
                    .bind_launch_planning(&record.reserved_thread_id)?
                {
                    repaired += 1;
                }
            }
        }
        repaired += g.runtime_db.expire_stale_launch_planning()?;
        Ok(repaired)
    }

    /// Load at most two exact thread subjects under one state-store lock.
    /// Results retain input order and use `None` for a genuinely absent
    /// subject. Callers must collapse absence and authorization refusal before
    /// returning anything externally.
    pub fn authoritative_thread_subjects(
        &self,
        thread_ids: &[&str],
    ) -> Result<Vec<Option<AuthoritativeThreadSubject>>> {
        if thread_ids.is_empty() || thread_ids.len() > 2 {
            bail!("exact thread authority reads require one or two subjects");
        }
        let g = self.lock()?;
        thread_ids
            .iter()
            .map(|thread_id| {
                let Some(row) = g.state_db.get_thread(thread_id)? else {
                    return Ok(None);
                };
                let Some(snapshot) = g
                    .state_db
                    .read_authoritative_thread_snapshot(&row.chain_root_id, thread_id)?
                else {
                    bail!("thread {thread_id} is missing its authoritative signed snapshot");
                };
                if snapshot.thread_id.as_str() != *thread_id
                    || snapshot.chain_root_id != row.chain_root_id
                {
                    bail!("thread {thread_id} authoritative subject identity is inconsistent");
                }
                Ok(Some(AuthoritativeThreadSubject {
                    thread_id: snapshot.thread_id,
                    chain_root_id: snapshot.chain_root_id,
                    item_ref: snapshot.item_ref,
                    status: snapshot.status,
                    requested_by: snapshot.requested_by,
                    project_authority: snapshot.project_authority,
                    admitted_launch_capsule_hash: snapshot.admitted_launch_capsule_hash,
                }))
            })
            .collect()
    }

    pub fn get_thread(&self, thread_id: &str) -> Result<Option<ThreadDetail>> {
        let g = self.lock()?;
        let thread_row = match g.state_db.get_thread(thread_id)? {
            Some(row) => row,
            None => return Ok(None),
        };

        let runtime = g
            .runtime_db
            .get_runtime_info(thread_id)?
            .unwrap_or_default();
        let lifecycle_authority = runtime
            .launch_metadata
            .as_ref()
            .map(|metadata| metadata.lifecycle_authority())
            .transpose()?
            .flatten();
        // The projection locates this exact thread. Read both project
        // coordinates from the same verified immutable snapshot, rather than
        // treating its SQLite result-hash column or a newer chain tip as proof.
        let snapshot = g
            .state_db
            .read_authoritative_thread_snapshot(&thread_row.chain_root_id, thread_id)?;
        let result_project_snapshot_hash = snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.result_project_snapshot_hash.clone());
        let result_workspace_output_capture_hash = snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.result_workspace_output_capture_hash.clone());
        let project_authority = snapshot.map(|snapshot| snapshot.project_authority);

        let successor_thread_id = if is_terminal_status(&thread_row.status) {
            queries::continuation_successor(g.state_db.projection(), thread_id)?
        } else {
            None
        };

        Ok(Some(ThreadDetail {
            thread_id: thread_row.thread_id,
            chain_root_id: thread_row.chain_root_id,
            kind: thread_row.kind,
            status: thread_row.status,
            item_ref: thread_row.item_ref,
            executor_ref: thread_row.executor_ref,
            launch_mode: thread_row.launch_mode,
            current_site_id: thread_row.current_site_id,
            origin_site_id: thread_row.origin_site_id,
            upstream_thread_id: thread_row.upstream_thread_id,
            successor_thread_id,
            requested_by: thread_row.requested_by,
            project_root: thread_row.project_root,
            project_authority: project_authority.clone(),
            result_project_snapshot_hash,
            result_workspace_output_capture_hash,
            lifecycle_authority,
            admitted_launch_capsule_hash: thread_row.admitted_launch_capsule_hash,
            created_at: thread_row.created_at,
            updated_at: thread_row.updated_at,
            started_at: thread_row.started_at,
            finished_at: thread_row.finished_at,
            runtime,
        }))
    }

    /// Resolve the authoritative continuation tip for one stable execution
    /// chain. Hosted-worker callers address the chain root; operational state
    /// is always fenced to the exact placement thread at this verified tip.
    pub fn current_chain_placement_thread_id(&self, chain_root_id: &str) -> Result<Option<String>> {
        let mut cursor = chain_root_id.to_owned();
        let mut visited = std::collections::HashSet::new();
        for _ in 0..1024 {
            if !visited.insert(cursor.clone()) {
                bail!("execution continuation lineage contains a cycle");
            }
            let Some(thread) = self.get_thread(&cursor)? else {
                return if cursor == chain_root_id {
                    Ok(None)
                } else {
                    bail!("execution continuation successor `{cursor}` disappeared")
                };
            };
            if thread.chain_root_id != chain_root_id {
                bail!("execution continuation escaped its stable chain root");
            }
            match thread.successor_thread_id {
                Some(successor_thread_id) => {
                    let successor = self
                        .get_thread(&successor_thread_id)?
                        .ok_or_else(|| anyhow!("execution continuation successor disappeared"))?;
                    if successor.chain_root_id != chain_root_id
                        || successor.upstream_thread_id.as_deref() != Some(cursor.as_str())
                    {
                        bail!("execution continuation successor has contradictory lineage");
                    }
                    cursor = successor_thread_id;
                }
                None => return Ok(Some(cursor)),
            }
        }
        bail!("execution continuation lineage exceeds its bounded depth")
    }

    /// Read the immutable generation pinned by authoritative signed history.
    /// Runtime metadata and projection paths are never consulted.
    pub fn authoritative_project_generation(
        &self,
        thread_id: &str,
    ) -> Result<Option<(Option<String>, Option<String>)>> {
        let g = self.lock()?;
        let Some(row) = g.state_db.get_thread(thread_id)? else {
            return Ok(None);
        };
        let snapshot =
            authoritative_snapshot_for_transition(&g, &row.chain_root_id, &row.thread_id)?;
        Ok(Some((
            snapshot.base_project_snapshot_hash,
            snapshot.result_project_snapshot_hash,
        )))
    }

    /// Exact terminal source/output pair from immutable thread authority. This
    /// does not follow a continuation or treat the launch generation as output.
    pub fn authoritative_result_generation(
        &self,
        thread_id: &str,
    ) -> Result<Option<ryeos_state::objects::WorkspaceGenerationPair>> {
        let g = self.lock()?;
        let row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("terminal result thread does not exist: {thread_id}"))?;
        let snapshot = authoritative_snapshot_for_transition(&g, &row.chain_root_id, thread_id)?;
        snapshot.verify_result_workspace_output_capture(&self.state_authority.cas_store()?)?;
        if snapshot.result_project_snapshot_hash.is_some() && !snapshot.status.is_terminal() {
            bail!("retained result generation requires an authoritative terminal thread");
        }
        Ok(snapshot.result_project_snapshot_hash.map(|snapshot_hash| {
            ryeos_state::objects::WorkspaceGenerationPair {
                snapshot_hash,
                output_capture_hash: snapshot.result_workspace_output_capture_hash,
            }
        }))
    }

    pub fn touch_seat_lease(
        &self,
        thread_id: &str,
        owner: &str,
        surface: &str,
        client_ref: &str,
    ) -> Result<()> {
        // A seat lease belongs to a thread of a kind whose profile declares a
        // retirement fence; the kind comes from installed profile data. The
        // fenced kinds stand for the seat kinds in this tranche because the
        // only fenced kind is the seat profile; the seat writers will make
        // the seat-lease kind its own declared datum.
        let fenced = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("seat thread {thread_id} does not exist"))?;
        if !fenced.contains(&thread.kind)
            || thread.status != ThreadStatus::Running.as_str()
            || thread.requested_by.as_deref() != Some(owner)
            || thread.item_ref != surface
        {
            bail!("seat thread {thread_id} is not a matching running owned seat");
        }
        let _admission = g.state_db.authorize_runtime_pin(&thread.chain_root_id)?;
        if !g
            .runtime_db
            .touch_seat_lease(thread_id, owner, surface, client_ref)?
        {
            bail!("seat thread {thread_id} is being reaped");
        }
        Ok(())
    }

    pub fn touch_existing_seat_lease(&self, thread_id: &str) -> Result<bool> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let _admission = Self::authorize_runtime_pin_for_thread(&g, thread_id)?;
        g.runtime_db.touch_existing_seat_lease(thread_id)
    }

    pub fn remove_seat_lease(&self, thread_id: &str) -> Result<()> {
        let g = self.lock()?;
        g.runtime_db.remove_seat_lease(thread_id)
    }

    pub fn seat_leases_for_owner_client(
        &self,
        owner: &str,
        client_ref: &str,
    ) -> Result<Vec<String>> {
        let g = self.lock()?;
        g.runtime_db.seat_leases_for_owner_client(owner, client_ref)
    }

    pub fn expired_seat_leases(&self, cutoff_ms: i64) -> Result<Vec<String>> {
        let g = self.lock()?;
        g.runtime_db.expired_seat_leases(cutoff_ms)
    }

    pub fn expired_seat_leases_slice(
        &self,
        cutoff_ms: i64,
        after_id: Option<&str>,
        cycle_max_id: &str,
        limit: usize,
    ) -> Result<runtime_db::SeatLeaseMaintenancePage> {
        let g = self.lock()?;
        g.runtime_db
            .expired_seat_leases_slice(cutoff_ms, after_id, cycle_max_id, limit)
    }

    pub fn max_seat_lease_id(&self) -> Result<Option<String>> {
        let g = self.lock()?;
        g.runtime_db.max_seat_lease_id()
    }

    pub fn claimed_seat_leases_slice(
        &self,
        after_id: Option<&str>,
        cycle_max_id: &str,
        limit: usize,
    ) -> Result<Vec<String>> {
        let g = self.lock()?;
        g.runtime_db
            .claimed_seat_leases_slice(after_id, cycle_max_id, limit)
    }

    pub fn claim_expired_seat_lease(&self, thread_id: &str, cutoff_ms: i64) -> Result<bool> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let _admission = Self::authorize_runtime_pin_for_thread(&g, thread_id)?;
        g.runtime_db.claim_expired_seat_lease(thread_id, cutoff_ms)
    }

    /// Run a short, synchronous action only while every supplied thread is
    /// still at its exact trust-verified signed frontier; `None` means a cut is
    /// stale. The callback holds the Store and every chain lock: it must not
    /// reenter StateStore, state authority or CAS, take locks, do I/O or write
    /// durable state.
    pub fn with_thread_event_read_anchors<T>(
        &self,
        anchors: &[ryeos_state::AuthoritativeThreadEventReadAnchor],
        action: impl FnOnce() -> Result<T>,
    ) -> Result<Option<T>> {
        let guard = self.state_authority.acquire_shared_guard()?;
        let g = self.lock()?;
        g.state_db
            .with_thread_event_read_anchors(&guard, anchors, action)
    }

    /// The same exclusion for a cut that also depends on retired chains, which
    /// must still be headless and fenced with the recorded closure. At least
    /// one retired dependency is required.
    pub fn with_thread_event_read_mixed_cut<T>(
        &self,
        current_anchors: &[ryeos_state::AuthoritativeThreadEventReadAnchor],
        retired: &[ryeos_state::RetiredChainDependency],
        action: impl FnOnce() -> Result<T>,
    ) -> Result<Option<T>> {
        let guard = self.state_authority.acquire_shared_guard()?;
        let g = self.lock()?;
        g.state_db
            .with_thread_event_read_mixed_cut(&guard, current_anchors, retired, action)
    }

    /// One immutable thread event by exact CAS hash, authenticated against its
    /// content hash and never taken from the projection. `None` means the
    /// object is not retained; a non-canonical hash refuses.
    pub fn retained_thread_event_by_hash(
        &self,
        event_hash: &str,
    ) -> Result<Option<ryeos_state::objects::ThreadEvent>> {
        let guard = self.state_authority.acquire_shared_guard()?;
        let g = self.lock()?;
        g.state_db.retained_thread_event_by_hash(event_hash, &guard)
    }

    fn with_cut_locked<T>(
        g: &Inner,
        guard: &ryeos_state::CasMutationGuard,
        anchors: &[ryeos_state::AuthoritativeThreadEventReadAnchor],
        retired: &[ryeos_state::RetiredChainDependency],
        action: impl FnOnce() -> Result<T>,
    ) -> Result<Option<T>> {
        if retired.is_empty() {
            g.state_db
                .with_thread_event_read_anchors(guard, anchors, action)
        } else {
            g.state_db
                .with_thread_event_read_mixed_cut(guard, anchors, retired, action)
        }
    }

    fn validate_seat_cut(seat: &ExactSeat<'_>, cut: &SeatCut<'_>) -> Result<()> {
        if seat.root_id.is_empty()
            || cut.expected.chain_root_id() != seat.root_id
            || cut.expected.thread_id() != seat.root_id
        {
            bail!("seat action requires an exact seat root anchor");
        }
        if !cut.anchors.iter().any(|anchor| anchor == cut.expected) {
            bail!("seat action cut omits the exact seat root anchor");
        }
        if cut
            .anchors
            .iter()
            .any(|anchor| anchor.chain_root_id() == seat.root_id && anchor != cut.expected)
        {
            bail!("seat action cut carries a second anchor for the seat root chain");
        }
        Ok(())
    }

    fn seat_snapshot_matches(
        snapshot: &ThreadSnapshot,
        seat: &ExactSeat<'_>,
        fenced: &ryeos_state::FencedChainKinds,
    ) -> bool {
        snapshot.chain_root_id == seat.root_id
            && snapshot.thread_id == seat.root_id
            && fenced.contains(&snapshot.kind_name)
            && snapshot.status == ThreadStatus::Running
            && snapshot.requested_by.as_deref() == Some(seat.owner)
            && snapshot.item_ref == seat.item_ref
            && snapshot.executor_ref == seat.executor_ref
    }

    /// Whether the seat root is, right now, exactly the anchored running seat.
    /// This runs before the chain locks. The anchor binds the chain head and
    /// the snapshot hash, so the anchor is compared first and the snapshot
    /// read after it; the caller's later exclusion re-proves the same anchor
    /// under the locks, and a head unchanged at both ends cannot have carried
    /// a different snapshot in between. Reading the snapshot first would leave
    /// it unbound to the cut.
    fn seat_anchor_state(
        &self,
        g: &Inner,
        guard: &ryeos_state::CasMutationGuard,
        seat: &ExactSeat<'_>,
        expected: &ryeos_state::AuthoritativeThreadEventReadAnchor,
    ) -> Result<SeatAnchorState> {
        let fenced = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let current =
            g.state_db
                .capture_thread_event_read_anchor(seat.root_id, seat.root_id, guard)?;
        if current.as_ref() != Some(expected) {
            return Ok(SeatAnchorState::Moved);
        }
        let Some(snapshot) = g
            .state_db
            .read_authoritative_thread_snapshot(seat.root_id, seat.root_id)?
        else {
            return Ok(SeatAnchorState::Moved);
        };
        Ok(if Self::seat_snapshot_matches(&snapshot, seat, fenced) {
            SeatAnchorState::Current
        } else {
            SeatAnchorState::NotThisSeat
        })
    }

    fn with_exact_seat_cut<T>(
        &self,
        seat: &ExactSeat<'_>,
        cut: &SeatCut<'_>,
        refuse_claimed: bool,
        refuse_stopping: bool,
        action: impl FnOnce(&runtime_db::RuntimeDb) -> Result<T>,
    ) -> Result<Option<T>> {
        Self::validate_seat_cut(seat, cut)?;
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if refuse_stopping && !Self::stop_intent_clear(&g, seat.root_id)? {
            return Ok(None);
        }
        if self.seat_anchor_state(&g, permit.cas_guard(), seat, cut.expected)?
            != SeatAnchorState::Current
        {
            return Ok(None);
        }
        let outcome =
            Self::with_cut_locked(&g, permit.cas_guard(), cut.anchors, cut.retired, || {
                if refuse_claimed && g.runtime_db.seat_lease_is_reaping(seat.root_id)? {
                    return Ok(None);
                }
                action(&g.runtime_db).map(Some)
            })?;
        Ok(outcome.flatten())
    }

    /// Admit a short, synchronous publication for one exact running seat. The
    /// seat's signed snapshot is proved before the chain locks and bound to
    /// the cut, which is re-proved under the locks the callback runs under. A
    /// seat whose lease is claimed for reaping, or whose runtime row is
    /// missing or carries a stop intent, is refused. `None` means not
    /// admitted. A seat identity the signed snapshot does not carry is not
    /// admitted either. The callback must not reenter StateStore, state
    /// authority or CAS.
    pub fn with_exact_seat_action_if_anchor<T>(
        &self,
        seat: &ExactSeat<'_>,
        expected: &ryeos_state::AuthoritativeThreadEventReadAnchor,
        action: impl FnOnce() -> Result<T>,
    ) -> Result<Option<T>> {
        self.with_exact_seat_action_if_anchors(
            seat,
            expected,
            std::slice::from_ref(expected),
            action,
        )
    }

    /// The same admission conditioned on every completed paired-cut head.
    pub fn with_exact_seat_action_if_anchors<T>(
        &self,
        seat: &ExactSeat<'_>,
        expected: &ryeos_state::AuthoritativeThreadEventReadAnchor,
        anchors: &[ryeos_state::AuthoritativeThreadEventReadAnchor],
        action: impl FnOnce() -> Result<T>,
    ) -> Result<Option<T>> {
        self.with_exact_seat_action_if_mixed_cut(
            seat,
            &SeatCut {
                expected,
                anchors,
                retired: &[],
            },
            action,
        )
    }

    /// The same admission conditioned on live frontiers and retired fences.
    pub fn with_exact_seat_action_if_mixed_cut<T>(
        &self,
        seat: &ExactSeat<'_>,
        cut: &SeatCut<'_>,
        action: impl FnOnce() -> Result<T>,
    ) -> Result<Option<T>> {
        self.with_exact_seat_cut(seat, cut, true, true, |_| action())
    }

    /// Renew an exact seat's lease only while the seat is the anchored running
    /// seat and every supplied live head is current. `false` means not
    /// renewed: a stale cut, a different seat identity, a claimed lease, or a
    /// runtime row that is missing or carries a stop intent.
    pub fn touch_seat_lease_if_anchors(
        &self,
        seat: &ExactSeat<'_>,
        expected: &ryeos_state::AuthoritativeThreadEventReadAnchor,
        anchors: &[ryeos_state::AuthoritativeThreadEventReadAnchor],
    ) -> Result<bool> {
        self.touch_seat_lease_if_mixed_cut(
            seat,
            &SeatCut {
                expected,
                anchors,
                retired: &[],
            },
        )
    }

    /// Lease renewal conditioned on live frontiers and retired fences.
    pub fn touch_seat_lease_if_mixed_cut(
        &self,
        seat: &ExactSeat<'_>,
        cut: &SeatCut<'_>,
    ) -> Result<bool> {
        self.with_exact_seat_cut(seat, cut, false, true, |db| {
            db.touch_seat_lease(seat.root_id, seat.owner, seat.item_ref, seat.executor_ref)
        })
        .map(|renewed| renewed.unwrap_or(false))
    }

    /// Mark an exact seat's lease for reaping only when the anchored tip of
    /// its signed history is the event `is_closing_tip` accepts, the seat is
    /// still the anchored running seat, and the cut is current. A later
    /// suffix, a stale cut, a missing or non-matching tip, or a different
    /// lease identity returns `false`. Claiming an already claimed lease keeps
    /// its first marker and returns `true`. A stop intent does not block the
    /// claim: a closed seat must stay claimable so the stop it carries can
    /// settle through reaping.
    pub fn claim_closed_seat_lease_if_tip(
        &self,
        seat: &ExactSeat<'_>,
        cut: &SeatCut<'_>,
        is_closing_tip: impl FnOnce(&ryeos_state::objects::ThreadEvent) -> Result<bool>,
    ) -> Result<bool> {
        Self::validate_seat_cut(seat, cut)?;
        let Some((tip_hash, tip_seq)) = cut.expected.tip() else {
            return Ok(false);
        };
        let Some(tip) = self.retained_thread_event_by_hash(tip_hash)? else {
            return Ok(false);
        };
        if tip.chain_root_id != seat.root_id
            || tip.thread_id != seat.root_id
            || tip.thread_seq != tip_seq
            || !is_closing_tip(&tip)?
        {
            return Ok(false);
        }
        self.with_exact_seat_cut(seat, cut, false, false, |db| {
            db.claim_closed_seat_lease(seat.root_id, seat.owner, seat.item_ref, seat.executor_ref)
        })
        .map(|claimed| claimed.unwrap_or(false))
    }

    /// Release a claimed lease's durable fence, but only once the exact root
    /// is terminal in signed authority and of a fenced kind. Projection
    /// absence or a projected status is never evidence. `false` means the
    /// proof does not hold (including a head that moved while proving).
    pub fn remove_terminal_seat_lease_if_proved(&self, thread_id: &str) -> Result<bool> {
        let fenced = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let g = self.lock()?;
        let Some(readback) = g
            .state_db
            .read_authoritative_thread_snapshot_with_last_event(thread_id, thread_id)?
        else {
            return Ok(false);
        };
        let admission = g.state_db.authorize_runtime_pin(thread_id)?;
        let snapshot = &readback.snapshot;
        if admission.head_hash != readback.chain_head_hash
            || snapshot.thread_id != thread_id
            || snapshot.chain_root_id != thread_id
            || !fenced.contains(&snapshot.kind_name)
            || !snapshot.status.is_terminal()
        {
            return Ok(false);
        }
        g.runtime_db.remove_seat_lease(thread_id)?;
        Ok(true)
    }

    /// Whether a runtime row exists for the thread and carries no stop intent.
    fn stop_intent_clear(g: &Inner, thread_id: &str) -> Result<bool> {
        Ok(g.runtime_db
            .get_runtime_info(thread_id)?
            .is_some_and(|runtime| runtime.stop_intent.is_none()))
    }

    /// The signed snapshot of a target that may take an ordinary append now:
    /// signed status is running, its runtime row exists without a stop
    /// intent, and process-attachment admission is open. `None` means not
    /// admitted. The projection is never consulted; the publishing primitive
    /// re-proves the snapshot under the chain locks.
    fn running_append_snapshot(
        &self,
        g: &Inner,
        chain_root_id: &str,
        thread_id: &str,
    ) -> Result<Option<ThreadSnapshot>> {
        let Some(snapshot) = g
            .state_db
            .read_authoritative_thread_snapshot(chain_root_id, thread_id)?
        else {
            return Ok(None);
        };
        if snapshot.chain_root_id != chain_root_id
            || snapshot.thread_id != thread_id
            || snapshot.status != ThreadStatus::Running
            || !Self::stop_intent_clear(g, thread_id)?
            || !self
                .process_attachment_admission_open
                .load(Ordering::Acquire)
        {
            return Ok(None);
        }
        Ok(Some(snapshot))
    }

    fn durable_cut_events(
        events: &[NewEventRecord],
        chain_root_id: &str,
        thread_id: &str,
    ) -> Result<Vec<ryeos_state::objects::ThreadEvent>> {
        if events.is_empty()
            || events
                .iter()
                .any(|event| event.storage_class == "ephemeral")
            || has_indexed_collection_events(events)
        {
            bail!("conditional append requires a nonempty durable batch without collection events");
        }
        let converted = convert_events(events, chain_root_id, thread_id);
        for event in &converted {
            event.validate()?;
        }
        Ok(converted)
    }

    /// Append to a running chain root only while its own frontier, a live
    /// counterpart chain, every further live head and every retired fence in
    /// the request are exactly as read, all checked under the ordered chain
    /// locks that publish. `admit` runs under those locks immediately before
    /// publication and must not reenter StateStore. A moved cut or a `false`
    /// admission returns `Conflict` with nothing written; an error leaves
    /// retry policy with the caller. A batch whose commit cannot be proved or
    /// disproved from signed history fails as an uncertain commit.
    pub fn append_events_if_mixed_cut(
        &self,
        request: &MixedCutAppend<'_>,
        admit: impl FnOnce(MixedCutAdmission<'_>) -> Result<bool>,
    ) -> Result<CutAppendResult> {
        let converted =
            Self::durable_cut_events(request.events, request.chain_root_id, request.thread_id)?;
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        if self
            .running_append_snapshot(&g, request.chain_root_id, request.thread_id)?
            .is_none()
        {
            return Ok(CutAppendResult::NotRunning);
        }
        let predecessor = g
            .state_db
            .read_authoritative_thread_append_anchor(request.chain_root_id, request.thread_id)?
            .ok_or_else(|| anyhow!("conditional append has no signed predecessor"))?;
        let dependencies = ryeos_state::MixedCutDependencies {
            current_anchors: request.current_anchors,
            retired: request.retired,
        };
        let committed = match request.counterpart {
            Some(counterpart) => g
                .state_db
                .append_running_events_admitted_if_mixed_cut_with_admission(
                    ryeos_state::TwoAnchorThreadAppend {
                        chain_root_id: request.chain_root_id,
                        thread_id: request.thread_id,
                        events: converted.clone(),
                        signer: g.signer.as_ref(),
                        runtime_liveness: &g.runtime_db,
                        expected: request.expected,
                        counterpart,
                        required_target_kind: request.required_target_kind,
                    },
                    dependencies,
                    permit.cas_guard(),
                    |view| {
                        admit(MixedCutAdmission {
                            target: view.target,
                            target_thread_ids: view.target_thread_ids,
                            counterpart: Some(view.counterpart),
                        })
                    },
                ),
            None => g
                .state_db
                .append_running_events_admitted_if_single_anchor_mixed_cut_with_admission(
                    ryeos_state::SingleAnchorThreadAppend {
                        chain_root_id: request.chain_root_id,
                        thread_id: request.thread_id,
                        events: converted.clone(),
                        signer: g.signer.as_ref(),
                        runtime_liveness: &g.runtime_db,
                        expected: request.expected,
                        required_target_kind: request.required_target_kind,
                    },
                    dependencies,
                    permit.cas_guard(),
                    |view| {
                        admit(MixedCutAdmission {
                            target: view.target,
                            target_thread_ids: view.target_thread_ids,
                            counterpart: None,
                        })
                    },
                ),
        };
        Self::cut_append_result(
            &g,
            request.chain_root_id,
            request.thread_id,
            &predecessor,
            &converted,
            request.events,
            committed,
        )
        .map(|result| result.unwrap_or(CutAppendResult::Conflict))
    }

    fn cut_append_result(
        g: &Inner,
        chain_root_id: &str,
        thread_id: &str,
        predecessor: &ryeos_state::AuthoritativeThreadAppendAnchorReadback,
        attempted: &[ryeos_state::objects::ThreadEvent],
        events: &[NewEventRecord],
        committed: Result<ryeos_state::ConditionalThreadEventAppendResult>,
    ) -> Result<Option<CutAppendResult>> {
        match committed {
            Ok(ryeos_state::ConditionalThreadEventAppendResult::Committed(committed)) => {
                Ok(Some(CutAppendResult::Committed(persisted_from_append(
                    &committed_value(committed),
                    events,
                )?)))
            }
            Ok(ryeos_state::ConditionalThreadEventAppendResult::Conflict) => Ok(None),
            Err(error) => committed_append_after_error(
                g,
                chain_root_id,
                thread_id,
                predecessor,
                attempted,
                events,
                error,
            )
            .map(|persisted| Some(CutAppendResult::Committed(persisted))),
        }
    }

    /// Append durable events to an exact running seat root and renew its
    /// lease in the same gated step. The signed seat status and identity are
    /// checked before the locks and again, with the cut and the lease being
    /// unclaimed, under the chain locks that publish; the lease is renewed
    /// only after the batch is published. A seat that is not the admitted
    /// running seat (finished, not a fenced kind, stopping, missing runtime
    /// row) or whose lease is claimed returns `NotRunning`; a moved cut
    /// returns `Conflict`. Neither writes, and an error before publication
    /// leaves the lease untouched.
    /// When the cut names another live chain, that chain is the counterpart of
    /// the guarded append; a cut with only retired dependencies is guarded as
    /// a single-target append under the same fences.
    pub fn append_seat_events_and_renew_if_mixed_cut(
        &self,
        seat: &ExactSeat<'_>,
        events: &[NewEventRecord],
        cut: &SeatCut<'_>,
    ) -> Result<CutAppendResult> {
        self.append_seat_events_and_renew_if_mixed_cut_admitted(seat, events, cut, |_| Ok(true))
    }

    /// The seat append of `append_seat_events_and_renew_if_mixed_cut` with a
    /// domain admission. `admit` runs under every chain lock of the cut,
    /// after the seat identity, status and unclaimed lease are re-proved and
    /// immediately before publication; it must not reenter StateStore. `false`
    /// is a `Conflict` with nothing written and the lease untouched. The
    /// lease is renewed only after the batch is published.
    pub fn append_seat_events_and_renew_if_mixed_cut_admitted(
        &self,
        seat: &ExactSeat<'_>,
        events: &[NewEventRecord],
        cut: &SeatCut<'_>,
        admit: impl FnOnce(MixedCutAdmission<'_>) -> Result<bool>,
    ) -> Result<CutAppendResult> {
        Self::validate_seat_cut(seat, cut)?;
        let converted = Self::durable_cut_events(events, seat.root_id, seat.root_id)?;
        let fenced = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let Some(snapshot) = self.running_append_snapshot(&g, seat.root_id, seat.root_id)? else {
            return Ok(CutAppendResult::NotRunning);
        };
        if !Self::seat_snapshot_matches(&snapshot, seat, fenced) {
            return Ok(CutAppendResult::NotRunning);
        }
        let predecessor = g
            .state_db
            .read_authoritative_thread_append_anchor(seat.root_id, seat.root_id)?
            .ok_or_else(|| anyhow!("seat append has no signed predecessor"))?;
        let refused = std::cell::Cell::new(false);
        // Runs under the publishing chain locks. It only reads: the lease is
        // renewed after the batch is published, so a refusal or an error
        // before publication leaves the lease untouched.
        let admit_seat = |view: MixedCutAdmission<'_>| -> Result<bool> {
            if !Self::seat_snapshot_matches(view.target, seat, fenced)
                || g.runtime_db.seat_lease_is_reaping(seat.root_id)?
            {
                refused.set(true);
                return Ok(false);
            }
            admit(view)
        };
        let dependencies = ryeos_state::MixedCutDependencies {
            current_anchors: cut.anchors,
            retired: cut.retired,
        };
        let committed = match cut
            .anchors
            .iter()
            .find(|anchor| anchor.chain_root_id() != seat.root_id)
        {
            Some(counterpart) => g
                .state_db
                .append_running_events_admitted_if_mixed_cut_with_admission(
                    ryeos_state::TwoAnchorThreadAppend {
                        chain_root_id: seat.root_id,
                        thread_id: seat.root_id,
                        events: converted.clone(),
                        signer: g.signer.as_ref(),
                        runtime_liveness: &g.runtime_db,
                        expected: cut.expected,
                        counterpart,
                        required_target_kind: &snapshot.kind_name,
                    },
                    dependencies,
                    permit.cas_guard(),
                    |view| {
                        admit_seat(MixedCutAdmission {
                            target: view.target,
                            target_thread_ids: view.target_thread_ids,
                            counterpart: Some(view.counterpart),
                        })
                    },
                ),
            None => g
                .state_db
                .append_running_events_admitted_if_single_anchor_mixed_cut_with_admission(
                    ryeos_state::SingleAnchorThreadAppend {
                        chain_root_id: seat.root_id,
                        thread_id: seat.root_id,
                        events: converted.clone(),
                        signer: g.signer.as_ref(),
                        runtime_liveness: &g.runtime_db,
                        expected: cut.expected,
                        required_target_kind: &snapshot.kind_name,
                    },
                    dependencies,
                    permit.cas_guard(),
                    |view| {
                        admit_seat(MixedCutAdmission {
                            target: view.target,
                            target_thread_ids: view.target_thread_ids,
                            counterpart: None,
                        })
                    },
                ),
        };
        let result = Self::cut_append_result(
            &g,
            seat.root_id,
            seat.root_id,
            &predecessor,
            &converted,
            events,
            committed,
        )?;
        Ok(match result {
            Some(result) => {
                if matches!(result, CutAppendResult::Committed(_)) {
                    match g.runtime_db.touch_seat_lease(
                        seat.root_id,
                        seat.owner,
                        seat.item_ref,
                        seat.executor_ref,
                    ) {
                        Ok(true) => {}
                        Ok(false) => tracing::error!(
                            seat = seat.root_id,
                            "seat lease was claimed after its append was admitted"
                        ),
                        Err(error) => tracing::error!(
                            seat = seat.root_id,
                            error = %error,
                            "seat lease renewal failed after its append was published"
                        ),
                    }
                }
                result
            }
            None if refused.get() => CutAppendResult::NotRunning,
            None => CutAppendResult::Conflict,
        })
    }

    /// Publish an ordered pair of events to two exact seats under one cut.
    /// Both seats are checked as the admitted running seat (signed identity,
    /// runtime row without a stop intent, lease unclaimed) before the locks
    /// and again under every chain lock of the cut, together with the
    /// caller's `admit`. The first seat takes `first_events`; `build_second`
    /// then receives that commit and returns the second seat's batch, which
    /// is published under the same locks. Both leases are renewed only after
    /// both batches are published. A seat that is not admitted returns
    /// `NotRunning` and a moved cut or refused admission returns `Conflict`,
    /// neither writing. Any failure after the first publication is reported
    /// as partial, never as a refusal. Neither callback may reenter StateStore.
    pub fn append_seat_pair_if_mixed_cut(
        &self,
        request: &SeatPairAppend<'_>,
        admit: impl FnOnce(SeatPairAdmission<'_>) -> Result<bool>,
        build_second: impl FnOnce(&[PersistedEventRecord]) -> Result<Vec<NewEventRecord>>,
    ) -> Result<CutPairAppendResult> {
        let SeatPairAppend {
            first,
            second,
            second_anchor,
            first_events,
            cut,
        } = *request;
        Self::validate_seat_cut(first, cut)?;
        if first.root_id == second.root_id
            || second_anchor.chain_root_id() != second.root_id
            || second_anchor.thread_id() != second.root_id
            || !cut.anchors.iter().any(|anchor| anchor == second_anchor)
        {
            bail!("seat pair append requires two distinct exact seat roots in the cut");
        }
        let first_converted = Self::durable_cut_events(first_events, first.root_id, first.root_id)?;
        let fenced = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let (Some(first_snapshot), Some(second_snapshot)) = (
            self.running_append_snapshot(&g, first.root_id, first.root_id)?,
            self.running_append_snapshot(&g, second.root_id, second.root_id)?,
        ) else {
            return Ok(CutPairAppendResult::NotRunning);
        };
        if !Self::seat_snapshot_matches(&first_snapshot, first, fenced)
            || !Self::seat_snapshot_matches(&second_snapshot, second, fenced)
        {
            return Ok(CutPairAppendResult::NotRunning);
        }
        let predecessor = g
            .state_db
            .read_authoritative_thread_append_anchor(first.root_id, first.root_id)?
            .ok_or_else(|| anyhow!("seat pair append has no signed predecessor"))?;
        let refused = std::cell::Cell::new(false);
        let second_new = std::cell::RefCell::new(Vec::new());
        let admitted = |view: ryeos_state::TwoAnchorAdmissionView<'_>| -> Result<bool> {
            for (snapshot, seat) in [(view.target, first), (view.counterpart, second)] {
                if !Self::seat_snapshot_matches(snapshot, seat, fenced)
                    || g.runtime_db.seat_lease_is_reaping(seat.root_id)?
                    || !Self::stop_intent_clear(&g, seat.root_id)?
                {
                    refused.set(true);
                    return Ok(false);
                }
            }
            admit(SeatPairAdmission {
                first: view.target,
                second: view.counterpart,
            })
        };
        let committed = g.state_db.append_running_event_pair_admitted_if_mixed_cut(
            ryeos_state::OrderedPairThreadAppend {
                first: cut.expected,
                second: second_anchor,
                first_events: first_converted.clone(),
                signer: g.signer.as_ref(),
                runtime_liveness: &g.runtime_db,
                required_first_kind: &first_snapshot.kind_name,
                required_second_kind: &second_snapshot.kind_name,
            },
            ryeos_state::MixedCutDependencies {
                current_anchors: cut.anchors,
                retired: cut.retired,
            },
            permit.cas_guard(),
            admitted,
            |committed, _frontier| {
                let persisted = persisted_from_append(&committed.value, first_events)?;
                let events = build_second(&persisted)?;
                let converted = Self::durable_cut_events(&events, second.root_id, second.root_id)?;
                *second_new.borrow_mut() = events;
                Ok(converted)
            },
        );
        Ok(match committed {
            Ok(ryeos_state::ConditionalThreadEventPairAppendResult::Committed {
                first: first_committed,
                second: second_committed,
            }) => {
                let first_records = persisted_from_append(
                    &committed_value(first_committed),
                    first_events,
                )?;
                let second_records = persisted_from_append(
                    &committed_value(second_committed),
                    &second_new.borrow(),
                )?;
                for seat in [first, second] {
                    match g.runtime_db.touch_seat_lease(
                        seat.root_id,
                        seat.owner,
                        seat.item_ref,
                        seat.executor_ref,
                    ) {
                        Ok(true) => {}
                        Ok(false) => tracing::error!(
                            seat = seat.root_id,
                            "seat lease was claimed after its pair append was admitted"
                        ),
                        Err(error) => tracing::error!(
                            seat = seat.root_id,
                            error = %error,
                            "seat lease renewal failed after its pair append was published"
                        ),
                    }
                }
                CutPairAppendResult::Committed {
                    first: first_records,
                    second: second_records,
                }
            }
            Ok(ryeos_state::ConditionalThreadEventPairAppendResult::Conflict) => {
                if refused.get() {
                    CutPairAppendResult::NotRunning
                } else {
                    CutPairAppendResult::Conflict
                }
            }
            Ok(ryeos_state::ConditionalThreadEventPairAppendResult::FirstUncertain { error }) => {
                // The first publication may or may not have happened: report
                // the observed signed outcome, not the raw write error.
                match committed_append_after_error(
                    &g,
                    first.root_id,
                    first.root_id,
                    &predecessor,
                    &first_converted,
                    first_events,
                    error,
                ) {
                    Ok(first_records) => CutPairAppendResult::FirstCommittedSecondUncertain {
                        first: first_records,
                        error: anyhow!(
                            "the first write reported an error after publishing; the second seat was not attempted"
                        ),
                    },
                    Err(error) => CutPairAppendResult::FirstUncertain(error),
                }
            }
            Ok(
                ryeos_state::ConditionalThreadEventPairAppendResult::FirstCommittedSecondUncertain {
                    first: first_committed,
                    error,
                },
            ) => CutPairAppendResult::FirstCommittedSecondUncertain {
                first: persisted_from_append(&committed_value(first_committed), first_events)?,
                error,
            },
            Err(error) => return Err(error),
        })
    }

    /// Seat append conditioned on a completed paired history cut.
    pub fn append_seat_events_and_renew_if_anchors(
        &self,
        seat: &ExactSeat<'_>,
        events: &[NewEventRecord],
        expected: &ryeos_state::AuthoritativeThreadEventReadAnchor,
        anchors: &[ryeos_state::AuthoritativeThreadEventReadAnchor],
    ) -> Result<CutAppendResult> {
        self.append_seat_events_and_renew_if_mixed_cut(
            seat,
            events,
            &SeatCut {
                expected,
                anchors,
                retired: &[],
            },
        )
    }

    /// Seat append conditioned only on the seat's own exact frontier.
    pub fn append_seat_events_and_renew_if_anchor(
        &self,
        seat: &ExactSeat<'_>,
        events: &[NewEventRecord],
        expected: &ryeos_state::AuthoritativeThreadEventReadAnchor,
    ) -> Result<CutAppendResult> {
        self.append_seat_events_and_renew_if_anchors(
            seat,
            events,
            expected,
            std::slice::from_ref(expected),
        )
    }

    /// Result facts from the signed thread snapshot instead of the rebuildable
    /// result projection. The caller has already authorized this exact
    /// thread; the signed status must still be `expected_status`.
    pub fn get_thread_result_authoritative(
        &self,
        chain_root_id: &str,
        thread_id: &str,
        expected_status: &str,
    ) -> Result<Option<ThreadResultRecord>> {
        let snapshot = {
            let g = self.lock()?;
            g.state_db
                .read_authoritative_thread_snapshot(chain_root_id, thread_id)?
                .ok_or_else(|| anyhow!("thread is missing its signed snapshot"))?
        };
        if snapshot.chain_root_id != chain_root_id || snapshot.thread_id != thread_id {
            bail!("result snapshot contradicts the requested thread");
        }
        if snapshot.status.as_str() != expected_status {
            bail!("result snapshot changed after the caller's authorization");
        }
        if snapshot.result.is_none() && snapshot.error.is_none() && snapshot.outcome_code.is_none()
        {
            return Ok(None);
        }
        let record = ThreadResultRecord {
            outcome_code: snapshot.outcome_code,
            result: snapshot.result,
            error: snapshot.error,
            metadata: None,
        };
        if serde_json::to_vec(&record)?.len() > MAX_THREAD_RESULT_RESPONSE_BYTES {
            bail!("thread {thread_id} signed result exceeds its response byte maximum");
        }
        Ok(Some(record))
    }

    fn inspect_terminal_chain_pins<F>(
        g: &Inner,
        chain: &ryeos_state::AuthoritativeTerminalChain,
        pin_count: &F,
    ) -> Result<runtime_db::ChainRecoveryPins>
    where
        F: Fn(&[String]) -> Result<u64>,
    {
        let mut pins = g
            .runtime_db
            .inspect_chain_recovery_pins(&chain.chain_root_id, &chain.thread_ids)?;
        pins.candidate_evidence = g
            .runtime_db
            .candidate_evidence_pin_count(&chain.chain_root_id)?;
        let members = chain
            .thread_ids
            .iter()
            .map(String::as_str)
            .collect::<HashSet<_>>();
        for (parent_thread_id, child_thread_id) in
            g.runtime_db.chain_child_links(&chain.thread_ids)?
        {
            let parent_is_member = members.contains(parent_thread_id.as_str());
            let child_is_member = members.contains(child_thread_id.as_str());
            if parent_is_member && child_is_member {
                continue;
            }
            let counterpart = if parent_is_member {
                &child_thread_id
            } else {
                &parent_thread_id
            };
            // A missing counterpart while its operational edge remains is an
            // inconsistent read, not proof of safety. Fail closed by retaining
            // the chain. A terminal counterpart no longer needs cancellation
            // cascade state and therefore does not pin this history.
            if g.state_db
                .get_thread(counterpart)?
                .is_none_or(|thread| !is_terminal_status(&thread.status))
            {
                pins.child_links = pins
                    .child_links
                    .checked_add(1)
                    .ok_or_else(|| anyhow!("child-link recovery pin count overflow"))?;
            }
        }
        pins.scheduler_fires = pin_count(&chain.thread_ids)?;
        Ok(pins)
    }

    fn finish_terminal_chain_removal(
        &self,
        g: &StateStoreGuard<'_>,
        chain: &ryeos_state::AuthoritativeTerminalChain,
        chain_lock: &ChainLock,
        runtime_paths: &[ThreadRuntimeRemoval],
        head_already_absent: bool,
        result: &mut TerminalChainRetirement,
    ) -> Result<()> {
        let selected_permit = self.selected_mutation_permit(
            g,
            SelectedMutationOperation::DeleteChain(&chain.chain_root_id, &chain.thread_ids),
        )?;
        if !head_already_absent
            && !g
                .state_db
                .remove_chain_head_ref(&chain.chain_root_id, chain_lock)?
        {
            bail!(
                "authoritative chain head disappeared during retirement: {}",
                chain.chain_root_id
            );
        }
        result.deleted_runtime_rows += g.runtime_db.delete_chain_runtime(
            &selected_permit,
            &chain.chain_root_id,
            &chain.thread_ids,
        )?;
        self.refresh_attached_process_registry_locked(g)?;
        result.deleted_runtime_files += delete_thread_runtime_files(runtime_paths)?;
        result.deleted_projection_rows += g
            .state_db
            .delete_chain_projection(&chain.chain_root_id, chain_lock)?;
        if !g
            .state_db
            .acknowledge_chain_removal_cleanup(&chain.chain_root_id, chain_lock)?
        {
            bail!(
                "pending chain removal disappeared before acknowledgement: {}",
                chain.chain_root_id
            );
        }
        Ok(())
    }

    fn recover_pending_terminal_chain_removals_with<F>(
        &self,
        now: &str,
        dry_run: bool,
        pin_count: &F,
    ) -> Result<TerminalChainRetirement>
    where
        F: Fn(&[String]) -> Result<u64>,
    {
        let mut result = TerminalChainRetirement::default();
        let mut pending_removals = {
            let g = self.lock()?;
            g.state_db.pending_remove_cursor()?
        };
        while let Some(observed) = pending_removals.next_transition()? {
            let chain_root_id = observed.chain_root_id.clone();
            let _permit = self.acquire_recovery_cleanup_permit(dry_run)?;
            let g = self.lock()?;
            let chain_lock = if dry_run {
                g.state_db.acquire_existing_chain_lock(&chain_root_id)?
            } else {
                g.state_db.acquire_chain_lock(&chain_root_id)?
            };
            let still_pending = g
                .state_db
                .pending_chain_transition(&chain_root_id)?
                .is_some_and(|pending| {
                    pending.transition_id == observed.transition_id
                        && pending.operation == ryeos_state::HeadOperation::Remove
                });
            if !still_pending {
                continue;
            }
            // Includes HeadAbsent contradictions: retain SAME Remove and all
            // cleanup owners rather than cancel/repair/acknowledge through them.
            self.require_selected_bulk_exclusion(&g)?;

            match g.state_db.pending_chain_removal_head_state(
                &chain_root_id,
                &observed.transition_id,
                &chain_lock,
            )? {
                ryeos_state::PendingRemoveHeadState::HeadAbsent => {
                    let chain = g
                        .state_db
                        .pending_removed_terminal_chain_under_lock(&chain_root_id, &chain_lock)?
                        .ok_or_else(|| {
                            anyhow!(
                                "pending Remove for {chain_root_id} names a nonterminal or invalid closure"
                            )
                        })?;
                    // The absent trusted head proves that this Remove crossed
                    // its authoritative deletion boundary. Operational rows,
                    // scheduler fires, follow state, and runtime files left by
                    // a crash at that boundary are cleanup targets, not fresh
                    // vetoes: new pin admission is already forbidden once the
                    // Remove publishes. Rechecking them here would strand the
                    // exact partial cleanup this replay owns forever.
                    let runtime_paths = inspect_thread_runtime_files(
                        self.thread_runtime_authority()?,
                        &chain.thread_ids,
                    )?;
                    result.pending_retirements_recovered += 1;
                    if !dry_run {
                        self.finish_terminal_chain_removal(
                            &g,
                            &chain,
                            &chain_lock,
                            &runtime_paths,
                            true,
                            &mut result,
                        )?;
                    }
                    continue;
                }
                ryeos_state::PendingRemoveHeadState::AdvancedHeadVisible { current_head_hash } => {
                    result.pending_retirements_recovered += 1;
                    tracing::warn!(
                        chain_root_id,
                        current_head_hash,
                        "pending terminal-history Remove is stale against an advanced signed head; repairing the current head"
                    );
                    if dry_run {
                        g.state_db.verify_advanced_head_after_stale_chain_removal(
                            &chain_root_id,
                            &observed.transition_id,
                            &current_head_hash,
                            &chain_lock,
                        )?;
                    } else {
                        g.state_db.repair_advanced_head_after_stale_chain_removal(
                            &chain_root_id,
                            &observed.transition_id,
                            &chain_lock,
                        )?;
                    }
                    continue;
                }
                ryeos_state::PendingRemoveHeadState::ExpectedHeadVisible => {}
            }

            let Some(chain) = g
                .state_db
                .authoritative_terminal_chain_under_lock(&chain_root_id, &chain_lock)?
            else {
                result.pending_retirements_recovered += 1;
                if !dry_run {
                    g.state_db
                        .cancel_pending_chain_removal(&chain_root_id, &chain_lock)?;
                }
                continue;
            };
            let due = chain.is_due_at(now)?;
            let pins = Self::inspect_terminal_chain_pins(&g, &chain, pin_count)?;
            if !due || !pins.is_empty() {
                result.pending_retirements_recovered += 1;
                if !dry_run {
                    g.state_db
                        .cancel_pending_chain_removal(&chain_root_id, &chain_lock)?;
                }
                continue;
            }
            let runtime_paths =
                inspect_thread_runtime_files(self.thread_runtime_authority()?, &chain.thread_ids)?;
            result.pending_retirements_recovered += 1;
            result.retired_chains += 1;
            if !dry_run {
                self.finish_terminal_chain_removal(
                    &g,
                    &chain,
                    &chain_lock,
                    &runtime_paths,
                    false,
                    &mut result,
                )?;
            }
        }
        Ok(result)
    }

    /// Complete or cancel only the bounded durable Remove records left by an
    /// interrupted retention transaction. Startup calls this before readiness;
    /// it never scans current chain heads or selects new GC candidates.
    pub fn recover_pending_terminal_chain_removals<F>(
        &self,
        now: &str,
        dry_run: bool,
        pin_count: F,
    ) -> Result<TerminalChainRetirement>
    where
        F: Fn(&[String]) -> Result<u64>,
    {
        let result = self.recover_pending_terminal_chain_removals_with(now, dry_run, &pin_count);
        match self
            .lock()
            .and_then(|g| Ok(g.state_db.pending_chain_transitions()?.len()))
        {
            Ok(pending) => self.projection_health.observe_pending_transitions(pending),
            Err(error) => self
                .projection_health
                .observe_pending_transition_error(&error),
        }
        result
    }

    /// Retire terminal chain history solely from the signed policy captured on
    /// its root. Candidate rows are a bounded read-model optimization; every
    /// destructive decision is repeated from the trust-verified CAS closure
    /// under the global guard/permit/mutex/chain-lock hierarchy.
    pub fn retire_due_terminal_chains<F>(
        &self,
        now: &str,
        dry_run: bool,
        pin_count: F,
    ) -> Result<TerminalChainRetirement>
    where
        F: Fn(&[String]) -> Result<u64>,
    {
        const CANDIDATE_BATCH: usize = 128;
        let mut result =
            self.recover_pending_terminal_chain_removals_with(now, dry_run, &pin_count)?;
        let mut cursor: Option<ryeos_state::DueTerminalChainCursor> = None;
        loop {
            let candidates = {
                let g = self.lock()?;
                self.require_selected_bulk_exclusion(&g)?;
                g.state_db
                    .list_due_terminal_chains(now, CANDIDATE_BATCH, cursor.as_ref())?
            };
            if candidates.is_empty() {
                break;
            }
            result.candidate_chains += candidates.len();
            cursor = candidates
                .last()
                .map(|candidate| ryeos_state::DueTerminalChainCursor {
                    retire_after: candidate.retire_after,
                    chain_root_id: candidate.chain_root_id.clone(),
                });

            for candidate in &candidates {
                let _permit = if dry_run {
                    self.acquire_gc_inspection_permit()?
                } else {
                    self.acquire_write_permit()?
                };
                let g = self.lock()?;
                self.require_selected_bulk_exclusion(&g)?;
                let chain_lock = if dry_run {
                    g.state_db
                        .acquire_existing_chain_lock(&candidate.chain_root_id)?
                } else {
                    g.state_db.acquire_chain_lock(&candidate.chain_root_id)?
                };
                // Any unresolved transition owns the chain's publication
                // slot. In particular, a Prepared Set may still name a newer
                // closure even while the old head/projection match this stale
                // candidate row; retirement must never try to converge or
                // overwrite that publication intent.
                if g.state_db
                    .pending_chain_transition(&candidate.chain_root_id)?
                    .is_some()
                {
                    continue;
                }
                if let Some(fenced) = self.fenced_chain_kinds.get() {
                    let root = g
                        .state_db
                        .get_thread(&candidate.chain_root_id)?
                        .ok_or_else(|| {
                            anyhow!(
                                "due chain {} has no root thread row",
                                candidate.chain_root_id
                            )
                        })?;
                    if fenced.contains(&root.kind) {
                        continue;
                    }
                }
                let Some(chain) = g.state_db.authoritative_terminal_chain_under_lock(
                    &candidate.chain_root_id,
                    &chain_lock,
                )?
                else {
                    continue;
                };
                if chain.head_hash != candidate.indexed_chain_state_hash
                    || chain.terminal_at != candidate.terminal_at
                    || !chain.is_due_at(now)?
                {
                    continue;
                }
                let pins = Self::inspect_terminal_chain_pins(&g, &chain, &pin_count)?;
                if !pins.is_empty() {
                    continue;
                }
                let runtime_paths = inspect_thread_runtime_files(
                    self.thread_runtime_authority()?,
                    &chain.thread_ids,
                )?;
                result.retired_chains += 1;
                if !dry_run {
                    self.finish_terminal_chain_removal(
                        &g,
                        &chain,
                        &chain_lock,
                        &runtime_paths,
                        false,
                        &mut result,
                    )?;
                }
            }
            if candidates.len() < CANDIDATE_BATCH {
                break;
            }
        }
        Ok(result)
    }

    /// Install the kinds that retire through a fence. Once per Store: the
    /// same set again is accepted, a different one is refused.
    pub fn install_fenced_chain_kinds(&self, kinds: &ryeos_state::FencedChainKinds) -> Result<()> {
        let installed = self.fenced_chain_kinds.get_or_init(|| kinds.clone());
        anyhow::ensure!(
            installed == kinds,
            "fenced chain kinds were already installed with a different set"
        );
        Ok(())
    }

    /// One bounded keyset slice of fenced-kind chains whose retention has
    /// elapsed. A scheduling hint only: `retire_fenced_chain` requalifies.
    pub fn due_fenced_chain_retirement_slice(
        &self,
        now: &str,
        after: Option<&str>,
        limit: usize,
    ) -> Result<Vec<String>> {
        let kinds = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let g = self.lock()?;
        self.require_selected_bulk_exclusion(&g)?;
        g.state_db
            .projection()
            .due_fenced_chain_retirement_slice(kinds, now, after, limit)
    }

    /// Finish the head half of every interrupted fenced retirement: a fence
    /// whose chain still has a head gets its Remove prepared and the head
    /// unlinked. The caller holds the exclusive retention exclusion.
    pub fn replay_fenced_chain_retirements(
        &self,
    ) -> Result<ryeos_state::state_db::FencedRetirementReplay> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        self.require_selected_bulk_exclusion(&g)?;
        g.state_db
            .replay_fenced_chain_retirements(permit.cas_guard())
    }

    /// Retire one fenced-kind chain to a retained closure, or finish an
    /// interrupted retirement of it. The caller decides which counterparts and
    /// evidence events the closure keeps; State derives every coordinate, and
    /// the composition's installed validator judges each retained event. The
    /// caller holds the retention exclusion whose pin count it passes.
    pub fn retire_fenced_chain<F>(
        &self,
        chain_root_id: &str,
        now: &str,
        plan: &FencedChainRetirementPlan,
        pin_count: F,
    ) -> Result<TerminalChainRetirement>
    where
        F: Fn(&[String]) -> Result<u64>,
    {
        let kinds = self
            .fenced_chain_kinds
            .get()
            .ok_or_else(|| anyhow!("fenced chain kinds are not installed"))?;
        let validator = crate::object_contracts::retained_evidence_validator()?;
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        self.require_selected_bulk_exclusion(&g)?;
        let root = g
            .state_db
            .get_thread(chain_root_id)?
            .ok_or_else(|| anyhow!("chain {chain_root_id} has no root thread row"))?;
        anyhow::ensure!(
            kinds.contains(&root.kind),
            "chain {chain_root_id} is not of a fenced kind"
        );
        // Owner and evidence counterparts are locked together in sorted
        // order, the one order every multi-chain path uses.
        let mut lock_ids: BTreeSet<&str> = plan
            .evidence
            .iter()
            .map(|reference| reference.counterpart_root.as_str())
            .collect();
        anyhow::ensure!(
            !lock_ids.contains(chain_root_id),
            "a retired chain cannot be its own counterpart"
        );
        lock_ids.insert(chain_root_id);
        let mut owner_lock = None;
        let mut counterpart_locks = Vec::new();
        for id in lock_ids {
            let lock = g.state_db.acquire_chain_lock(id)?;
            if id == chain_root_id {
                owner_lock = Some(lock);
            } else {
                counterpart_locks.push(lock);
            }
        }
        let owner_lock = owner_lock.ok_or_else(|| anyhow!("owner chain lock was not acquired"))?;
        let counterpart_refs: Vec<&ChainLock> = counterpart_locks.iter().collect();
        let chain = match g
            .state_db
            .authoritative_terminal_chain_under_lock(chain_root_id, &owner_lock)?
        {
            Some(chain) => {
                anyhow::ensure!(
                    chain.is_due_at(now)?,
                    "chain {chain_root_id} is not due for retirement"
                );
                let pins = Self::inspect_terminal_chain_pins(&g, &chain, &pin_count)?;
                anyhow::ensure!(
                    pins.is_empty(),
                    "chain {chain_root_id} is still pinned: {pins:?}"
                );
                chain
            }
            None => g
                .state_db
                .pending_removed_terminal_chain_under_lock(chain_root_id, &owner_lock)?
                .ok_or_else(|| {
                    anyhow!("chain {chain_root_id} is neither live nor a pending Remove")
                })?,
        };
        let runtime_paths =
            inspect_thread_runtime_files(self.thread_runtime_authority()?, &chain.thread_ids)?;
        let deleted_rows = std::cell::Cell::new(0usize);
        let deleted_files = std::cell::Cell::new(0usize);
        let cleanup = || -> Result<()> {
            let selected_permit = self.selected_mutation_permit(
                &g,
                SelectedMutationOperation::DeleteChain(&chain.chain_root_id, &chain.thread_ids),
            )?;
            deleted_rows.set(
                deleted_rows.get()
                    + g.runtime_db.delete_chain_runtime(
                        &selected_permit,
                        &chain.chain_root_id,
                        &chain.thread_ids,
                    )?,
            );
            self.refresh_attached_process_registry_locked(&g)?;
            deleted_files.set(deleted_files.get() + delete_thread_runtime_files(&runtime_paths)?);
            Ok(())
        };
        let report = g.state_db.retire_chain(
            chain_root_id,
            &owner_lock,
            permit.cas_guard(),
            ryeos_state::state_db::ChainRetirement {
                counterpart_roots: plan.counterpart_roots.clone(),
                evidence: plan.evidence.clone(),
                counterpart_locks: &counterpart_refs,
                validator: &validator,
                runtime_cleanup: &cleanup,
            },
        )?;
        tracing::info!(
            chain_root_id,
            manifest_hash = report.manifest_hash,
            stored_manifest = report.stored_manifest,
            "fenced chain retired"
        );
        Ok(TerminalChainRetirement {
            candidate_chains: 1,
            retired_chains: 1,
            deleted_projection_rows: 0,
            deleted_runtime_rows: deleted_rows.get(),
            deleted_runtime_files: deleted_files.get(),
            pending_retirements_recovered: usize::from(!report.stored_manifest),
        })
    }

    pub fn get_thread_result(&self, thread_id: &str) -> Result<Option<ThreadResultRecord>> {
        let result_row = {
            let g = self.lock()?;
            queries::get_thread_result(g.state_db.projection(), thread_id)?
        };
        let Some(row) = result_row else {
            return Ok(None);
        };
        // JSON parsing and exact response serialization happen after releasing
        // the global store mutex. The query has already bounded both source
        // columns before allocating them.
        let result = match row.result {
            Some(bytes) => Some(serde_json::from_slice::<Value>(&bytes).with_context(|| {
                format!(
                    "malformed JSON in thread_results.result for thread_id {}",
                    thread_id
                )
            })?),
            None => None,
        };
        let record = ThreadResultRecord {
            outcome_code: row.outcome_code,
            result,
            error: row
                .error
                .map(|error| {
                    serde_json::from_str::<Value>(&error).with_context(|| {
                        format!(
                            "malformed JSON in thread_results.error for thread_id {}",
                            thread_id
                        )
                    })
                })
                .transpose()?,
            metadata: None,
        };
        let response_bytes = serde_json::to_vec(&record)?.len();
        if response_bytes > MAX_THREAD_RESULT_RESPONSE_BYTES {
            bail!(
                "thread {thread_id} result response is {response_bytes} bytes; maximum is {MAX_THREAD_RESULT_RESPONSE_BYTES}"
            );
        }
        Ok(Some(record))
    }

    pub fn get_thread_terminal_authority(
        &self,
        thread_id: &str,
    ) -> Result<Option<ThreadTerminalAuthority>> {
        let g = self.lock()?;
        let Some(thread) = g.state_db.get_thread(thread_id)? else {
            return Ok(None);
        };
        let Some(status) = ThreadStatus::from_str_lossy(&thread.status) else {
            bail!("thread {thread_id} has unknown status `{}`", thread.status);
        };
        if !status.is_terminal() {
            return Ok(None);
        }

        let snapshot = g
            .state_db
            .read_authoritative_thread_snapshot(&thread.chain_root_id, thread_id)?
            .ok_or_else(|| anyhow!("terminal thread {thread_id} is missing its CAS snapshot"))?;
        let ThreadSnapshot {
            status: snapshot_status,
            result,
            error,
            budget,
            managed_runtime_terminal,
            facets,
            ..
        } = snapshot;
        if snapshot_status != status {
            bail!(
                "terminal thread {thread_id} projection status `{status}` contradicts CAS status `{}`",
                snapshot_status
            );
        }

        let final_cost = budget
            .map(|usage| {
                let metadata = facets
                    .get("cost.metadata_json")
                    .map(|raw| serde_json::from_str(raw))
                    .transpose()
                    .context("decode authoritative final cost metadata")?;
                Ok::<_, anyhow::Error>(ryeos_engine::contracts::FinalCost {
                    turns: usage.completed_turns,
                    input_tokens: usage.input_tokens,
                    output_tokens: usage.output_tokens,
                    spend: usage.spend_usd,
                    provider: facets.get("cost.provider").cloned(),
                    basis: facets.get("cost.basis").cloned(),
                    metadata,
                })
            })
            .transpose()?;
        let managed_envelope = managed_runtime_terminal
            .map(|supplement| {
                managed_terminal_envelope_from_supplement(
                    thread_id,
                    status,
                    result.as_ref(),
                    error.as_ref(),
                    final_cost.as_ref(),
                    supplement,
                )
            })
            .transpose()?;

        Ok(Some(ThreadTerminalAuthority {
            status,
            result,
            error,
            final_cost,
            managed_envelope,
        }))
    }

    pub fn list_thread_artifacts(&self, thread_id: &str) -> Result<Vec<ThreadArtifactRecord>> {
        let artifact_rows = {
            let g = self.lock()?;
            // Aggregate/count-only preflight happens before the guarded SELECT,
            // so no collection BLOB is copied until the whole collection fits.
            ensure_artifact_projection_capacity(&g, thread_id, 0, 0, 0)?;
            queries::list_thread_artifacts_bounded(
                g.state_db.projection(),
                thread_id,
                MAX_THREAD_ARTIFACT_ITEMS,
                MAX_THREAD_ARTIFACT_TYPE_BYTES,
                MAX_THREAD_ARTIFACT_METADATA_BYTES,
                MAX_THREAD_ARTIFACT_METADATA_TOTAL_BYTES,
            )?
        };
        let mut records = Vec::with_capacity(artifact_rows.len());
        let mut response_bytes = b"[]".len();
        for (idx, row) in artifact_rows.into_iter().enumerate() {
            let metadata = match row.metadata {
                Some(bytes) => {
                    Some(serde_json::from_slice::<Value>(&bytes).with_context(|| {
                        format!(
                            "malformed JSON in thread_artifacts.metadata \
                             for artifact at index {idx} of thread_id {}",
                            thread_id
                        )
                    })?)
                }
                None => None,
            };
            let record = ThreadArtifactRecord {
                artifact_id: idx as i64 + 1,
                artifact_type: row.kind,
                uri: String::new(),
                content_hash: None,
                metadata,
            };
            let encoded = serde_json::to_vec(&record)?;
            response_bytes = response_bytes
                .checked_add(encoded.len())
                .and_then(|bytes| bytes.checked_add(usize::from(!records.is_empty())))
                .ok_or_else(|| anyhow!("thread artifact response size overflow"))?;
            if response_bytes > MAX_THREAD_ARTIFACT_RESPONSE_BYTES {
                bail!(
                    "thread {thread_id} artifact response exceeds the {MAX_THREAD_ARTIFACT_RESPONSE_BYTES}-byte maximum"
                );
            }
            records.push(record);
        }
        Ok(records)
    }

    #[tracing::instrument(
        name = "state:publish_state_anchor",
        skip(self, params),
        fields(thread_id = %params.thread_id, contract = %params.contract)
    )]
    pub fn publish_state_anchor(
        &self,
        params: &StateAnchorPublishParams,
    ) -> Result<StateAnchorPublication> {
        validate_state_anchor_request(params)?;

        let restore_bytes = lillux::canonical_json(&params.restore)
            .context("canonicalize state restore contract")?
            .into_bytes();
        if restore_bytes.len() > MAX_STATE_RESTORE_BYTES {
            bail!(
                "state restore contract is {} bytes; maximum is {MAX_STATE_RESTORE_BYTES}",
                restore_bytes.len()
            );
        }
        let restore_hash = lillux::sha256_hex(&restore_bytes);
        require_prefixed_digest("restore_digest", &params.restore_digest, &restore_hash)?;

        let mut decoded_objects = Vec::with_capacity(params.objects.len());
        let mut total_input_bytes = 0usize;
        for input in &params.objects {
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(&input.content_base64)
                .with_context(|| format!("decode state manifest object {:?}", input.name))?;
            if bytes.len() > MAX_STATE_MANIFEST_INPUT_BYTES {
                bail!(
                    "state manifest object {:?} is {} bytes; maximum is {MAX_STATE_MANIFEST_INPUT_BYTES}",
                    input.name,
                    bytes.len()
                );
            }
            total_input_bytes = total_input_bytes
                .checked_add(bytes.len())
                .ok_or_else(|| anyhow!("state manifest input byte total overflow"))?;
            if total_input_bytes > MAX_STATE_MANIFEST_TOTAL_INPUT_BYTES {
                bail!(
                    "state manifest inputs total {total_input_bytes} bytes; maximum is {MAX_STATE_MANIFEST_TOTAL_INPUT_BYTES}"
                );
            }
            let hash = lillux::sha256_hex(&bytes);
            require_prefixed_digest("state manifest object digest", &input.digest, &hash)?;
            decoded_objects.push((input, bytes, hash));
        }

        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread = g
            .state_db
            .get_thread(&params.thread_id)?
            .ok_or_else(|| anyhow!("state-anchor thread not found: {}", params.thread_id))?;
        if thread.status != ThreadStatus::Running.as_str() {
            bail!(
                "state-anchor publication requires a running thread; {} is '{}'",
                params.thread_id,
                thread.status
            );
        }
        let runtime = g
            .runtime_db
            .get_runtime_info(&params.thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing while publishing state anchor"))?;
        if runtime.stop_intent.is_some()
            || !self
                .process_attachment_admission_open
                .load(Ordering::Acquire)
        {
            bail!(
                "state-anchor publication is closed for thread {}",
                params.thread_id
            );
        }
        match &params.subject {
            ryeos_state::objects::StateAnchorSubject::Graph { .. } => {}
            ryeos_state::objects::StateAnchorSubject::Execution {
                chain_root_id,
                placement_thread_id,
                item_ref,
                exact_program_hash,
                launch_capsule_hash,
                source_chain_seq,
                source_event_hash,
            } => {
                if chain_root_id != &thread.chain_root_id
                    || placement_thread_id != &params.thread_id
                    || item_ref != &thread.item_ref
                    || thread.admitted_launch_capsule_hash.as_deref()
                        != Some(launch_capsule_hash.as_str())
                {
                    bail!("state-anchor execution subject contradicts its authoritative thread");
                }
                let capsule = load_admitted_launch_capsule(
                    &self.state_authority,
                    &self.bundle_admission_trust,
                    launch_capsule_hash,
                )?;
                if &capsule.exact_program_hash != exact_program_hash {
                    bail!("state-anchor execution subject contradicts its admitted program");
                }
                let authoritative = g
                    .state_db
                    .read_authoritative_thread_snapshot_with_last_event(
                        &thread.chain_root_id,
                        &params.thread_id,
                    )?
                    .ok_or_else(|| anyhow!("state-anchor authoritative thread is missing"))?;
                let (observed_hash, observed_event) = authoritative
                    .last_event
                    .ok_or_else(|| anyhow!("execution state anchor requires a source event"))?;
                if observed_event.thread_id != params.thread_id
                    || observed_event.chain_seq != *source_chain_seq
                    || observed_hash != *source_event_hash
                {
                    bail!("state-anchor execution checkpoint position is no longer current");
                }
            }
        }
        if !self.projection_health.is_current() {
            bail!("state-anchor admission requires a current thread projection");
        }

        self.state_authority.ensure_guard(permit.cas_guard())?;
        let cas = self.state_authority.cas_store()?;
        let stored_restore = cas.put_blob(&restore_bytes)?;
        if stored_restore.hash != restore_hash {
            bail!(
                "state restore CAS hash mismatch: expected {restore_hash}, stored {}",
                stored_restore.hash
            );
        }
        let restore = StateManifestBlob {
            name: "restore".to_string(),
            media_type: "application/json".to_string(),
            blob_hash: restore_hash,
            size_bytes: u64::try_from(restore_bytes.len())
                .context("state restore byte length exceeds u64")?,
        };
        let mut objects = Vec::with_capacity(decoded_objects.len());
        for (input, bytes, expected_hash) in decoded_objects {
            let stored = cas.put_blob(&bytes)?;
            if stored.hash != expected_hash {
                bail!(
                    "state manifest object {:?} CAS hash mismatch: expected {expected_hash}, stored {}",
                    input.name,
                    stored.hash
                );
            }
            objects.push(StateManifestBlob {
                name: input.name.clone(),
                media_type: input.media_type.clone(),
                blob_hash: expected_hash,
                size_bytes: u64::try_from(bytes.len())
                    .context("state manifest object byte length exceeds u64")?,
            });
        }
        let manifest = StateManifest::new(
            params.contract.clone(),
            thread.chain_root_id.clone(),
            params.thread_id.clone(),
            restore,
            objects,
        )?;
        let manifest_hash = cas
            .store_object(&manifest.to_value())
            .context("store canonical state manifest")?;
        let state_digest = format!("sha256:{manifest_hash}");
        let manifest_ref = format!("cas:{manifest_hash}");
        let event_payload = ryeos_state::objects::StateAnchorMilestone {
            kind: "state_anchor".to_string(),
            payload: ryeos_state::objects::StateAnchorPayload {
                schema_version: ryeos_state::objects::STATE_ANCHOR_SCHEMA_VERSION,
                label: params.anchor.label.clone(),
                state_digest: state_digest.clone(),
                manifest_ref: manifest_ref.clone(),
                runtime: params.anchor.runtime.clone(),
                metadata: params.anchor.metadata.clone(),
            },
            subject: params.subject.clone(),
        }
        .to_value()
        .context("encode current state-anchor milestone")?;
        let event = NewEventRecord {
            event_type: ryeos_state::event_types::MILESTONE.to_string(),
            storage_class: "indexed".to_string(),
            payload: event_payload,
        };
        let persisted = append_events_locked(
            &g,
            Some(permit.cas_guard()),
            &thread.chain_root_id,
            &params.thread_id,
            std::slice::from_ref(&event),
        )?;
        let event = persisted
            .into_iter()
            .next()
            .ok_or_else(|| anyhow!("state-anchor milestone was not persisted"))?;
        Ok(StateAnchorPublication {
            state_digest,
            manifest_ref,
            event,
        })
    }

    /// Append or exactly fold one source-scoped project observation. The
    /// rebuildable projection is the idempotency index, so the identity lives
    /// for exactly as long as its chain evidence.
    pub fn publish_project_observation(
        &self,
        params: &ryeos_runtime::ProjectObservationPublishParams,
        source_definition_ref: &str,
        source_effective_definition_digest: &str,
    ) -> Result<ProjectObservationPublication> {
        params.observation.validate()?;
        let occurrence = ryeos_state::ProjectObservationOccurrence {
            graph_run_id: params.graph_run_id.clone(),
            node: params.node.clone(),
            step: params.step,
        };
        occurrence.validate()?;
        let payload_canonical = lillux::canonical_json(&params.observation.payload)
            .context("canonicalize project observation payload")?;
        let payload_fingerprint = lillux::sha256_hex(payload_canonical.as_bytes());

        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread = g
            .state_db
            .get_thread(&params.thread_id)?
            .ok_or_else(|| anyhow!("project-observation thread not found: {}", params.thread_id))?;
        if thread.status != ThreadStatus::Running.as_str() {
            bail!(
                "project-observation publication requires a running thread; {} is '{}'",
                params.thread_id,
                thread.status
            );
        }
        let runtime = g
            .runtime_db
            .get_runtime_info(&params.thread_id)?
            .ok_or_else(|| anyhow!("runtime row missing while publishing project observation"))?;
        if runtime.stop_intent.is_some()
            || !self
                .process_attachment_admission_open
                .load(Ordering::Acquire)
        {
            bail!(
                "project-observation publication is closed for thread {}",
                params.thread_id
            );
        }
        if !self.projection_health.is_current() {
            bail!("project-observation admission requires a current thread projection");
        }

        let observation_id = ryeos_state::project_observation_id(
            &thread.chain_root_id,
            source_definition_ref,
            source_effective_definition_digest,
            &params.observation.namespace,
            &params.observation.stable_id,
        )?;
        let payload = ryeos_state::ProjectObservationRecordedPayload {
            schema_version: ryeos_state::PROJECT_OBSERVATION_SCHEMA.to_string(),
            observation_id: observation_id.clone(),
            namespace: params.observation.namespace.clone(),
            stable_id: params.observation.stable_id.clone(),
            source_definition_ref: source_definition_ref.to_string(),
            source_effective_definition_digest: source_effective_definition_digest.to_string(),
            occurrence,
            payload_fingerprint,
            payload: params.observation.payload.clone(),
        };
        payload.validate_for_chain(&thread.chain_root_id)?;
        let event_payload = serde_json::to_value(&payload)?;

        if let Some(existing) = ryeos_state::queries::get_project_observation_identity(
            g.state_db.projection(),
            &observation_id,
        )? {
            if existing.chain_root_id != thread.chain_root_id
                || existing.source_definition_ref != source_definition_ref
                || existing.source_effective_definition_digest != source_effective_definition_digest
                || existing.namespace != params.observation.namespace
                || existing.stable_id != params.observation.stable_id
                || existing.payload_fingerprint != payload.payload_fingerprint
            {
                bail!(
                    "project observation {} contradicts its durable identity",
                    observation_id
                );
            }
            let row = ryeos_state::queries::get_event_by_hash(
                g.state_db.projection(),
                &existing.event_hash,
            )?
            .ok_or_else(|| {
                anyhow!(
                    "project observation {} references missing projected event {}",
                    observation_id,
                    existing.event_hash
                )
            })?;
            let event = persisted_event_from_projection_row(row)?;
            if event.event_type != ryeos_state::event_types::PROJECT_OBSERVATION_RECORDED
                || event.payload != event_payload
            {
                bail!(
                    "project observation {} has divergent durable event content",
                    observation_id
                );
            }
            return Ok(ProjectObservationPublication {
                event,
                inserted: false,
            });
        }

        let event = NewEventRecord {
            event_type: ryeos_state::event_types::PROJECT_OBSERVATION_RECORDED.to_string(),
            storage_class: "indexed".to_string(),
            payload: event_payload,
        };
        let mut persisted = append_events_locked(
            &g,
            Some(permit.cas_guard()),
            &thread.chain_root_id,
            &params.thread_id,
            std::slice::from_ref(&event),
        )?;
        let event = persisted
            .pop()
            .ok_or_else(|| anyhow!("project observation append returned no event"))?;
        Ok(ProjectObservationPublication {
            event,
            inserted: true,
        })
    }

    /// Append or exactly fold a daemon-authored provider publication/replay
    /// observation after the provider record has crossed its proof boundary.
    pub fn publish_provider_call_observation(
        &self,
        thread_id: &str,
        draft: &ryeos_state::ProviderCallObservationDraft,
    ) -> Result<ProviderCallObservationPublication> {
        draft.validate()?;
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("provider-call observation thread not found: {thread_id}"))?;
        if thread.status != ThreadStatus::Running.as_str() {
            bail!(
                "provider-call observation requires a running thread; {thread_id} is '{}'",
                thread.status
            );
        }
        // This event completes evidence for an already-issued provider effect.
        // The callback admission layer therefore classifies it with settlement
        // as a stop-completion mutation. Re-applying the ordinary authoring
        // gate here would make cancellation after contact strand a financially
        // terminal call without its provider observation.
        if !self.projection_health.is_current() {
            bail!("provider-call observation requires a current thread projection");
        }

        let observation_id = ryeos_state::provider_call_observation_id(
            &thread.chain_root_id,
            thread_id,
            draft.turn,
            draft.attempt_number,
            &draft.effect_coordinate_digest,
            draft.source,
            &draft.answer_digest,
            &draft.record_hash,
            draft.publication,
            draft.replayed_from.as_ref(),
        )?;
        let payload = ryeos_state::ProviderCallObservationRecordedPayload {
            schema_version: ryeos_state::PROVIDER_CALL_OBSERVATION_SCHEMA.to_string(),
            observation_id: observation_id.clone(),
            turn: draft.turn,
            attempt_number: draft.attempt_number,
            effect_coordinate_digest: draft.effect_coordinate_digest.clone(),
            source: draft.source,
            answer_digest: draft.answer_digest.clone(),
            record_hash: draft.record_hash.clone(),
            publication: draft.publication,
            replayed_from: draft.replayed_from.clone(),
        };
        payload.validate_for_subject(&thread.chain_root_id, thread_id)?;
        let event_payload = serde_json::to_value(&payload)?;
        let source = serde_json::to_value(payload.source)?
            .as_str()
            .expect("provider source serializes as a string")
            .to_string();
        let publication = serde_json::to_value(payload.publication)?
            .as_str()
            .expect("provider publication serializes as a string")
            .to_string();

        if let Some(existing) = ryeos_state::queries::get_provider_call_observation_identity(
            g.state_db.projection(),
            &observation_id,
        )? {
            if existing.chain_root_id != thread.chain_root_id
                || existing.thread_id != thread_id
                || existing.turn != draft.turn
                || existing.attempt_number != draft.attempt_number
                || existing.effect_coordinate_digest != draft.effect_coordinate_digest
                || existing.source != source
                || existing.answer_digest != draft.answer_digest
                || existing.record_hash != draft.record_hash
                || existing.publication != publication
            {
                bail!(
                    "provider-call observation {observation_id} contradicts its durable identity"
                );
            }
            let row = ryeos_state::queries::get_event_by_hash(
                g.state_db.projection(),
                &existing.event_hash,
            )?
            .ok_or_else(|| {
                anyhow!(
                    "provider-call observation {observation_id} references missing event {}",
                    existing.event_hash
                )
            })?;
            let event = persisted_event_from_projection_row(row)?;
            if event.event_type != ryeos_state::event_types::PROVIDER_CALL_OBSERVATION_RECORDED
                || event.payload != event_payload
            {
                bail!(
                    "provider-call observation {observation_id} has divergent durable event content"
                );
            }
            return Ok(ProviderCallObservationPublication {
                event,
                inserted: false,
            });
        }

        let event = NewEventRecord {
            event_type: ryeos_state::event_types::PROVIDER_CALL_OBSERVATION_RECORDED.to_string(),
            storage_class: "indexed".to_string(),
            payload: event_payload,
        };
        let mut persisted = append_events_locked(
            &g,
            Some(permit.cas_guard()),
            &thread.chain_root_id,
            thread_id,
            std::slice::from_ref(&event),
        )?;
        let event = persisted
            .pop()
            .ok_or_else(|| anyhow!("provider-call observation append returned no event"))?;
        Ok(ProviderCallObservationPublication {
            event,
            inserted: true,
        })
    }

    #[tracing::instrument(
        name = "state:publish_artifact",
        skip(self, artifact),
        fields(thread_id = %thread_id, artifact_type = %artifact.artifact_type)
    )]
    pub fn publish_artifact(
        &self,
        thread_id: &str,
        artifact: &NewArtifactRecord,
    ) -> Result<(ThreadArtifactRecord, PersistedEventRecord)> {
        let permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let thread_row = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;

        // Artifact projection is derived from the artifact_published event
        // during project_event (see projection.rs). No direct write needed.

        let event = NewEventRecord {
            event_type: "artifact_published".to_string(),
            storage_class: "indexed".to_string(),
            payload: json!({
                "artifact_type": artifact.artifact_type,
                "uri": artifact.uri,
                "content_hash": artifact.content_hash,
                "metadata": artifact.metadata,
            }),
        };
        if !self.projection_health.is_current() {
            bail!("artifact admission requires a current thread projection");
        }
        validate_artifact_event_admission(&g, thread_id, std::slice::from_ref(&event))?;

        let te = convert_events(
            std::slice::from_ref(&event),
            &thread_row.chain_root_id,
            thread_id,
        );
        let result = committed_value(g.state_db.append_events_admitted(
            &thread_row.chain_root_id,
            thread_id,
            te,
            vec![],
            g.signer.as_ref(),
            &g.runtime_db,
            permit.cas_guard(),
        )?);

        let persisted = persisted_from_append(&result, &[event])?;

        let persisted_event = persisted.into_iter().next().ok_or_else(|| {
            anyhow!("artifact_published event was not persisted for thread {thread_id}")
        })?;

        let artifact_id = persisted_event.event_id;

        let record = ThreadArtifactRecord {
            artifact_id,
            artifact_type: artifact.artifact_type.clone(),
            uri: artifact.uri.clone(),
            content_hash: artifact.content_hash.clone(),
            metadata: artifact.metadata.clone(),
        };

        Ok((record, persisted_event))
    }

