    pub fn list_thread_children(&self, thread_id: &str) -> Result<Vec<ThreadDetail>> {
        let g = self.lock()?;
        let child_rows = queries::list_thread_children(g.state_db.projection(), thread_id)?;
        let mut children = Vec::new();
        for row in child_rows {
            let runtime = g
                .runtime_db
                .get_runtime_info(&row.thread_id)?
                .unwrap_or_default();
            let successor_thread_id = if is_terminal_status(&row.status) {
                queries::continuation_successor(g.state_db.projection(), &row.thread_id)?
            } else {
                None
            };
            children.push(ThreadDetail {
                // Display projection, like the other list fields. Exact get
                // and retained-result import perform immutable verification.
                result_project_snapshot_hash: row.result_project_snapshot_hash,
                result_workspace_output_capture_hash: row.result_workspace_output_capture_hash,
                thread_id: row.thread_id,
                chain_root_id: row.chain_root_id,
                kind: row.kind,
                status: row.status,
                item_ref: row.item_ref,
                executor_ref: row.executor_ref,
                launch_mode: row.launch_mode,
                current_site_id: row.current_site_id,
                origin_site_id: row.origin_site_id,
                upstream_thread_id: row.upstream_thread_id,
                successor_thread_id,
                requested_by: row.requested_by,
                project_root: row.project_root,
                project_authority: Some(row.project_authority),
                lifecycle_authority: runtime
                    .launch_metadata
                    .as_ref()
                    .map(|metadata| metadata.lifecycle_authority())
                    .transpose()?
                    .flatten(),
                admitted_launch_capsule_hash: row.admitted_launch_capsule_hash,
                created_at: row.created_at,
                updated_at: row.updated_at,
                started_at: row.started_at,
                finished_at: row.finished_at,

                runtime,
            });
        }
        Ok(children)
    }

    pub fn list_chain_threads(&self, chain_root_id: &str) -> Result<Vec<ThreadDetail>> {
        let g = self.lock()?;
        let thread_rows = queries::list_threads_by_chain(g.state_db.projection(), chain_root_id)?;
        let mut threads = Vec::new();
        for row in thread_rows {
            let runtime = g
                .runtime_db
                .get_runtime_info(&row.thread_id)?
                .unwrap_or_default();
            let successor_thread_id = if is_terminal_status(&row.status) {
                queries::continuation_successor(g.state_db.projection(), &row.thread_id)?
            } else {
                None
            };
            threads.push(ThreadDetail {
                // Do not reread/revalidate the complete chain head per row.
                // List data is not retained-result import authority.
                result_project_snapshot_hash: row.result_project_snapshot_hash,
                result_workspace_output_capture_hash: row.result_workspace_output_capture_hash,
                thread_id: row.thread_id,
                chain_root_id: row.chain_root_id,
                kind: row.kind,
                status: row.status,
                item_ref: row.item_ref,
                executor_ref: row.executor_ref,
                launch_mode: row.launch_mode,
                current_site_id: row.current_site_id,
                origin_site_id: row.origin_site_id,
                upstream_thread_id: row.upstream_thread_id,
                successor_thread_id,
                requested_by: row.requested_by,
                project_root: row.project_root,
                project_authority: Some(row.project_authority),
                lifecycle_authority: runtime
                    .launch_metadata
                    .as_ref()
                    .map(|metadata| metadata.lifecycle_authority())
                    .transpose()?
                    .flatten(),
                admitted_launch_capsule_hash: row.admitted_launch_capsule_hash,
                created_at: row.created_at,
                updated_at: row.updated_at,
                started_at: row.started_at,
                finished_at: row.finished_at,

                runtime,
            });
        }
        Ok(threads)
    }

    pub fn list_chain_edges(&self, chain_root_id: &str) -> Result<Vec<ThreadEdgeRecord>> {
        let g = self.lock()?;
        let edge_rows = queries::list_thread_edges(g.state_db.projection(), chain_root_id)?;
        Ok(edge_rows
            .into_iter()
            .enumerate()
            .map(|(idx, row)| ThreadEdgeRecord {
                edge_id: idx as i64 + 1,
                chain_root_id: row.chain_root_id,
                source_thread_id: row.parent_thread_id,
                target_thread_id: row.child_thread_id,
                edge_type: "spawned".to_string(),
                created_at: String::new(),
                metadata: row.spawn_reason.map(|r| json!(r)),
            })
            .collect())
    }

    pub fn list_threads_by_status(&self, statuses: &[&str]) -> Result<Vec<ThreadDetail>> {
        let g = self.lock()?;
        let thread_rows = queries::list_threads_by_status(g.state_db.projection(), statuses)?;
        let mut details = Vec::new();
        for row in thread_rows {
            let runtime = g
                .runtime_db
                .get_runtime_info(&row.thread_id)?
                .unwrap_or_default();
            let successor_thread_id = if is_terminal_status(&row.status) {
                queries::continuation_successor(g.state_db.projection(), &row.thread_id)?
            } else {
                None
            };
            details.push(ThreadDetail {
                // Reconciliation enumerates projected rows; exact authority
                // remains with the operation that consumes the coordinate.
                result_project_snapshot_hash: row.result_project_snapshot_hash,
                result_workspace_output_capture_hash: row.result_workspace_output_capture_hash,
                thread_id: row.thread_id,
                chain_root_id: row.chain_root_id,
                kind: row.kind,
                status: row.status,
                item_ref: row.item_ref,
                executor_ref: row.executor_ref,
                launch_mode: row.launch_mode,
                current_site_id: row.current_site_id,
                origin_site_id: row.origin_site_id,
                upstream_thread_id: row.upstream_thread_id,
                successor_thread_id,
                requested_by: row.requested_by,
                project_root: row.project_root,
                project_authority: Some(row.project_authority),
                lifecycle_authority: runtime
                    .launch_metadata
                    .as_ref()
                    .map(|metadata| metadata.lifecycle_authority())
                    .transpose()?
                    .flatten(),
                admitted_launch_capsule_hash: row.admitted_launch_capsule_hash,
                created_at: row.created_at,
                updated_at: row.updated_at,
                started_at: row.started_at,
                finished_at: row.finished_at,

                runtime,
            });
        }
        Ok(details)
    }

    pub fn active_thread_count(&self) -> Result<i64> {
        let g = self.lock()?;
        queries::active_thread_count(g.state_db.projection())
    }

    pub fn wait_for_project_authority(
        &self,
        thread_id: &str,
        reason: &str,
        detail: &str,
        now_ms: i64,
        deadline_at_ms: i64,
    ) -> Result<runtime_db::RecoveryWaitDisposition> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let result = g.runtime_db.wait_for_project_authority(
            thread_id,
            reason,
            detail,
            now_ms,
            deadline_at_ms,
        );
        drop(g);
        result
    }

    pub fn clear_recovery_wait(&self, thread_id: &str) -> Result<()> {
        let _permit = self.acquire_write_permit()?;
        let g = self.lock()?;
        let result = g.runtime_db.clear_recovery_wait(thread_id);
        drop(g);
        result
    }

    pub fn authoritative_result_project_snapshot(&self, thread_id: &str) -> Result<Option<String>> {
        let g = self.lock()?;
        Ok(g.state_db
            .get_thread(thread_id)?
            .and_then(|snapshot| snapshot.result_project_snapshot_hash))
    }

    /// Prove that an authoritative project snapshot still has its complete,
    /// canonical CAS closure under this store's pinned state generation.
    ///
    /// Startup repair uses this before reconnecting an operational session row
    /// to a snapshot already testified by the root thread chain. A hash-shaped
    /// SQLite value alone is never sufficient publication authority.
    pub fn verify_project_snapshot_closure(&self, snapshot_hash: &str) -> Result<()> {
        if !lillux::valid_hash(snapshot_hash) {
            bail!("project snapshot hash is not canonical");
        }
        let cas = self.state_authority.cas_store()?;
        ryeos_state::project_materialization::VerifiedProjectSnapshotClosure::load(
            &cas,
            snapshot_hash,
        )?;
        Ok(())
    }

    pub fn admitted_launch_capsule_hash(&self, thread_id: &str) -> Result<Option<String>> {
        let g = self.lock()?;
        Ok(g.state_db
            .get_thread(thread_id)?
            .and_then(|thread| thread.admitted_launch_capsule_hash))
    }

    /// Load the authoritative CAS-rooted launch capsule for an admitted
    /// thread. Operational SQLite metadata is deliberately not consulted.
    pub fn admitted_launch_capsule(
        &self,
        thread_id: &str,
    ) -> Result<Option<ryeos_state::objects::AdmittedLaunchCapsule>> {
        Ok(self
            .admitted_launch_capsule_with_coordinates(thread_id)?
            .map(|(_, _, capsule)| capsule))
    }

    /// Read one immutable admission coordinate while holding the short state
    /// lock, then verify its retained CAS closure outside that lock. The shared
    /// storage guard covers both steps so GC cannot retire the selected bytes.
    pub fn admitted_launch_capsule_with_coordinates(
        &self,
        thread_id: &str,
    ) -> Result<Option<(String, String, ryeos_state::objects::AdmittedLaunchCapsule)>> {
        let _guard = self.state_authority.acquire_shared_guard()?;
        let Some((chain_root_id, capsule_hash)) =
            self.admitted_launch_capsule_coordinate(thread_id)?
        else {
            return Ok(None);
        };
        let capsule = load_admitted_launch_capsule(
            &self.state_authority,
            &self.bundle_admission_trust,
            &capsule_hash,
        )?;
        Ok(Some((chain_root_id, capsule_hash, capsule)))
    }

    fn admitted_launch_capsule_coordinate(
        &self,
        thread_id: &str,
    ) -> Result<Option<(String, String)>> {
        let g = self.lock()?;
        let Some(snapshot) = g.state_db.get_thread(thread_id)? else {
            return Ok(None);
        };
        Ok(snapshot
            .admitted_launch_capsule_hash
            .map(|hash| (snapshot.chain_root_id, hash)))
    }

    /// Load and independently verify the exact root program retained by the
    /// thread's CAS-rooted admitted capsule. Only the subject and capsule hash
    /// cross this boundary; sealed invocation, capabilities, and closure stay
    /// private to execution recovery.
    pub fn admitted_program_evidence(
        &self,
        thread_id: &str,
    ) -> Result<Option<AdmittedProgramEvidence>> {
        Ok(self
            .admitted_execution_comparison_evidence(thread_id)?
            .map(|evidence| evidence.program))
    }

    /// Load the exact admitted program and its retained execution realization
    /// under one verification path. This is intentionally keyed by an
    /// already-authorized thread id; hashes are evidence identities, not
    /// lookup authority.
    pub fn admitted_execution_comparison_evidence(
        &self,
        thread_id: &str,
    ) -> Result<Option<AdmittedExecutionComparisonEvidence>> {
        let _guard = self.state_authority.acquire_shared_guard()?;
        let Some((_, capsule_hash)) = self.admitted_launch_capsule_coordinate(thread_id)? else {
            return Ok(None);
        };
        let (capsule, execution_realization) = load_admitted_launch_capsule_with_realization(
            &self.state_authority,
            &self.bundle_admission_trust,
            &capsule_hash,
        )?;
        capsule.validate()?;
        let request: crate::thread_lifecycle::SealedRootExecutionRequest =
            serde_json::from_value(capsule.sealed_invocation.clone())
                .context("decode admitted sealed invocation")?;
        if request.admitted_program_value()? != capsule.exact_program
            || request.admitted_program_hash()? != capsule.exact_program_hash
        {
            bail!("admitted sealed invocation contradicts its exact program projection");
        }
        let subject = request
            .admitted_program_subject()
            .context("verify exact admitted root subject")?;
        let resolution = request.admitted_effective_resolution()?.clone();
        let effective_definition_digest = request.effective_definition_digest().clone();
        Ok(Some(AdmittedExecutionComparisonEvidence {
            execution_realization_hash: capsule.execution_realization_hash.clone(),
            execution_realization,
            program: AdmittedProgramEvidence {
                admitted_launch_capsule_hash: capsule_hash,
                subject,
                effective_definition_digest,
                resolution,
            },
        }))
    }

    /// Compare a recovery attempt with the CAS-rooted artifact identity before
    /// any process is permitted to execute. Runtime SQLite metadata is an
    /// operational index; the signed thread snapshot and its capsule are the
    /// authority boundary.
    pub fn verify_admitted_artifact_identity(
        &self,
        thread_id: &str,
        attempted: &ryeos_state::objects::AdmittedLaunchArtifactIdentity,
    ) -> Result<()> {
        attempted.validate()?;
        let g = self.lock()?;
        let snapshot = g
            .state_db
            .get_thread(thread_id)?
            .ok_or_else(|| anyhow!("thread not found: {thread_id}"))?;
        let capsule_hash = snapshot
            .admitted_launch_capsule_hash
            .as_deref()
            .ok_or_else(|| {
                anyhow!("thread {thread_id} has no authoritative admitted launch capsule")
            })?;
        let capsule = load_admitted_launch_capsule(
            &self.state_authority,
            &self.bundle_admission_trust,
            capsule_hash,
        )?;
        if &capsule.artifact_identity != attempted {
            bail!(
                "thread {thread_id} recovery artifact identity differs from its authoritative \
                 admitted capsule: admitted={:?}, attempted={attempted:?}",
                capsule.artifact_identity
            );
        }
        Ok(())
    }

