        // the Ready-only root birth mutation.
        store
            .authorize_thread_workspace_contact("T-workspace-root", &root_binding)
            .unwrap();
        let mut wrong_root = root_binding.clone();
        wrong_root.view_identity = "other-created-view".to_owned();
